KINDS[TYPES.throwable].prepare_grenades = function()
    local spec = KINDS[TYPES.throwable]
    spec.choices, spec.by_id, spec.by_entity = { { id = 0, label = 'Normal projectile' } }, {}, {}
    spec.known = {}   -- every donor, offered or not: a launcher still holding one reads as it (and resets)
    for id, hash in ipairs(spec.grenade_hashes) do
        local w = by_hash[hash]
        if w then spec.known[w.key] = id end
        if w and tables[TYPES.throwable] and tables[TYPES.throwable].index[w.key]
           and tables[TYPES.explosive] and tables[TYPES.explosive].index[w.key] then
            local shot = { id = id, key = w.key, label = w.name }
            spec.by_id[id], spec.by_entity[w.key] = shot, id
            spec.choices[#spec.choices + 1] = shot
        end
    end
end

KINDS[TYPES.throwable].read_entity = function(bytes)
    if bytes == string.rep('\0', 8) then return 0 end
    local spec = KINDS[TYPES.throwable]
    return bytes and (spec.by_entity and spec.by_entity[bytes] or spec.known and spec.known[bytes])
end

KINDS[TYPES.throwable].entity_bytes = function(id)
    if id == 0 then return string.rep('\0', 8) end
    local shot = KINDS[TYPES.throwable].by_id and KINDS[TYPES.throwable].by_id[id]
    return shot and shot.key
end

KINDS[TYPES.throwable].step = function(id, n)
    local list = KINDS[TYPES.throwable].choices or {}
    for at, shot in ipairs(list) do
        if shot.id == id then return list[math.max(1, math.min(#list, at + n))].id end
    end
    return id
end

local function add_row(weapon, section, id, label, storage, parts, min, max, small, big)
    local row = { section = section, id = id, label = label, storage = storage, parts = parts,
                  min = min, max = max, small = small, big = big }
    weapon.rows[#weapon.rows + 1] = row
    for _, part in ipairs(parts) do
        weapon.by_id[part.id] = part
        part.row = part.row or row
        part.field.users[#part.field.users + 1] = weapon
    end
    return row
end

local function part(id, kind, offset, storage, limit)
    return { id = id, field = field_at(kind, offset, storage, limit) }
end

-- An explosion's cone (ExplosionInfo +28; the Orbital Airburst's 27 degrees, the Cluster Bomb's 45; 0: all round):
-- a row where the game sets one. (No rows for +104 cloud time and the fire sizes: they did nothing in game.)
function MOD.explosion_extras(entry, section, prefix, xrow)
    if (default_of(field_at(T_EXPLOSION, xrow + 28, 'f32', 100000)) or 0) > 0 then
        add_row(entry, section, prefix .. 'cone', 'Cone angle (deg)', 'f32',
                { part(prefix .. 'cone', T_EXPLOSION, xrow + 28, 'f32', 100000) }, 0, 360, 1, 10)
    end
end

local function read_text(address)
    local bytes = address and address > 65536 and api.read(address, 96)
    local text = bytes and bytes:match('^([^%z]*)%z')
    if not text or #text < 3 or text:find('[^\32-\126]') then return nil end
    return text
end

-- Attachment items, per group table (`prepare`, once): their names, in table order, and lines: the
-- items of one weapon line, listed together, each starting at a new family ('Rifle 5,5x50mm.') or a
-- 'Standard' item. `words`: an item's deltas, 'component:offset' -> payload offset in the deltas, for
-- magazine (component 5) and heat (266) values and the weapon's stat bonuses (236, +956: 8 of type,
-- value); `mods`: where an item's stat modifiers are, type -> value (0 ergonomics, added; the rest
-- multiply: 1 sway, 2 / 4 recoil horizontal / vertical, 10 / 12 recoil climb, 14 / 16 spread, each followed by
-- its 'Alt' twin, 3 / 5 / ...: WeaponStatModifierType; MODS: their rows).
KINDS[TYPES.items].prepare = function(t)
    if t.lines then return end
    t.lines, t.order, t.names, t.labels = {}, {}, {}, {}
    local top, line, last = t.copies[1] + HEADER_BYTES, 0, nil
    for k = 0, (peek4(top + 8) or 0) - 1 do
        local r = 16 + k * 88
        local lo, hi = peek4(top + r), peek4(top + r + 4)
        local label = read_text(lo and hi and lo + hi * 4294967296) or ''
        local name = label:lower()
        local family = name:match('^([^%.]+)%.') or name:match('^(%S+ %S+)') or name
        if family ~= last or name:find('standard') then line = line + 1 end
        last, t.lines[r], t.order[#t.order + 1], t.names[r] = family, line, r, name
        t.labels[r] = label:gsub('%a+', function(word)
            if #word <= 2 or word ~= word:upper() or word:find('^MK') then return word end
            return word:sub(1, 1) .. word:sub(2):lower()
        end)
    end
end

KINDS[TYPES.items].find = function(id)
    for _, group in ipairs(id and id ~= 0 and KINDS[TYPES.items].list or {}) do
        local t = tables[group]
        if t and t.index[id] then KINDS[TYPES.items].prepare(t); return t, t.index[id] end
    end
end

-- Game build 25988413 (2026-10-20) renumbered the components (weapon 236 -> 239, heat 266 -> 269, reload
-- 113 -> 114, projectile 321 -> 324) and moved the weapon's stat bonuses 8 bytes on (its records grew): `words`
-- names them as before.
KINDS[TYPES.items].RENUMBERED = { [239] = 236, [269] = 266, [114] = 113, [324] = 321,
                                  [236] = false, [266] = false, [113] = false, [321] = false }
KINDS[TYPES.items].words = function(t, r)
    local deltas, at, out = tables[TYPES.deltas], KINDS[TYPES.deltas].layout, {}
    local renumbered = KINDS[T_WEAPON].stride == 1240 and KINDS[TYPES.items].RENUMBERED
    local slot = deltas and at and deltas.index[api.read(t.copies[1] + HEADER_BYTES + r + 32, 8) or '']
    if not slot then return out end
    local d = deltas.copies[1] + HEADER_BYTES
    local count, first = peek4(d + at[1] + slot * 8), peek4(d + at[1] + slot * 8 + 4)
    for c = first or 0, (first or 0) + (count or 0) - 1 do
        local comp = peek4(d + at[2] + c * 12)
        if renumbered and renumbered[comp] ~= nil then comp = renumbered[comp] end
        if comp == 5 or comp == 266 or comp == 236 or comp == 113 then
            local fd, nd = peek4(d + at[2] + c * 12 + 4), peek4(d + at[2] + c * 12 + 8)
            for x = fd, fd + nd - 1 do
                local offset, size, data = peek4(d + at[3] + x * 12), peek4(d + at[3] + x * 12 + 4), peek4(d + at[3] + x * 12 + 8)
                if renumbered and comp == 236 and offset >= 488 then offset = offset - 8 end
                for w = 0, size - 4, 4 do
                    local o = offset + w   -- the weapon's: stat bonuses (+956), and an optic's zoom (+116), follow speed (+316) and zeroing (+340)
                    if (comp ~= 236 or (o >= 956 and o < 1020) or (o >= 116 and o <= 124) or (o >= 316 and o <= 324) or (o >= 340 and o <= 348))
                       and (comp ~= 113 or o == 56) then
                        out[comp .. ':' .. (offset + w)] = at[4] + data + w
                    end
                end
            end
        end
    end
    return out
end

KINDS[TYPES.items].mods = function(words)
    local d, out = tables[TYPES.deltas].copies[1] + HEADER_BYTES, {}
    for e = 0, 7 do
        local kind, value = words['236:' .. (956 + e * 8)], words['236:' .. (960 + e * 8)]
        local type = kind and value and peek4(d + kind)
        if type and type < 18 and not out[type] then out[type] = value end
    end
    return out
end

KINDS[TYPES.items].MODS = {
    { 0, 'ergonomics', 'Ergonomics bonus', -100, 100, 1, 5 },
    { 1, 'sway', 'Sway multiplier', 0, 50, 0.05, 0.25 },
    { 2, 'recoil_h', 'Recoil multiplier (horizontal)', 0, 50, 0.05, 0.25 },
    { 4, 'recoil_v', 'Recoil multiplier (vertical)', 0, 50, 0.05, 0.25 },
    { 10, 'climb_h', 'Climb multiplier (horizontal)', 0, 50, 0.05, 0.25 },
    { 12, 'climb_v', 'Climb multiplier (vertical)', 0, 50, 0.05, 0.25 },
    { 14, 'spread_h', 'Spread multiplier (horizontal)', 0, 50, 0.05, 0.25 },
    { 16, 'spread_v', 'Spread multiplier (vertical)', 0, 50, 0.05, 0.25 },
}

-- An attachment's stat modifier rows on `entry` (`mods`: type -> where its value is in the deltas), ids
-- `pre` .. stat. A multiplier's 'Alt' twin (the next type: recoil, climb and spread have one) moves with it.
KINDS[TYPES.items].mod_rows = function(entry, section, pre, mods)
    for _, m in ipairs(KINDS[TYPES.items].MODS) do
        local offset = mods[m[1]]
        if offset then
            local f = field_at(TYPES.deltas, offset, 'f32', 1000)
            f.signed = m[4] < 0
            local parts = { { id = pre .. m[2], field = f } }
            local alt = m[1] >= 2 and mods[m[1] + 1]
            if alt then parts[2] = { id = pre .. m[2] .. '_alt', field = field_at(TYPES.deltas, alt, 'f32', 1000) } end
            add_row(entry, section, pre .. m[2], m[3], 'f32', parts, m[4], m[5], m[6], m[7])
        end
    end
end

-- The projectile a weapon's default attachments give its fire mode (+0), when they set one (the P-2
-- Peacemaker's and P-19 Redeemer's ammo type): component 321, offset 0, 4 bytes; the last slot wins.
-- Also returns where that value sits in the deltas (payload offset).
KINDS[TYPES.custom].projectile = function(key)
    local custom, spec, deltas, at = tables[TYPES.custom], KINDS[TYPES.items], tables[TYPES.deltas], KINDS[TYPES.deltas].layout
    local row = custom and deltas and at and custom.index[key]
    if not row then return nil end
    local base, d, out, out_at = custom.copies[1] + HEADER_BYTES + row, deltas.copies[1] + HEADER_BYTES, nil, nil
    local renumbered = KINDS[T_WEAPON].stride == 1240 and spec.RENUMBERED
    for s = 0, 8 do
        local t, r = spec.find(peek4(base + s * 8 + 4))
        local slot = t and deltas.index[api.read(t.copies[1] + HEADER_BYTES + r + 32, 8) or '']
        if slot then
            local count, first = peek4(d + at[1] + slot * 8) or 0, peek4(d + at[1] + slot * 8 + 4) or 0
            local value, value_at = nil, nil
            for c = first, first + count - 1 do
                local comp = peek4(d + at[2] + c * 12)
                if renumbered and renumbered[comp] ~= nil then comp = renumbered[comp] end
                if not value and comp == 321 then
                    local fd, nd = peek4(d + at[2] + c * 12 + 4) or 0, peek4(d + at[2] + c * 12 + 8) or 0
                    for x = fd, fd + nd - 1 do
                        if peek4(d + at[3] + x * 12) == 0 and peek4(d + at[3] + x * 12 + 4) == 4 then
                            value_at = at[4] + (peek4(d + at[3] + x * 12 + 8) or 0)
                            value = defaults[TYPES.deltas .. ':' .. value_at] or peek4(d + value_at)   -- the game's, not a swap
                            break
                        end
                    end
                end
            end
            if value and value > 0 then out, out_at = value, value_at end
        end
    end
    return out, out_at
end

-- Where a weapon's default attachments set its rounds feeds' projectiles (the SG-20 Halt's ammo type
-- and alternate ammo type, the SG-8 Punisher's and P-4 Senator's ammo type): a 4-byte delta at offset
-- 64 or 68 that holds the rounds record's own value there (`own`: offset -> projectile id), on any
-- component. Returns offset -> where each sits in the deltas (payload offset); the last slot wins.
KINDS[TYPES.custom].feeds = function(key, own)
    local custom, spec, deltas, at = tables[TYPES.custom], KINDS[TYPES.items], tables[TYPES.deltas], KINDS[TYPES.deltas].layout
    local row = custom and deltas and at and custom.index[key]
    local out = {}
    if not row then return out end
    local base, d = custom.copies[1] + HEADER_BYTES + row, deltas.copies[1] + HEADER_BYTES
    for s = 0, 8 do
        local t, r = spec.find(peek4(base + s * 8 + 4))
        local slot = t and deltas.index[api.read(t.copies[1] + HEADER_BYTES + r + 32, 8) or '']
        if slot then
            local count, first = peek4(d + at[1] + slot * 8) or 0, peek4(d + at[1] + slot * 8 + 4) or 0
            for c = first, first + count - 1 do
                local comp = peek4(d + at[2] + c * 12)
                local fd, nd = peek4(d + at[2] + c * 12 + 4) or 0, peek4(d + at[2] + c * 12 + 8) or 0
                for x = fd, fd + nd - 1 do
                    local offset, size = peek4(d + at[3] + x * 12) or 0, peek4(d + at[3] + x * 12 + 4) or 0
                    local data = at[4] + (peek4(d + at[3] + x * 12 + 8) or 0)
                    for w = 0, size - 4, 4 do
                        local value = defaults[TYPES.deltas .. ':' .. (data + w)] or peek4(d + data + w)
                        if own[offset + w] and value == own[offset + w] then out[offset + w] = data + w end
                    end
                end
            end
        end
    end
    return out
end

-- A weapon's magazine attachments (its slot 5 line: magazines, heatsinks, canisters) set magazine,
-- reload and heat values of their own over the weapon's, and modify its stats. For the weapon entity
-- `key`: { items = the line's attachments, the one it comes with first: { id, name, default (true for
-- that one), words ('component:offset' -> payload offset in the deltas of each value it sets), mods
-- (type -> its stat modifiers) } }. The weapon's line: the items listed with its default one.
-- Weapons whose other magazines are a line of their own: weapon -> that line's name. The AR-59
-- Suppressor comes with the Liberator's Extended; its Short and Drum are 'whisper' ones.
KINDS[TYPES.custom].LINES = { [hash_key('708EA298C82093D0')] = 'whisper rifle 5,5x50mm.' }

local function attachments(key)
    local cache = KINDS[TYPES.custom].cache
    if cache[key] ~= nil then return cache[key] end
    cache[key] = false
    local custom, spec = tables[TYPES.custom], KINDS[TYPES.items]
    local row = custom and tables[TYPES.deltas] and KINDS[TYPES.deltas].layout and custom.index[key]
    if not row then return false end
    local base, fitted = custom.copies[1] + HEADER_BYTES + row, {}
    for slot = 0, 9 do
        local kind = peek4(base + slot * 8)
        if kind then fitted[kind] = peek4(base + slot * 8 + 4) end
    end
    local out, t, mine = { items = {} }, spec.find(fitted[5])
    local also = KINDS[TYPES.custom].LINES[key]
    for _, r in ipairs(t and t.order or {}) do
        local listed = also and (r == mine or t.names[r]:sub(1, #also) == also) or (not also and t.lines[r] == t.lines[mine])
        if listed then
            local words = spec.words(t, r)
            local mods, any = spec.mods(words), false
            for word in pairs(words) do
                if word:find('^236:') then words[word] = nil else any = true end
            end
            if any or next(mods) then
                local top = t.copies[1] + HEADER_BYTES
                local item = { id = peek4(top + r + 8) or 0, name = MOD.item_names[peek4(top + r + 16) or 0] or t.labels[r],
                               default = r == mine, words = words, mods = mods }
                table.insert(out.items, item.default and 1 or #out.items + 1, item)
            end
        end
    end
    cache[key] = out
    return out
end

-- The Attachments tab: every optic, underbarrel and muzzle with an ergonomics, sway, recoil or spread modifier,
-- as an entry of its own (they apply to every weapon fitted with it). A Custom muzzle brake is one weapon's
-- own (the Penetrator's, the Adjudicator's, ...): named after the weapon that comes with it (no designation).
-- Ammunition types (slot 6, and 7: a weapon's alternate load) take the game's names (MOD.item_names, by the
-- item's text id at +16), else their own ('Shotgun 10g. Buckshot' -> '10g Buckshot').
KINDS[TYPES.items].build = function()
    for k = #weapons, 1, -1 do
        if weapons[k].attachment then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    local spec, list = KINDS[TYPES.items], {}
    local kinds = { [1] = 'Underbarrel', [2] = 'Optic', [4] = 'Muzzle', [6] = 'Ammunition', [7] = 'Alternate ammunition' }
    local custom, owner = tables[TYPES.custom], {}
    for _, w in ipairs(weapons) do
        local row = custom and w.key and not w.stratagem and custom.index[w.key]
        for slot = 0, row and 9 or -1 do
            local at = custom.copies[1] + HEADER_BYTES + row + slot * 8
            local id = peek4(at) == 4 and peek4(at + 4)
            if id and id ~= 0 and not owner[id] then owner[id] = w.name end
        end
    end
    for _, group in ipairs(spec.list) do
        local t = tables[group]
        spec.prepare(t)
        local top = t.copies[1] + HEADER_BYTES
        for _, r in ipairs(t.order) do
            local lo, hi, n = peek4(top + r + 48), peek4(top + r + 52), peek4(top + r + 56)
            local slot = lo and hi and n and n > 0 and n < 8 and peek4(lo + hi * 4294967296)
            local words = kinds[slot] and spec.words(t, r)
            local mods = words and spec.mods(words)
            local any = false
            for _, m in ipairs(spec.MODS) do any = any or (mods and mods[m[1]] ~= nil) end
            -- an optic's zoom levels and zeroing distances (the weapon's +116 / +340, three each)
            local scope = slot == 2 and words and (words['236:116'] or words['236:340']) and words
            any = any or scope ~= nil and scope ~= false
            local id = peek4(top + r + 8)
            local hash = any and string.format('FFFFFFFF%08X', id)
            local own = t.names[r]:find('custom') and owner[id]
            local name = own and ('Muzzle brake (' .. own:gsub('^%S*%d%S*%s+', '') .. ')') or t.labels[r]
            if slot == 6 or slot == 7 then
                name = MOD.item_names[peek4(top + r + 16) or 0]
                       or t.labels[r]:gsub(' [Aa]lternate$', ''):gsub('^%a[%a%-]* ', ''):gsub('%. ', ' ', 1)
                if slot == 7 then name = name .. ' (alternate)' end
            end
            if hash and not by_hash[hash] then
                list[#list + 1] = { name = name, slot = 'Attachments', hash = hash, rows = {}, by_id = {},
                                    note = own and ('Muzzle. Only the ' .. own .. ' comes with it.')
                                           or slot >= 6 and (kinds[slot] .. '. Its modifiers apply to every weapon loaded with it.')
                                           or (kinds[slot] .. '. Its modifiers apply to every weapon fitted with it.'),
                                    attachment = { mods = mods, scope = scope or nil, order = slot == 2 and 1 or slot == 1 and 2 or slot == 4 and 3 or 4,
                                                   texts = { peek4(top + r + 16), peek4(top + r + 12), peek4(top + r + 20) } } }
                by_hash[hash] = list[#list]
            end
        end
    end
    table.sort(list, function(a, b)
        if a.attachment.order ~= b.attachment.order then return a.attachment.order < b.attachment.order end
        return a.name:lower() < b.name:lower()
    end)
    for _, entry in ipairs(list) do weapons[#weapons + 1] = entry end
    log('attachments: ' .. #list .. ' with ergonomics, sway, recoil or spread modifiers listed')
end

KINDS[TYPES.passive].build = function()
    for k = #weapons, 1, -1 do
        if weapons[k].passive then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    -- the helldiver (offline), first on the Armors tab
    local A = KINDS[TYPES.avatar]
    local key = hash_key(A.ENTITY)
    if MOD.offline and not by_hash[A.ENTITY] and ((tables[TYPES.health] and tables[TYPES.health].index[key])
                                                  or (tables[TYPES.avatar] and tables[TYPES.avatar].index[key])) then
        by_hash[A.ENTITY] = { name = 'Helldiver', slot = 'Armors', hash = A.ENTITY, key = key, rows = {}, by_id = {}, player = true,
                              note = 'Every helldiver in your game. Restore the game\'s files before joining other players\' lobbies.' }
        weapons[#weapons + 1] = by_hash[A.ENTITY]
    end
    local spec, list = KINDS[TYPES.passive], {}
    for _, group in ipairs(spec.list) do
        local index = tables[group].index
        local hash = string.format('FFFFFFFE%08X', index.id)
        if index.id ~= 0 and not by_hash[hash] then
            list[#list + 1] = { name = spec.NAMES[index.id] or ('Passive ' .. index.id), slot = 'Armors', hash = hash,
                                key = hash_key(hash), rows = {}, by_id = {}, passive = group,
                                note = 'Shared by every armor with this passive. Multipliers: 1 = no change.' }
            by_hash[hash] = list[#list]
        end
    end
    table.sort(list, function(a, b) return a.name:lower() < b.name:lower() end)
    for _, entry in ipairs(list) do weapons[#weapons + 1] = entry end
    log('armor passives: ' .. #list .. ' listed')
end

-- Armor weight: one page on the Armors tab, a row per armor (every armor set of that name), its weight on every
-- piece of it (the torso's shown); speed and stamina follow it (tested in game, issue #89).
MOD.kits = { HASH = 'FFFFFFF900000001', PAGE = 'FFFFFFF8%08X', LOOK = 'FFFFFFF7%08X', MAX_PASSIVES = 14,
             NAMES = { [0] = 'Light', [1] = 'Medium', [2] = 'Heavy' } }
function MOD.kits.build()
    for k = #weapons, 1, -1 do
        if weapons[k].kits then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    local any = false
    for _, group in ipairs(KINDS[TYPES.kit].list) do any = any or #tables[group].index.pieces > 0 end
    if not any then return end
    by_hash[MOD.kits.HASH] = { name = 'Armor weight', slot = 'Armors', hash = MOD.kits.HASH, key = hash_key(MOD.kits.HASH),
                               rows = {}, by_id = {}, kits = true,
                               note = 'Light, medium or heavy, per armor (every armor set with that name).' }
    -- at the top of the Armors tab, below the Helldiver
    local at = #weapons + 1
    for k, w in ipairs(weapons) do if w.slot == 'Armors' then at = k + (w.player and 1 or 0); break end end
    table.insert(weapons, at, by_hash[MOD.kits.HASH])
    -- each armor its own page, between Armor weight and the passives
    local by_name, order, last = MOD.kits.named()
    for _, id in ipairs(order) do
        if MOD.kit_names[id] ~= '' then
            local hash = string.format(MOD.kits.PAGE, id)
            -- a few armors' variants differ: the page starts from the passive most of them have (not none, if it can)
            local seen, lead = {}, nil
            for _, kit in ipairs(by_name[id]) do
                local v = kit.index.passive
                seen[v] = (seen[v] or 0) + 1
                if not lead or (v ~= 0 and (lead == 0 or seen[v] > seen[lead])) then lead = v end
            end
            last = { name = MOD.kit_names[id], slot = 'Armors', hash = hash, key = hash_key(hash), rows = {}, by_id = {},
                     kits = 'passive', armor = id, default = lead ~= 0 and { lead } or {},
                     note = 'Every armor set with this name. Its passive text is shared by every armor with that passive.' }
            by_hash[hash] = last
            at = at + 1
            table.insert(weapons, at, last)
        end
    end
    MOD.kits.looks()
    MOD.kits.migrate()
end
-- Helmets, then capes: a page each (offline), only for its Name and Description boxes, after the passives. A helmet
-- named like an armor shares its texts, so its boxes are the armor's (same). MOD.kits.texts: every kit's name text
-- id -> its capitals and description ids.
function MOD.kits.looks()
    local host = rawget(_G, 'SHODAN_PHYSICS')
    local texts, list, seen, kinds = host and host.texts, {}, {}, { 'Helmet', 'Cape' }
    MOD.kits.texts = {}
    for _, group in ipairs(KINDS[TYPES.kit].list) do
        local k = tables[group].index
        local t = MOD.kits.texts[k.name] or { caps = {}, desc = {} }
        MOD.kits.texts[k.name] = t
        t.caps[k.caps] = true
        t.desc[k.desc] = true
        if MOD.offline and texts and texts[k.name] and texts[k.name] ~= '' and k.type ~= 0 and not seen[k.name] then
            seen[k.name] = true
            local hash = string.format(MOD.kits.LOOK, k.name)
            local kind = kinds[k.type] or 'Look'
            local same = by_hash[string.format(MOD.kits.PAGE, k.name)]
            list[#list + 1] = { name = kind .. ': ' .. texts[k.name], slot = 'Armors', hash = hash, key = hash_key(hash), rows = {},
                                by_id = {}, kits = 'look', look = k.name, look_kind = k.type, same = same,
                                note = same and 'Shares its name and description with the armor of this name: a change here changes both.'
                                       or 'Every ' .. kind:lower() .. ' with this name.' }
            by_hash[hash] = list[#list]
        end
    end
    table.sort(list, function(a, b)
        if a.look_kind ~= b.look_kind then return a.look_kind < b.look_kind end
        return a.name:lower() < b.name:lower()
    end)
    local at = #weapons + 1
    for k = #weapons, 1, -1 do if weapons[k].slot == 'Armors' then at = k + 1; break end end
    for k, entry in ipairs(list) do table.insert(weapons, at + k - 1, entry) end
end
-- which part of the Armors tab a page is in, nil on other tabs
function MOD.kits.part(w)
    return w.player and 1 or w.kits == true and 2 or w.armor and 3 or w.passive and 4 or w.look_kind and 4 + w.look_kind or nil
end
-- the armors in the game, by text id, and their ids by name
function MOD.kits.named()
    local by_name, order = {}, {}
    for _, group in ipairs(KINDS[TYPES.kit].list) do
        local index = tables[group].index
        if #index.pieces > 0 and MOD.kit_names and MOD.kit_names[index.name] then   -- (unnamed: not in the game yet)
            if not by_name[index.name] then by_name[index.name] = {}; order[#order + 1] = index.name end
            table.insert(by_name[index.name], { group = group, index = index })
        end
    end
    local function name_of(id) return MOD.kit_names[id] end
    table.sort(order, function(a, b) return name_of(a):lower() < name_of(b):lower() end)
    return by_name, order
end
function MOD.kits.resolve(entry)
    if entry.kits ~= true then return end
    local by_name, order = MOD.kits.named()
    local function name_of(id) return MOD.kit_names[id] end
    local rows = { {}, {}, {} }
    for _, id in ipairs(order) do
        local row_id, parts, first = string.format('weight_%08X', id), {}, nil
        for _, kit in ipairs(by_name[id]) do
            for _, piece in ipairs(kit.index.pieces) do
                local p = part(row_id .. '_' .. (#parts + 1), kit.group, piece.offset, 'u32', 2)
                if piece.torso and not first then first = #parts + 1 end
                parts[#parts + 1] = p
            end
        end
        if first then table.insert(parts, 1, table.remove(parts, first)) end
        parts[1].id = row_id
        local w, page = default_of(parts[1].field), by_hash[string.format(MOD.kits.PAGE, id)]
        if page then page.weight_field = parts[1].field end
        if w and rows[w + 1] then rows[w + 1][#rows[w + 1] + 1] = { row_id, name_of(id), parts } end
    end
    for w, list in ipairs(rows) do
        for _, r in ipairs(list) do
            local row = add_row(entry, MOD.kits.NAMES[w - 1] .. ' armor', r[1], r[2], 'u32', r[3], 0, 2, 1, 1)
            row.choice = 'weight'
            row.label_of = function() return r[2] .. ': ' .. (MOD.kits.NAMES[read_field(r[3][1].field) or -1] or '?') end
            row.note = '0 light, 1 medium, 2 heavy'
        end
    end
end

-- The helldiver: its health component (main health +0, each named zone's health +232; zones of 552 bytes from +520,
-- the name at +96) and its avatar's move info (MOVE: section, id, label, offset, max, small / big step).
KINDS[TYPES.avatar].ENTITY = '4D1C334D294DFA97'   -- content/fac_helldivers/cha_avatar/avatar_helldiver
KINDS[TYPES.avatar].ZONES = { [0x8C5570C9] = 'Head', [0xAA1DB0B0] = 'Body', [0x1880288E] = 'Left arm',
                              [0xB6F2BAF5] = 'Right arm', [0x64A3FA1D] = 'Left leg', [0x87B05FF4] = 'Right leg' }
KINDS[TYPES.avatar].MOVE = {
    { 'Movement', 'walk', 'Walk speed (m/s)', 12, 50, 0.1, 0.5 }, { 'Movement', 'jog', 'Jog speed (m/s)', 16, 50, 0.1, 0.5 },
    { 'Movement', 'sprint', 'Sprint speed (m/s)', 20, 50, 0.1, 0.5 },
    { 'Movement', 'sprint_exerted', 'Sprint speed, out of stamina (m/s)', 24, 50, 0.1, 0.5 },
    { 'Movement', 'aim', 'Speed while aiming (m/s)', 8, 50, 0.1, 0.5 },
    { 'Movement', 'crouch_walk', 'Crouched walk speed (m/s)', 32, 50, 0.1, 0.5 },
    { 'Movement', 'crouch_jog', 'Crouched jog speed (m/s)', 36, 50, 0.1, 0.5 },
    { 'Movement', 'crouch_sprint', 'Crouched sprint speed (m/s)', 40, 50, 0.1, 0.5 },
    { 'Movement', 'crouch_aim', 'Crouched speed while aiming (m/s)', 28, 50, 0.1, 0.5 },
    { 'Movement', 'prone', 'Prone speed (m/s)', 44, 50, 0.1, 0.5 }, { 'Movement', 'swim', 'Swim speed (m/s)', 48, 50, 0.1, 0.5 },
    { 'Movement', 'reversing', 'Walking backwards (multiplier)', 4, 10, 0.05, 0.25 },
    { 'Stamina', 'sprint_drain', 'Sprinting empties it in (s)', 52, 3600, 1, 5 },
    { 'Stamina', 'jog_drain', 'Jogging empties it in (s)', 56, 3600, 1, 10 },
    { 'Stamina', 'recover_stand', 'Refills standing in (s)', 60, 600, 0.5, 2 },
    { 'Stamina', 'recover_crouch', 'Refills crouched in (s)', 64, 600, 0.5, 2 },
    { 'Stamina', 'recover_prone', 'Refills prone in (s)', 68, 600, 0.5, 2 },
    { 'Stamina', 'recover_delay', 'Refill starts after (s)', 72, 60, 0.1, 0.5 },
    { 'Stamina', 'cost_jump', 'Jump cost (share of stamina)', 76, 1, 0.05, 0.1 },
    { 'Stamina', 'cost_dive', 'Dive cost (share of stamina)', 80, 1, 0.05, 0.1 },
    -- (Consistent Vaulting's fields, via SHODAN Offline Integration)
    { 'Climbing and sliding', 'slide_enter', 'Slope slide starts at (degrees)', 152, 89, 1, 5 },
    { 'Climbing and sliding', 'slide_exit', 'Slope slide ends at (degrees)', 172, 89, 1, 5 },
    { 'Climbing and sliding', 'climb_height', 'Highest ledge it climbs (m)', 260, 10, 0.05, 0.25 } }
-- the player hellpods (initial drop, reinforcements): entity, label
KINDS[TYPES.avatar].PODS = { { 'E58163E71928D3E2', 'Initial drop' }, { 'EF9EB729A9D6D849', 'Reinforcement' } }
KINDS[TYPES.avatar].resolve = function(entry)
    local A, ht, at = KINDS[TYPES.avatar], tables[TYPES.health], tables[TYPES.avatar]
    local h = ht and ht.index[entry.key]
    if h then
        add_row(entry, 'Health', 'health', 'Health', 'u32', { part('health', TYPES.health, h, 'u32', 10000000) }, 1, 100000, 5, 25)
        -- Native Helldiver HealthComponentData regeneration field (+4).
        add_row(entry, 'Health', 'health_regen', 'Regeneration (health/s)', 'f32',
                { part('health_regen', TYPES.health, h + 4, 'f32', 1000000) }, 0, 100, 1, 5)
        local top = ht.copies[1] + HEADER_BYTES
        for z = 0, 37 do
            local base = h + 520 + z * 552
            local label = A.ZONES[peek4(top + base + 96) or 0]
            if label then
                local id = 'zone' .. z .. '_health'
                add_row(entry, 'Body parts', id, label .. ' health', 'u32',
                        { part(id, TYPES.health, base + 232, 'u32', 10000000) }, 1, 100000, 5, 25)
                -- +248 how much of a hit passes to your health: 1.5 on the head (SHODAN Offline Integration)
                if label == 'Head' then
                    add_row(entry, 'Body parts', 'zone' .. z .. '_to_body', 'Head hits: damage to your health (x)', 'f32',
                            { part('zone' .. z .. '_to_body', TYPES.health, base + 248, 'f32', 100) }, 0, 100, 0.05, 0.25).tip =
                        { 'A hit to the head costs this many times its damage. 1 = the same as the body.' }
                end
            end
        end
    end
    local m = at and at.index[entry.key]
    if m then
        for _, f in ipairs(A.MOVE) do
            add_row(entry, f[1], f[2], f[3], 'f32', { part(f[2], TYPES.avatar, m + f[4], 'f32', 100000) }, 0, f[5], f[6], f[7])
        end
    end
    -- suppression by enemy fire (danger sensor: +0 cap, +4 radius, +8 near misses count)
    local st = tables[TYPES.danger]
    local s = st and st.index[entry.key]
    if s then
        add_row(entry, 'Suppression', 'danger_radius', 'Enemy shots count within (m)', 'f32',
                { part('danger_radius', TYPES.danger, s + 4, 'f32', 1000) }, 0, 100, 0.5, 2).note = 'how close enemy fire must pass to shake your aim; 0: never'
        add_row(entry, 'Suppression', 'danger_max', 'Most suppression', 'f32',
                { part('danger_max', TYPES.danger, s, 'f32', 1000) }, 0, 1000, 1, 5).note = 'how far it can build up; 0: none'
        add_row(entry, 'Suppression', 'danger_miss', 'Near misses suppress you', 'flag',
                { part('danger_miss', TYPES.danger, s + 8, 'flag', 1) }, 0, 1, 1, 1)
    end
    -- water (Shallow Water Diving's fields): the two depth offsets are below the water line (negative)
    local dt = tables[TYPES.drown]
    local d = dt and dt.index[entry.key]
    if d then
        for _, f in ipairs({ { 'drown_depth', 'Drowning depth offset (m)', 4, -5, 0 }, { 'float_depth', 'Floating depth offset (m)', 8, -5, 0 },
                             { 'drown_time', 'Time before drowning (s)', 12, 0.1, 3600 } }) do
            local p = part(f[1], TYPES.drown, d + f[3], 'f32', 3600)
            p.field.signed = f[4] < 0 or nil   -- (before the first read: negative values are refused otherwise)
            local v = default_of(p.field)
            if v and v >= f[4] and v <= f[5] then
                local r = add_row(entry, 'Water', f[1], f[2], 'f32', { p }, f[4], f[5], 0.1, f[3] == 12 and 5 or 0.5)
                if f[3] == 4 then r.note = 'lower (more negative): you go deeper before drowning starts' end
            end
        end
    end
    -- the hellpods' descent (Hellpod Control's fields: higher and slower gives more time to steer)
    local hp = tables[TYPES.hellpod]
    for _, pod in ipairs(hp and A.PODS or {}) do
        local at = hp.index[hash_key(pod[1])]
        if at then
            local section = 'Hellpod: ' .. pod[2]:lower()
            local prefix = 'pod' .. (pod[2] == 'Initial drop' and 1 or 2) .. '_'
            for _, f in ipairs({ { 'height', 'Spawn height (m)', 8, 10000, 10, 50 }, { 'speed', 'Starting speed (m/s)', 20, 10000, 5, 25 },
                                 { 'brake_height', 'Braking height (m)', 24, 10000, 5, 25 }, { 'brake_speed', 'Braking speed (m/s)', 28, 10000, 1, 5 },
                                 { 'brake_time', 'Braking time (s)', 32, 60, 0.1, 0.5 } }) do
                local p = part(prefix .. f[1], TYPES.hellpod, at + f[3], 'f32', 100000)
                local v = default_of(p.field)
                if v and v == v and math.abs(v) < 100000 then
                    p.field.signed = v < 0 or nil
                    add_row(entry, section, prefix .. f[1], f[2], 'f32', { p }, v < 0 and -f[4] or 0, f[4], f[5], f[6])
                end
            end
        end
    end
    -- every hand-aimed weapon's sway at once (MOD.enemy.faction_refresh writes it); only its own value is saved
    local sway = { id = 'weapon_sway', field = field_at(0, 'helldiver:weapon_sway', 'virtual', 1000) }
    sway.field.default = 1
    add_row(entry, 'Weapons', 'weapon_sway', 'Weapon sway (x)', 'f32', { sway }, 0, 100, 0.05, 0.25).tip =
        { 'Every weapon you aim yourself, emplacements and vehicle guns too: the game\'s sway times this. 0 = no sway.',
          'A weapon whose own Sway multiplier you changed keeps it. Sway this row changes shows in blue.' }
    -- melee strikes: damage rows DamageInfoType_Ability_Avatar_Melee (560) and _Melee_Bayonet (568), shared by every weapon
    MOD.melee_rows(entry, 560, 'Melee', 'melee_')
    MOD.melee_rows(entry, 568, 'Bayonet melee', 'bayonet_')
end

-- A melee strike's damage row (a DamageInfoType id) on a page: the Helldiver's, and the bayonet guns' (MOD.BAYONET,
-- the same shared row). Returns its first row.
MOD.BAYONET = { ['R-2124 Constitution'] = true, ['SG-97 Sweeper'] = true, ['R-2 Amendment'] = true }
function MOD.melee_rows(entry, id, section, prefix)
    local drow = tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    local first = nil
    for _, s in ipairs(drow and { { 'damage', 'Damage', 4, 1, 10 }, { 'durable', 'Durable damage', 8, 1, 10 },
                                  { 'ap', 'Armor penetration', 12, 1, 1 }, { 'stagger', 'Stagger force', 32, 1, 10 },
                                  { 'push', 'Push force', 36, 1, 10 } } or {}) do
        local r = add_row(entry, section, prefix .. s[1], s[2], 'u32', { part(prefix .. s[1], T_DAMAGE, drow + s[3], 'u32', 1000000) }, 0,
                          s[1] == 'ap' and 10 or 100000, s[4], s[5])
        first = first or r
    end
    return first
end

-- A passive's rows: each modifier (named, or by its id), then its weapon stat modifiers.
KINDS[TYPES.passive].resolve = function(entry)
    local spec, t = KINDS[TYPES.passive], tables[entry.passive]
    if not t then return end
    --        type: min, max, small step, big step
    local RANGE = { [0] = { 0, 10, 1, 1 }, [1] = { 0, 1000, 0.5, 5 }, [2] = { 0, 10, 0.05, 0.25 }, [3] = { 0, 600, 0.5, 2 } }
    local joined = {}   -- a modifier the game describes with another -> that one's row
    for k, m in ipairs(t.index.mods) do
        local r = RANGE[m.type]
        if m.id ~= 0 and r then
            local id = string.format('mod_%08X', m.id)
            if entry.by_id[id] then id = id .. '_' .. k end
            local p, with = part(id, entry.passive, m.offset, 'f32', 100000), spec.JOINED[m.id]
            local row = with and joined[with .. '_' .. m.type]
            if row then
                row.parts[#row.parts + 1] = p
                entry.by_id[id], p.row = p, row
                p.field.users[#p.field.users + 1] = entry
            else
                row = add_row(entry, 'Passive', id, spec.MODS[with or m.id] or string.format('Modifier %08X', m.id), 'f32',
                              { p }, r[1], r[2], r[3], r[4])
                if with then joined[with .. '_' .. m.type] = row end
            end
        end
    end
    for _, st in ipairs(t.index.stats) do
        local id = 'stat_' .. st.stat
        if not entry.by_id[id] then
            add_row(entry, 'Weapon stats', id, spec.STATS[st.stat] or ('Stat ' .. st.stat), 'f32',
                    { part(id, entry.passive, st.offset, 'f32', 100000) }, 0, 10, 0.05, 0.25)
        end
    end
end

-- Adds a damage row's stats (the first `count`, default all) to `entry`, ids `prefix` .. stat id.
-- `what` names the damage / durable rows ('Explosion' -> 'Explosion damage'); `strike`: steps of 10 / 100 for those.
local function damage_rows(entry, section, prefix, drow, what, count, strike)
    local first
    for k = 1, count or 9 do
        local r = KINDS[T_DAMAGE].rows[k]
        local id, named = prefix .. r[1], k <= 2
        local row = add_row(entry, section, id, (named and what) and (what .. ' ' .. r[2]:lower()) or r[2], 'u32',
                            { part(id, T_DAMAGE, drow + r[3], 'u32', 1000000) }, 0, r[4],
                            (named and strike) and 10 or r[5], (named and strike) and 100 or r[6])
        first = first or row
    end
    return first
end

-- Adds the rows of the gun whose entity hash is `key` (8 bytes) to `weapon` (a weapon, or a
-- stratagem whose payload is a gun: sentries, emplacements).
-- The status effects damage row `drow` applies that deal damage (fire from flamers, incendiary rounds
-- and grenades, gas) or stun: how much each hit applies (`per`: 'hit', 'blast'), then the status's damage
-- row (none for a stun) and duration (every source of that status shares them). Ids: `prefix` .. 'status<type>_' .. stat.
-- The status effects a hit can be given (issue #24): the ones player weapons already apply, by this build's type
-- number (StatusEffectSettings rows, told apart by their durations), with a usual strength (written when an empty
-- slot gets one). DamageInfo +44 + 8n: 4 slots of { type u32, strength f32 }, packed from the first.
MOD.status = { choices = {
    { 5, 'Burning', 3 }, { 33, 'Heavy burning', 50 }, { 6, 'Fire panic', 3 }, { 68, 'Flamethrower slow', 1 },
    { 38, 'Stun (small)', 10 }, { 39, 'Stun (medium)', 50 }, { 40, 'Stun (large)', 25 },
    { 43, 'Gas', 100 }, { 45, 'Gas confusion', 100 }, { 44, 'Gas (Sterilizer)', 1 }, { 46, 'Gas confusion (Sterilizer)', 1 },
}, by = {} }
-- more, from SHODAN Offline Integration (HD2Runtime's catalogue; this build's numbers, checked against the records'
-- damage and durations): statuses enemies and hazards apply; a player weapon may or may not pass them on
for _, c in ipairs({ { 2, 'Bleed', 10 }, { 1, 'Blind', 10 }, { 3, 'Deaf', 10 }, { 4, 'Confusion', 100 }, { 7, 'Lava', 10 },
                     { 8, 'Slowed', 10 }, { 9, 'Rooted', 10 }, { 10, 'Acid splash', 10 }, { 11, 'Acid', 10 },
                     { 12, 'Thermite', 10 }, { 13, 'Cyborg fire', 10 }, { 14, 'Choked', 100 }, { 34, 'Radiation (light)', 10 },
                     { 35, 'Radiation (heavy)', 10 }, { 36, 'Electric', 10 }, { 41, 'Stun (massive)', 25 },
                     { 42, 'Stun (Illuminate)', 25 }, { 47, 'Inverted aim assist', 10 }, { 53, 'Tremor', 10 },
                     { 56, 'Acid storm', 10 }, { 58, 'Tornado stun', 25 }, { 69, 'Gloom', 10 }, { 71, 'Poison', 10 } }) do
    MOD.status.choices[#MOD.status.choices + 1] = { c[1], c[2] .. ' (experimental)', c[3] }
end
for n, c in ipairs(MOD.status.choices) do MOD.status.by[c[1]] = { n = n, type = c[1], name = c[2], strength = c[3] } end
function MOD.status.name(kind)
    if kind == 0 then return 'none' end
    return MOD.status.by[kind] and MOD.status.by[kind].name or KINDS[T_STATUS].stuns[kind] or ('status ' .. kind)
end
-- the next / previous choice (n steps; 0: none, before the first)
function MOD.status.step(current, n)
    local at = MOD.status.by[current] and MOD.status.by[current].n or 0
    local to = math.max(0, math.min(#MOD.status.choices, at + n))
    return to == 0 and 0 or MOD.status.choices[to][1]
end
-- why slot `row.slot` of `row.drow` can't take `target` (a gap in the slots, a status not offered), or nil
function MOD.status.refused(row, target)
    if target ~= 0 and not MOD.status.by[target] and target ~= default_of(row.parts[1].field) then
        return 'Status effect ' .. tostring(target) .. ' is not one of the choices.'
    end
    if target ~= 0 and not (tables[T_STATUS] and tables[T_STATUS].index[target]) then
        return 'Status effect ' .. tostring(target) .. ' is not in this game build.'
    end
    local function at(i) return i >= 0 and i <= 3 and read_field(field_at(T_DAMAGE, row.drow + 44 + i * 8, 'u32', 100000)) or 0 end
    if target ~= 0 and row.slot > 0 and at(row.slot - 1) == 0 then
        return 'Give status effect ' .. row.slot .. ' first (the game reads them in order).'
    end
    if target == 0 and at(row.slot + 1) ~= 0 then
        return 'Clear status effect ' .. (row.slot + 2) .. ' first (the game reads them in order).'
    end
end

local function status_rows(entry, section, prefix, drow, per)
    local strength_of = {}   -- slot -> its named strength row
    for i = 0, 3 do
        local kind = read_field(field_at(T_DAMAGE, drow + 44 + i * 8, 'u32', 100000))
        if not kind or kind == 0 then break end
        local srow = tables[T_STATUS] and tables[T_STATUS].index[kind]
        local sid = srow and read_field(field_at(T_STATUS, srow + 44, 'u32', 100000))
        local qrow = sid and sid > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[sid]
        local stun = srow and not qrow and KINDS[T_STATUS].stuns[kind]
        if qrow or stun then
            local name, key = stun or KINDS[T_STATUS].names[kind] or ('Status ' .. kind), prefix .. 'status' .. kind
            strength_of[i] = add_row(entry, section, key .. '_strength', name .. ' applied per ' .. per, 'f32',
                                     { part(key .. '_strength', T_DAMAGE, drow + 48 + i * 8, 'f32', 100000) }, 0, 1000, 0.1, 1)
            local first = qrow and damage_rows(entry, name, key .. '_', qrow, name, 6)   -- no forces: a status has none
            local duration = add_row(entry, name, key .. '_duration', name .. ' duration (s)', 'f32',
                                     { part(key .. '_duration', T_STATUS, srow + 40, 'f32', 100000) }, 0, 600, 0.5, 5)
            local by = qrow and '(other weapons, strikes, hazards, enemies)' or '(other weapons, grenades, strikes)'
            ;(first or duration).note = 'every ' .. name:lower() .. ' source shares ' .. (qrow and 'these ' or 'this ') .. by
        end
    end
    -- which status each of the four slots applies (SHODAN Offline Integration: all four shown, filled in order)
    local own = section == 'Damage' and 'Status effects' or ('Status effects (' .. section .. ')')
    for i = 0, 3 do
        local id = prefix .. 'slot' .. (i + 1)
        local row = add_row(entry, own, id, 'Status effect ' .. (i + 1) .. ' (choice)', 'u32',
                            { part(id, T_DAMAGE, drow + 44 + i * 8, 'u32', 100000) }, 0, 100000, 1, 1)
        row.choice, row.drow, row.slot = 'status', drow, i
        row.label_of = function() return 'Applies: ' .. MOD.status.name(read_field(row.parts[1].field) or 0) end
        if i == 0 then row.note = 'what each hit applies; the slots go in order' end
        row.strength = strength_of[i] or add_row(entry, own, id .. '_strength', 'Status effect ' .. (i + 1) .. ' strength per ' .. per,
                                                 'f32', { part(id .. '_strength', T_DAMAGE, drow + 48 + i * 8, 'f32', 100000) }, 0, 1000, 0.1, 1)
    end
end

-- A charge weapon's shots, when its stages name projectiles (the plasma weapons: Loyalist and
-- Purifier fire one projectile uncharged and another charged, the Epoch one at partial and another
-- at full charge; a stage without one fires `fired`, the fire mode's). In stage order: { id, prow,
-- stage, last (stages it fires at), name, prefix: '' for the fire mode's projectile, so its ids stay
-- those of a plain weapon, else 'c<stage>_' }. nil when every stage fires the fire mode's projectile.
KINDS[TYPES.charge].shots = function(at, fired)
    local list, by = {}, {}
    for s = 1, 3 do
        local id = default_of(field_at(TYPES.charge, at + (s - 1) * 24 + 4, 'u32', 100000))
        if id == 0 then id = fired end
        local prow = id and id > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[id]
        if prow then
            if not by[id] then by[id] = { id = id, prow = prow, stage = s }; list[#list + 1] = by[id] end
            by[id].last = s
        end
    end
    if #list == 0 or (#list == 1 and list[1].id == fired) then return nil end
    -- a first stage that fires at once (0.01 s) is the uncharged shot
    local quick = (default_of(field_at(TYPES.charge, at, 'f32', 100000)) or 1) < 0.1
    local names = #list == 2 and (quick and { 'Uncharged', 'Charged' } or { 'Partial charge', 'Full charge' })
    for k, shot in ipairs(list) do
        shot.name = names and names[k] or (#list == 1 and 'Charged' or ('Stage ' .. shot.stage))
        shot.prefix = shot.id == fired and '' or ('c' .. shot.stage .. '_')
    end
    return list
end

local function resolve_gun(weapon, key)
    local function record(kind)
        local entry = tables[kind]
        return entry and entry.index[key]
    end
    -- (from LovedeHua's fork) flame and gas weapons (SprayWeaponComponentData): +0 warm-up, +4 how long the
    -- pilot light stays lit, +16 hit radius, +192 ammo per puff, +208 sets off mines
    local spray = record(T_SPRAY)
    for _, f in ipairs(spray and {
        { 'spray_warmup', 'Warm-up before it sprays (s)', 0, 'f32', 10, 0.1, 0.5 },
        { 'spray_cooldown', 'Pilot light goes out after (s)', 4, 'f32', 60, 0.5, 2 },
        { 'spray_radius', 'Hit radius (m)', 16, 'f32', 10, 0.05, 0.25 },
        { 'spray_cost', 'Ammo per puff', 192, 'u32', 100, 1, 5 },
        { 'spray_mines', 'Sets off mines', 208, 'flag', 1, 1, 1 },
    } or {}) do
        add_row(weapon, 'Spray', f[1], f[2], f[4], { part(f[1], T_SPRAY, spray + f[3], f[4], 100000) }, 0, f[5], f[6], f[7])
    end
    -- (from LovedeHua's fork) the guided weapons' lock-on range: their own SensorComponent +0, gated on its
    -- stock value so a shifted record gets no row
    local sight = ({ ['25AA2FD4643CF4EE'] = 300, ['CC786F6491FE7E65'] = 300,   -- FAF-14 Spear, StA-X3 W.A.S.P.
                     ['CF8934FF6567A42D'] = 60, ['14D5D4506056C7A4'] = 100 })[weapon.key == key and weapon.hash or '']   -- P-92 Warrant, P-33 Missile Pistol
    local at = sight and record(TYPES.sensor)
    if at and math.abs((default_of(field_at(TYPES.sensor, at, 'f32', 10000)) or 0) - sight) < 0.01 then
        add_row(weapon, 'Target lock', 'lock_range', 'Lock-on range (m)', 'f32',
                { part('lock_range', TYPES.sensor, at, 'f32', 10000) }, 1, 2000, 10, 100)
    end
    -- its magazine attachments, each with rows of its own (KINDS[TYPES.items].item_rows); a magazine /
    -- reload / heat value of the weapon's own record ('component:offset') has a row while one of them
    -- leaves it to the record (or it has none)
    local ok, links = pcall(attachments, key)
    if not ok then log('attachments of ' .. weapon.name .. ': ' .. tostring(links)) end
    local items = ok and weapon.key == key and links and links.items or {}
    local function kept(word)
        for _, item in ipairs(items) do
            if not item.words[word] then return true end
        end
        return #items == 0
    end
    -- the projectile it fires: the rounds record's (+64), else its default ammo type's (an attachment
    -- delta on the fire mode's +0, put there when the weapon spawns: Peacemaker, Redeemer), else the fire
    -- mode's (+0). Read as the game had them (the Projectile swap row writes them all; the stat rows stay
    -- the weapon's own). `sources`: those fields, with the charge stages' (below), for that row.
    local sources = {}
    local function source(id, kind, offset, always)
        local f = field_at(kind, offset, 'u32', 100000)
        local own = default_of(f)
        if own and (own > 0 or always) then sources[#sources + 1] = { id = id, field = f, own = own } end
        return own
    end
    local projectile = nil
    local rounds, fire = record(T_ROUNDS), record(T_FIRE)
    if rounds then projectile = source('proj_rounds', T_ROUNDS, rounds + 64) end
    local feed2 = nil
    if weapon.key == key then
        local _, at = KINDS[TYPES.custom].projectile(key)
        local own = at and source('proj_ammo', TYPES.deltas, at)
        if (projectile == nil or projectile == 0) and own and own > 0 then projectile = own end
        -- its ammo types (attachments) set the rounds feeds when it spawns: the swap writes them too
        if rounds then
            local alt = default_of(field_at(T_ROUNDS, rounds + 68, 'u32', 100000))
            local feeds = KINDS[TYPES.custom].feeds(key, { [64] = projectile, [68] = alt })
            if feeds[64] then source('proj_ammo_feed1', TYPES.deltas, feeds[64]) end
            feed2 = feeds[68] and field_at(TYPES.deltas, feeds[68], 'u32', 100000)
        end
    end
    if fire then
        -- (also when it names none: its ammo type does, and the fire mode then takes the swapped one)
        local own = source('proj_fire', T_FIRE, fire, true)
        if projectile == nil or projectile == 0 then projectile = own end
    end
    local prow = projectile and projectile > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[projectile]
    -- charge weapons whose stages fire their own projectiles: those, not the fire mode's
    local charge = record(TYPES.charge)
    local shots = charge and KINDS[TYPES.charge].shots(charge, projectile)
    if shots then prow = nil end
    for s = 1, charge and 3 or 0 do source('proj_c' .. s, TYPES.charge, charge + (s - 1) * 24 + 4) end
    local drow = nil
    if prow then
        local id = read_field(field_at(T_PROJECTILE, prow + 60, 'u32', 100000))
        drow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    -- beam weapons: beam component (+0 beam type) -> beam row (+12) -> damage row
    local beam = not drow and record(T_BEAM_WEAPON)
    if beam then
        local kind = read_field(field_at(T_BEAM_WEAPON, beam, 'u32', 100000))
        local brow = kind and tables[T_BEAM] and tables[T_BEAM].index[kind]
        local id = brow and read_field(field_at(T_BEAM, brow + 12, 'u32', 100000))
        drow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    -- flame and gas weapons: spray component (+200 damage row), damage per flame / gas hit
    local spray = not drow and record(T_SPRAY)
    if spray then
        local id = read_field(field_at(T_SPRAY, spray + 200, 'u32', 100000))
        drow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
        -- none of its own (the enemies' bile and acid sprays): its projectile's (+196 projectile type, that +60)
        local pt = not drow and read_field(field_at(T_SPRAY, spray + 196, 'u32', 100000))
        local pr = pt and pt > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[pt]
        id = pr and read_field(field_at(T_PROJECTILE, pr + 60, 'u32', 100000))
        drow = drow or id and id > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    -- melee weapons: melee component (+12 damage row), damage per strike
    local melee = not drow and record(T_MELEE)
    if melee then
        local id = read_field(field_at(T_MELEE, melee + 12, 'u32', 100000))
        drow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    -- arc weapons: arc component (+0 arc type, +4 fire rate) -> arc row (+8 range, +28 chain
    -- length, +32 chain split, +36 damage row)
    local arc = not drow and record(TYPES.arc_weapon)
    local arow = nil
    if arc then
        local kind = read_field(field_at(TYPES.arc_weapon, arc, 'u32', 100000))
        arow = kind and tables[TYPES.arc] and tables[TYPES.arc].index[kind]
        local id = arow and read_field(field_at(TYPES.arc, arow + 36, 'u32', 100000))
        drow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    weapon.projectile, weapon.damage_row = prow and projectile or nil, nil
    local main_from = #weapon.rows + 1   -- the shot's rows (direct hit, projectile, explosions): main_from..main_to
    if drow then
        weapon.damage_row = true
        damage_rows(weapon, 'Damage', '', drow)
    end
    if drow then status_rows(weapon, 'Damage', '', drow, 'hit') end
    -- a beam's damage ticks per minute (BeamWeaponComponentData +104; SHODAN Offline Integration: 60 on the Laser
    -- Cannon and Laser Sentry)
    -- a beam's reach (BeamSettings +8; from starstring's fork), where the beam is the damage source
    local reach = beam and drow and tables[T_BEAM] and tables[T_BEAM].index[read_field(field_at(T_BEAM_WEAPON, beam, 'u32', 100000)) or -1]
    if reach then
        add_row(weapon, 'Damage', 'beam_range', 'Beam range (m)', 'f32', { part('beam_range', T_BEAM, reach + 8, 'f32', 100000) }, 0, 10000, 1, 10)
    end
    local tick = beam and field_at(T_BEAM_WEAPON, beam + 104, 'u32', 6000)
    local ticks = tick and default_of(tick)
    if ticks and ticks > 0 and ticks <= 6000 then
        add_row(weapon, 'Damage', 'beam_ticks', 'Damage ticks per minute', 'u32',
                { part('beam_ticks', T_BEAM_WEAPON, beam + 104, 'u32', 6000) }, 1, 6000, 10, 60).note =
            'how often the beam deals its damage while it touches'
    end
    -- +108 / +112: 2 and 0.15 s on the Trident, 1 and 1.4 s on the Meltagun; the steady lasers (1 and 0) ignore both, tested
    local beams = beam and default_of(field_at(T_BEAM_WEAPON, beam + 108, 'u32', 1000))
    local stay = beam and default_of(field_at(T_BEAM_WEAPON, beam + 112, 'f32', 100000))
    if beams and beams >= 1 and beams <= 16 and (beams > 1 or (stay or 0) > 0) then
        add_row(weapon, 'Damage', 'beam_count', 'Beams per barrel', 'u32', { part('beam_count', T_BEAM_WEAPON, beam + 108, 'u32', 1000) }, 1, 12, 1, 1).tip =
            { 'The Trident shows 4 beams at its default of 2.' }
        add_row(weapon, 'Damage', 'beam_stay', 'Beam stays after the shot (s)', 'f32', { part('beam_stay', T_BEAM_WEAPON, beam + 112, 'f32', 100000) }, 0, 10, 0.05, 0.25)
    end
    local damage_to = #weapon.rows
    if arow then
        add_row(weapon, 'Arc', 'arc_range', 'Range (m)', 'f32', { part('arc_range', TYPES.arc, arow + 8, 'f32', 100000) },
                0, 1000, 1, 5)
        add_row(weapon, 'Arc', 'arc_chain', 'Chain length', 'u32', { MOD.solo(part('arc_chain', TYPES.arc, arow + 28, 'u32', 1000)) },
                0, 20, 1, 1)
        add_row(weapon, 'Arc', 'arc_split', 'Chain split', 'u32', { MOD.solo(part('arc_split', TYPES.arc, arow + 32, 'u32', 1000)) },
                0, 20, 1, 1)
        local rate = read_field(field_at(TYPES.arc_weapon, arc + 4, 'f32', 100000))
        if rate and rate > 0 then
            add_row(weapon, 'Fire', 'arc_rpm', 'Fire rate (RPM)', 'f32', { part('arc_rpm', TYPES.arc_weapon, arc + 4, 'f32', 100000) },
                    1, 6000, 1, 10)
        end
    end
    local blasts = {}
    -- the ids of rows from..to, taken by `prefix` .. their id past `listed` (its prefix): another shot's
    -- for the same memory (listed once), kept so saved values and presets that name them still apply
    local function alias_rows(from, to, listed, prefix)
        weapon.aliases = weapon.aliases or {}
        for k = from, to do
            for _, p in ipairs(weapon.rows[k].parts) do
                if p.id:sub(1, #listed) == listed then
                    local alias = prefix .. p.id:sub(#listed + 1)
                    if not weapon.by_id[alias] then weapon.by_id[alias], weapon.aliases[alias] = p, p.id end
                end
            end
        end
    end
    local exploded = {}   -- explosion row -> { from, to, prefix } once listed
    local blast_hits = {}   -- an explosion's damage row -> { from, to, prefix, section } once listed
    -- a projectile's rows (ids `idp` .. stat) in `section`, and its explosions, to add after it: on
    -- impact (+144) and on expiry (+156, when another one) -> explosion row (+4 damage row, +16 inner,
    -- +20 outer, +24 shockwave radius), in `xsection` ('Explosion', or the shot's)
    local function projectile_rows(p, idp, section, xsection)
        local function proj(id, label, offset, max, small, big)
            add_row(weapon, section, idp .. id, label, 'f32', { part(idp .. id, T_PROJECTILE, p + offset, 'f32', 100000) },
                    0, max, small, big)
        end
        add_row(weapon, section, idp .. 'pellets', 'Projectiles per shot', 'u32',
                { part(idp .. 'pellets', T_PROJECTILE, p + 28, 'u32', 1000) }, 1, 100, 1, 5)
        if idp == '' and weapon.missile then
            KINDS[TYPES.seeking].flight(weapon, weapon.missile, KINDS[TYPES.seeking].steered(weapon))
        else
            proj('velocity', 'Velocity (m/s)', 32, 100000, 10, 100)
            proj('drag', 'Drag factor', 40, 100, 0.05, 0.5)
            proj('gravity', 'Gravity factor', 44, 100, 0.05, 0.5)
        end
        proj('pen_slowdown', 'Penetration slowdown', 64, 100, 0.05, 0.25)
        local impact = read_field(field_at(T_PROJECTILE, p + 144, 'u32', 100000))
        local expiry = read_field(field_at(T_PROJECTILE, p + 156, 'u32', 100000))
        -- the explosions it sets off, as choices (+144 on impact, +156 on expiry; 0: none), and its fuse: above 0
        -- it goes off this close to a target (+148, a flak fuse) and this long after the hit (+152). The
        -- explosion rows below stay the game's own explosion's: another one's are on the Records tab.
        local idsec = section .. ' explosion id'
        local function blast_id(id, label, offset)
            local row = add_row(weapon, idsec, idp .. id, label, 'u32', { part(idp .. id, T_PROJECTILE, p + offset, 'u32', 100000) },
                                0, 100000, 1, 10)
            row.choice = 'explosion'
            return row
        end
        local impact_row = impact and blast_id('impact_explosion', 'Impact explosion (id)', 144)
        if impact_row then
            impact_row.note = function() return 'sets off: ' .. MOD.records.label(T_EXPLOSION, read_field(impact_row.parts[1].field)) end
            impact_row.tip = MOD.records.TIPS.impact
        end
        if impact and impact > 0 then
            for _, f in ipairs({ { 'fuse_proximity', 'Blast proximity (m)', 148, 200, 0.1, 1 },
                                 { 'fuse_delay', 'Blast delay (s)', 152, 30, 0.05, 0.5 } }) do
                local row = add_row(weapon, idsec, idp .. f[1], f[2], 'f32', { part(idp .. f[1], T_PROJECTILE, p + f[3], 'f32', 100000) },
                                    0, f[4], f[5], f[6])
                row.tip = f[1] == 'fuse_proximity' and MOD.records.TIPS.proximity or MOD.records.TIPS.delay
            end
            -- the blast angle (+136): 80 or 90 on most rounds, 360 on the airburst ones (RL-77, the large plasma bolt)
            local angle = add_row(weapon, idsec, idp .. 'blast_angle', 'Blast angle (deg)', 'f32',
                                  { part(idp .. 'blast_angle', T_PROJECTILE, p + 136, 'f32', 100000) }, 0, 360, 1, 10)
            angle.note = MOD.records.NOTES.weapon_angle
        end
        if expiry then blast_id('expiry_explosion', 'Expiry explosion (id)', 156).tip = MOD.records.TIPS.expiry end
        local first = #blasts
        if impact and impact > 0 then blasts[#blasts + 1] = { id = impact, prefix = idp .. 'blast', section = xsection, damage = true } end
        if expiry and expiry > 0 and expiry ~= impact then
            blasts[#blasts + 1] = { id = expiry, prefix = idp .. 'expiry', section = #blasts > first and (xsection .. ' (expiry)') or xsection,
                                    damage = true }
        end
    end
    local function explosion_rows()
        for _, blast in ipairs(blasts) do
            local xrow = tables[T_EXPLOSION] and tables[T_EXPLOSION].index[blast.id]
            local before = xrow and exploded[xrow]
            if before then   -- another shot's explosion too (the same one in game): listed once
                alias_rows(before.from, before.to, before.prefix, blast.prefix)
                local first = weapon.rows[before.from]
                if first then first.note = first.note or ('explosion: also the ' .. blast.section:gsub(' ?[Ee]xplosion.*$', ''):lower() .. "'s") end
            elseif xrow then
                local from = #weapon.rows + 1
                local id = blast.damage and read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
                local qrow = id and id > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
                local shared = qrow and blast_hits[qrow]
                if shared then   -- another explosion's damage too (StA-X3 W.A.S.P.'s modes): listed once
                    alias_rows(shared.from, shared.to, shared.prefix, blast.prefix .. '_')
                elseif qrow then
                    damage_rows(weapon, blast.section, blast.prefix .. '_', qrow, 'Explosion')
                    blast_hits[qrow] = { from = from, to = #weapon.rows, prefix = blast.prefix .. '_', section = blast.section }
                end
                local radii = #weapon.rows + 1
                for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                     { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                    local rid = blast.prefix .. '_' .. r[1]
                    add_row(weapon, blast.section, rid, r[2], 'f32', { part(rid, T_EXPLOSION, xrow + r[3], 'f32', 100000) }, 0, 200, 0.1, 1)
                end
                MOD.explosion_extras(weapon, blast.section, blast.prefix .. '_', xrow)
                -- the shrapnel it throws: the projectile every piece is (+84, a choice: its own flight, damage and
                -- explosion) and how many (+80)
                MOD.records.shrapnel_rows(weapon, blast.section == 'Explosion' and 'Shrapnel' or (blast.section .. ' shrapnel'),
                                          blast.prefix .. '_shrapnel', xrow)
                -- the arc it makes (explosion +120 arc type -> arc row: +8 range, +28 chain length, +32 chain
                -- split, +36 damage row), as a throwable's: the GL-52 De-Escalator's grenade
                local arc = tables[TYPES.arc] and tables[TYPES.arc].index[read_field(field_at(T_EXPLOSION, xrow + 120, 'u32', 100000)) or -1]
                if arc then
                    local section, pre = blast.section == 'Explosion' and 'Arc' or (blast.section .. ' arc'), blast.prefix .. '_arc_'
                    add_row(weapon, section, pre .. 'range', 'Range (m)', 'f32', { part(pre .. 'range', TYPES.arc, arc + 8, 'f32', 100000) },
                            0, 1000, 1, 5)
                    add_row(weapon, section, pre .. 'chain', 'Chain length', 'u32', { MOD.solo(part(pre .. 'chain', TYPES.arc, arc + 28, 'u32', 1000)) },
                            0, 20, 1, 1)
                    add_row(weapon, section, pre .. 'split', 'Chain split', 'u32', { MOD.solo(part(pre .. 'split', TYPES.arc, arc + 32, 'u32', 1000)) },
                            0, 20, 1, 1)
                    local aid = read_field(field_at(TYPES.arc, arc + 36, 'u32', 100000))
                    local arow = aid and tables[T_DAMAGE] and tables[T_DAMAGE].index[aid]
                    if arow then
                        damage_rows(weapon, section, pre, arow, 'Arc')
                        status_rows(weapon, section, pre, arow, 'hit')
                    end
                end
                if shared and weapon.rows[radii] then
                    weapon.rows[radii].note = 'damage: the same as the ' .. shared.section:lower() .. "'s (above)"
                    local first = weapon.rows[shared.from]
                    if first then first.note = first.note or ('also the ' .. blast.section:lower() .. "'s damage") end
                end
                exploded[xrow] = { from = from, to = #weapon.rows, prefix = blast.prefix }
            end
        end
        blasts = {}
    end
    weapon.missile = fire and KINDS[TYPES.seeking].fired(fire)
    if prow then projectile_rows(prow, '', 'Projectile', 'Explosion') end
    -- a melee strike's explosion (Breaching Hammer), with its damage row (explosion +4)
    local strike = melee and weapon.key == key and KINDS[T_MELEE].explosions[weapon.hash]
    if strike then blasts[#blasts + 1] = { id = strike, prefix = 'blast', section = 'Explosion', damage = true } end
    explosion_rows()
    local main_to = #weapon.rows
    -- each shot of a charge weapon: its direct hit and projectile, then its explosion. A direct hit a
    -- later shot shares with an earlier one (Loyalist, Purifier: one damage row) is listed once, under
    -- the earlier shot; the later shot's ids for it stay as aliases (weapon.aliases: id -> listed id),
    -- so saved values and presets that name them still apply.
    local hits = {}
    for _, shot in ipairs(shots or {}) do
        local section = shot.name .. ' shot'
        local id = read_field(field_at(T_PROJECTILE, shot.prow + 60, 'u32', 100000))
        local qrow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
        local before = qrow and hits[qrow]
        if before then
            weapon.aliases = weapon.aliases or {}
            for _, listed in ipairs(before.ids) do
                local alias = shot.prefix .. listed:sub(#before.prefix + 1)
                weapon.by_id[alias], weapon.aliases[alias] = weapon.by_id[listed], listed
            end
            before.first.note = before.first.note or ('direct hit: also the ' .. shot.name:lower() .. ' shot\'s')
        elseif qrow then
            local from = #weapon.rows + 1
            local first = damage_rows(weapon, section, shot.prefix, qrow)
            status_rows(weapon, section, shot.prefix, qrow, 'hit')
            local ids = {}
            for k = from, #weapon.rows do
                for _, p in ipairs(weapon.rows[k].parts) do ids[#ids + 1] = p.id end
            end
            hits[qrow] = { name = shot.name, first = first, prefix = shot.prefix, ids = ids }
        end
        local from = #weapon.rows + 1
        projectile_rows(shot.prow, shot.prefix, section, shot.name .. ' explosion')
        if before and weapon.rows[from] then
            weapon.rows[from].note = 'direct hit: see the ' .. before.name:lower() .. ' shot'
        end
        explosion_rows()
    end
    -- the second firing mode's projectile (fire mode +576: the Autocannon's flak, the Recoilless Rifle's HE),
    -- read as the game had it: its direct hit, projectile and explosions, ids 'm2_' .. stat
    local second = fire and weapon.key == key and default_of(field_at(T_FIRE, fire + 576, 'u32', 100000))
    local srow = second and second > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[second]
    -- The same projectile as the first mode's (StA-X3 W.A.S.P.'s artillery mode): not listed again; a
    -- direct hit or explosion the two share: listed once (the 'm2_' ids stay as aliases).
    if srow and srow == prow then
        alias_rows(main_from, main_to, '', 'm2_')
        local first = weapon.rows[main_from]
        if first then first.note = first.note or "also the second firing mode's shot (the same projectile)" end
    elseif srow then
        local id = read_field(field_at(T_PROJECTILE, srow + 60, 'u32', 100000))
        local qrow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
        local from = #weapon.rows + 1
        if qrow and qrow == drow then
            alias_rows(main_from, damage_to, '', 'm2_')
        elseif qrow then
            damage_rows(weapon, 'Second mode', 'm2_', qrow)
            status_rows(weapon, 'Second mode', 'm2_', qrow, 'hit')
        end
        projectile_rows(srow, 'm2_', 'Second mode', 'Second mode explosion')
        if qrow and qrow == drow and weapon.rows[from] then
            weapon.rows[from].note = "direct hit: the same as the first mode's (Damage above)"
        end
        explosion_rows()
    end
    -- its second ammo type and tracer rounds (KINDS[T_ROUNDS].extra): their direct hit (a tracer's
    -- is the round's own: not listed again), projectile and explosions, ids 'a2_' / 't_' .. stat
    local extra = weapon.key == key and prow and KINDS[T_ROUNDS].extra(rounds, record(T_MAGAZINE), projectile)
    for _, shot in ipairs(extra or {}) do
        if shot.field then shot.delta = feed2 end
    end
    for _, shot in ipairs(extra or {}) do
        if shot.prow then
            local id = read_field(field_at(T_PROJECTILE, shot.prow + 60, 'u32', 100000))
            local qrow = id and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
            local from = #weapon.rows + 1
            if qrow and qrow ~= drow then
                damage_rows(weapon, shot.name, shot.prefix, qrow)
                status_rows(weapon, shot.name, shot.prefix, qrow, 'hit')
            end
            projectile_rows(shot.prow, shot.prefix, shot.name, shot.name .. ' explosion')
            -- a status's shared rows (its own section) after the shot's, not between them
            local own, shared = {}, {}
            for k = from, #weapon.rows do
                local r = weapon.rows[k]
                if r.section == shot.name then own[#own + 1] = r else shared[#shared + 1] = r end
                weapon.rows[k] = nil
            end
            for _, r in ipairs(own) do weapon.rows[#weapon.rows + 1] = r end
            for _, r in ipairs(shared) do weapon.rows[#weapon.rows + 1] = r end
            if qrow == drow and weapon.rows[from] then
                weapon.rows[from].note = 'damage: the same as the other rounds (Damage above)'
            end
            explosion_rows()
        end
    end
    -- the charge: its stages' times, the overcharge limit, and the multipliers it puts on the shot
    if charge then
        local function cf(offset) return field_at(TYPES.charge, charge + offset, 'f32', 100000) end
        local note = nil
        if shots then
            local said = {}
            for _, shot in ipairs(shots) do
                said[#said + 1] = (shot.last > shot.stage and ('stages ' .. shot.stage .. '-' .. shot.last) or ('stage ' .. shot.stage))
                                  .. ': ' .. shot.name:lower() .. ' shot'
            end
            note = table.concat(said, ', ')
        end
        for s = 1, 3 do
            local row = add_row(weapon, 'Charge', 'charge_' .. s, 'Stage ' .. s .. ' charge time (s)', 'f32',
                                { part('charge_' .. s, TYPES.charge, charge + (s - 1) * 24, 'f32', 100000) }, 0, 600, 0.05, 0.25)
            if s == 1 then row.note = note end
        end
        local limit = default_of(cf(208))
        if limit and limit > 0 then
            add_row(weapon, 'Charge', 'charge_limit', 'Overcharge limit (s)', 'f32',
                    { part('charge_limit', TYPES.charge, charge + 208, 'f32', 100000) }, 0, 600, 0.05, 0.25).tip =
                { 'Held this long, it blows up. 600 = it never does.' }
        end
        -- +185 blows up at the last stage's charge time (the Railgun's unsafe mode; SHODAN Offline Integration)
        local boom = part('charge_explodes', TYPES.charge, charge + 185, 'flag', 1)
        if default_of(boom.field) == 1 then
            add_row(weapon, 'Charge', 'charge_explodes', 'Blows up when overcharged', 'flag', { boom }, 0, 1, 1, 1)
        end
        for _, m in ipairs(KINDS[TYPES.charge].MULTIPLIERS) do
            if not m.arc or record(TYPES.arc_weapon) then
                for k, at in ipairs({ { '_min', ', min charge' }, { '_max', ', overcharge' } }) do
                    local id = 'mul_' .. m[1] .. at[1]
                    add_row(weapon, 'Charge', id, m[2] .. ' multiplier' .. at[2], 'f32',
                            { (m.arc and MOD.solo or MOD.same)(part(id, TYPES.charge, charge + m[3] + (k - 1) * 4, 'f32', 100000)) },
                            0, 100, 0.05, 0.25)
                end
            end
        end
    end
    if fire then
        local rates, values = {}, {}
        for n, offset in ipairs({ 4, 8, 12 }) do
            local f = field_at(T_FIRE, fire + offset, 'f32', 100000)
            local v = read_field(f)
            if v and v > 0 then rates[#rates + 1] = { n = n, offset = offset } end
            values[n] = default_of(f)
        end
        -- settings of one value (Maxigun, Bullet Storm, SG-88: all three; LAS-44 Nova: two, the first 0): no
        -- rate to pick in game, so one row writes them all (its first part is the default setting, the one the
        -- game fires at). Sentries, emplacements and vehicles can't switch either: one row, whatever their values
        local same = #rates > 1
        local fixed = weapon.slot == 'Stratagems' or weapon.slot == 'Mechas' or weapon.slot == 'Boosters'
        for _, rate in ipairs(rates) do same = same and (fixed or values[rate.n] == values[rates[1].n]) end
        if same then
            local parts = {}
            for _, rate in ipairs(rates) do
                local id = ({ 'rpm_1', 'rpm', 'rpm_3' })[rate.n]
                table.insert(parts, rate.n == 2 and 1 or #parts + 1, part(id, T_FIRE, fire + rate.offset, 'f32', 100000))
            end
            add_row(weapon, 'Fire', parts[1].id, 'Fire rate (RPM)', 'f32', parts, 1, 6000, 10, 50).lead = true   -- (shows the default)
            rates = {}
        end
        for k, rate in ipairs(rates) do
            local id = ({ 'rpm_1', 'rpm', 'rpm_3' })[rate.n]
            local label = #rates == 1 and 'Fire rate (RPM)' or ('Fire rate ' .. k .. ' (RPM)')
            add_row(weapon, 'Fire', id, label, 'f32', { part(id, T_FIRE, fire + rate.offset, 'f32', 100000) }, 1, 6000, 10, 50)
        end
    end
    local magazine, heat = record(T_MAGAZINE), record(T_HEAT)
    local reload = (magazine or rounds or heat) and record(TYPES.reload)
    -- heat weapons (lasers, Quasar): +84/+88/+92 heatsinks, +96 overheat threshold, +100 heat it
    -- recovers to after an overheat, +116/+120 heat per shot / second, +128 cooling per second,
    -- +140 cooling per second while overheated, +144 (byte) overheat needs a new heatsink
    local sinks = heat and read_field(field_at(T_HEAT, heat + 144, 'u32', 4294967295))
    sinks = sinks and sinks % 256 ~= 0
    local function item_section(item)
        return #items == 1 and 'Ammo' or item.name   -- (the one it comes with first)
    end
    -- The magazine (`ammo`), else the reload and heat rows of the weapon's own record (`item` nil), or of
    -- one of its magazine attachments: the values it sets, ids 'item<id>_<stat>', in a section of its own.
    -- `hidden`: the record's ids whose rows its attachments took over (id -> 'component:offset').
    local hidden = {}
    local function stock(item, ammo)
        local pre = item and string.format('item%08X_', item.id) or ''
        -- the field a row edits (nil: no row); `base`: where a value is read from (the attachment's, else the
        -- record's; the record's rows read the attachment it comes with)
        local function get(id, word, kind, offset, storage, limit)
            if item then return item.words[word] and field_at(TYPES.deltas, item.words[word], storage, limit) end
            if kept(word) then return field_at(kind, offset, storage, limit) end
            hidden[id] = word
        end
        local function base(word, kind, offset, storage, limit)
            local from = item or (items[1] and items[1].default and items[1])
            local at = from and from.words[word]
            return at and field_at(TYPES.deltas, at, storage, limit) or field_at(kind, offset, storage, limit)
        end
        local function row(section, id, label, storage, f, min, max, small, big)
            if not f then return nil end
            return add_row(weapon, item and item_section(item) or section, pre .. id, label, storage,
                           { { id = pre .. id, field = f } }, min, max, small, big)
        end
        if ammo then
            -- a vehicle's gun that has no spare magazines and holds none (the exosuits' arms, the Incinerator
            -- FRV's flamer) never reloads: spare magazines would start a reload the game does not finish
            -- (issue #31: a crash once the animation ends), so it has neither those rows nor a reload time
            if weapon.mounted and magazine and not item then
                weapon.sealed = default_of(field_at(T_MAGAZINE, magazine + 140, 'u32', 100000)) == 0
                                and default_of(field_at(T_MAGAZINE, magazine + 148, 'u32', 100000)) == 0
            end
            -- not a player's gun (sentries, emplacements, vehicles) and no spare magazines to start with or hold:
            -- no magazine rows (their reload stays)
            local spares = not (magazine and not item and weapon.slot ~= 'Primary' and weapon.slot ~= 'Secondary'
                                and weapon.slot ~= 'Support'
                                and default_of(field_at(T_MAGAZINE, magazine + 140, 'u32', 100000)) == 0
                                and default_of(field_at(T_MAGAZINE, magazine + 148, 'u32', 100000)) == 0)
            -- the game keeps at most 2048 rounds in a magazine (more drops to 2048 at the first shot): rows stop
            -- there, and going past it says why (row.limit)
            for _, m in ipairs(magazine and { { 'capacity', 'Magazine size', 136, 1, 2048, 10 },
                                              not weapon.sealed and spares and { 'mags_start', 'Starting magazines', 140, 0, 100000, 50 } or nil,
                                              not weapon.sealed and spares and { 'mags_supply', 'Magazines from supply', 144, 0, 100000, 50 } or nil,
                                              not weapon.sealed and spares and { 'mags_max', 'Max spare magazines', 148, 0, 100000, 50 } or nil } or {}) do
                local r = row('Ammo', m[1], m[2], 'u32', get(m[1], '5:' .. m[3], T_MAGAZINE, magazine + m[3], 'u32', 100000), m[4], m[5], 1, m[6])
                if r and m[1] == 'capacity' then r.limit = 'The game holds at most 2048 rounds in a magazine.' end
                if r and m[1] == 'mags_supply' then r.tip = { 'A resupply box gives this many. An ammo box on the map gives half, rounded down (at least 1).' } end
            end
            return
        end
        -- reload time: the weapon's own (+56), or its magazine's (an attachment sets it over the weapon's 0).
        -- The game scales the reload animation to it; 0: the animation's own length, which the tables do
        -- not hold: shown as that length where it is known (MOD.reload_seconds, row.zero)
        local rf = reload and get('reload_time', '113:56', TYPES.reload, reload + 56, 'f32', 1000)
        local rt = rf and default_of(rf)
        local known = rt == 0 and not item and MOD.reload_seconds[weapon.hash]
        if rt and rt >= 0 and rt < 1000 and not weapon.sealed then
            local r = row('Ammo', 'reload_time', (rt > 0 or known) and 'Reload time (s)' or 'Reload time (s; 0 = animation length)',
                          'f32', rf, 0, 60, 0.1, 0.5)
            if r and known then r.zero = known end
            -- a weapon loading a round at a time: the value scales each round, shown as the full reload
            if r and not item and MOD.reload_scale[weapon.hash] then r.scale = MOD.reload_scale[weapon.hash] end
        end
        -- +1: you can move while reloading; off on the weapons that hold you still (the Autocannon, MG-43...):
        -- a row there only (not on vehicle guns: you are not walking)
        if reload and not item and not weapon.mounted
           and default_of(field_at(TYPES.reload, reload + 1, 'flag', 1)) == 0 then
            add_row(weapon, 'Ammo', 'reload_move', 'Move while reloading', 'flag',
                    { part('reload_move', TYPES.reload, reload + 1, 'flag', 1) }, 0, 1, 1, 1)
        end
        if not heat then return end
        local function hf(id, offset) return get(id, '266:' .. offset, T_HEAT, heat + offset, 'f32', 1000000) end
        local function hb(offset) return base('266:' .. offset, T_HEAT, heat + offset, 'f32', 1000000) end
        if sinks then
            for _, k in ipairs({ { 'heatsinks_start', 'Starting heatsinks', 84 }, { 'heatsinks_supply', 'Heatsinks from supply', 88 },
                                 { 'heatsinks_max', 'Max spare heatsinks', 92 } }) do
                row('Ammo', k[1], k[2], 'u32', get(k[1], '266:' .. k[3], T_HEAT, heat + k[3], 'u32', 100000), 0, 999, 1, 5)
            end
        end
        row('Heat', 'heat_capacity', 'Overheat threshold', 'f32', hf('heat_capacity', 96), 0, 100000, 1, 10)
        for _, g in ipairs({ { 'heat_shot', 'Heat per shot', 116 }, { 'heat_second', 'Heat per second firing', 120 } }) do
            local v = read_field(hb(g[3]))
            if v and v > 0 then row('Heat', g[1], g[2], 'f32', hf(g[1], g[3]), 0, 100000, 0.1, 1) end
        end
        -- cool-down times: the heat to shed over the cooling rate; setting a time sets the rate
        local capacity, recover = hb(96), hb(100)
        local function span(recovered, read)
            local c, r = read(capacity), recovered and read(recover) or 0
            return c and r and c - r
        end
        local function cool(id, label, offset, recovered)
            local s = span(recovered, read_field)
            local r = s and s > 0 and row('Heat', id, label, 'f32', hf(id, offset), 0.1, 3600, 0.5, 5)
            if not r then return end
            r.span = function() return span(recovered, read_field) end
            r.span_default = function() return span(recovered, default_of) end
        end
        cool('heat_cool', 'Cool-down time, full heat (s)', 128, false)
        if not sinks then cool('heat_cool_overheated', 'Cool-down time after overheat (s)', 140, true) end
        -- wind-up (Sickles, Scythe, Quasar...): +148 the charge it needs to fire, +152 the charge gained
        -- per second holding the trigger, +156 lost per second once let go; times: that charge over the rate
        local needed = hb(148)
        local function wind(id, label, offset)
            local c = read_field(needed)
            local r = c and c > 0 and row('Wind-up', id, label, 'f32', hf(id, offset), 0.01, 3600, 0.05, 0.25)
            if not r then return end
            r.span = function() return read_field(needed) end
            r.span_default = function() return default_of(needed) end
        end
        wind('windup', 'Wind-up time (s)', 152)
        wind('winddown', 'Wind-down time, released (s)', 156)
    end
    stock(nil, true)
    if rounds then
        -- +72 the first magazine's capacity, +76 the second's (0: none; the Punisher, Slugger, Cookout and Halt
        -- have two 8-round tubes, 16 in all)
        local tubes = (default_of(field_at(T_ROUNDS, rounds + 76, 'f32', 100000)) or 0) > 0
        add_row(weapon, 'Ammo', 'rounds_capacity', tubes and 'Rounds loaded, first tube' or 'Rounds loaded', 'f32',
                { part('rounds_capacity', T_ROUNDS, rounds + 72, 'f32', 100000) }, 1, 999, 1, 5)
        if tubes then
            add_row(weapon, 'Ammo', 'rounds_capacity2', 'Rounds loaded, second tube', 'f32',
                    { part('rounds_capacity2', T_ROUNDS, rounds + 76, 'f32', 100000) }, 1, 999, 1, 5)
        end
        local function rnd(id, label, offset)
            return add_row(weapon, 'Ammo', id, label, 'u32', { part(id, T_ROUNDS, rounds + offset, 'u32', 100000) }, 0, 9999, 1, 10)
        end
        rnd('rounds_start', 'Starting rounds', 88)
        rnd('rounds_supply', 'Rounds from supply', 84).tip = { 'A resupply box gives this much. An ammo box on the map gives half, rounded down.' }
        rnd('rounds_max', 'Max spare rounds', 80)
        -- +92 rounds added per reload (a clip: Autocannon 5, Veto 6; else 1, a shell at a time); +96 a reload
        -- is allowed below this many rounds left (f32; 0: below the capacity)
        add_row(weapon, 'Ammo', 'rounds_per_reload', 'Rounds per reload', 'u32',
                { part('rounds_per_reload', T_ROUNDS, rounds + 92, 'u32', 100000) }, 1, 999, 1, 5)
        local clip = not MOD.offline and key == weapon.key and KINDS[T_ROUNDS].CLIPS[weapon.hash]   -- (live only)
        if clip then
            local f = field_at(T_ROUNDS, 'clip' .. rounds, 'virtual', 100000)
            f.default, f.rounds = clip.count, rounds
            local row = add_row(weapon, 'Ammo', 'rounds_per_clip', 'Rounds per ' .. clip.name .. ' (empty)', 'u32',
                                { { id = 'rounds_per_clip', field = f } }, 1, 999, 1, 5)
            row.note = 'loaded into an empty weapon, from your spare rounds'
        end
        if (read_field(field_at(T_ROUNDS, rounds + 96, 'f32', 100000)) or 0) > 0 then
            add_row(weapon, 'Ammo', 'reload_below', 'Reload allowed below (rounds)', 'f32',
                    { part('reload_below', T_ROUNDS, rounds + 96, 'f32', 100000) }, 1, 999, 1, 5)
        end
    end
    stock(nil, false)
    if heat then
        -- heat levels (+0: 3 of 24 bytes: +0 heat it starts at, +4 projectile fired from there on, +20
        -- status effect put on the shooter: its damage row, status row +44). The LAS-17 Double-Edge
        -- Sickle's damage ramp and self-damage; below the first level it fires the fire mode's projectile.
        local top = default_of(field_at(T_HEAT, heat + 96, 'f32', 1000000))
        for k = 1, 3 do
            local at = heat + (k - 1) * 24
            local from = default_of(field_at(T_HEAT, at, 'f32', 1000000))
            local pid = from and from > 0 and source('proj_h' .. k, T_HEAT, at + 4)
            local prow = pid and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[pid]
            local did = prow and read_field(field_at(T_PROJECTILE, prow + 60, 'u32', 100000))
            local qrow = did and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
            if qrow then
                local id = 'heatlvl' .. k .. '_'
                local section = top and top > 0 and string.format('Above %d%% heat', math.floor(from / top * 100 + 0.5))
                                or ('Heat level ' .. k)
                local first = add_row(weapon, section, id .. 'at', 'Starts at heat', 'f32',
                                      { part(id .. 'at', T_HEAT, at, 'f32', 1000000) }, 0, 100000, 1, 10)
                first.note = 'the shot fired from this heat on, and what it does to you'
                damage_rows(weapon, section, id, qrow)
                local kind = read_field(field_at(T_HEAT, at + 20, 'u32', 100000))
                local srow = kind and kind > 0 and tables[T_STATUS] and tables[T_STATUS].index[kind]
                local sid = srow and read_field(field_at(T_STATUS, srow + 44, 'u32', 100000))
                local hurt = sid and sid > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[sid]
                if hurt then
                    add_row(weapon, section, id .. 'self', 'Damage to you', 'u32',
                            { part(id .. 'self', T_DAMAGE, hurt + 4, 'u32', 1000000),
                              part(id .. 'self_durable', T_DAMAGE, hurt + 8, 'u32', 1000000) }, 0, 100000, 1, 10)
                    for i = 0, 3 do
                        if read_field(field_at(T_DAMAGE, hurt + 44 + i * 8, 'u32', 100000)) == 5 then
                            add_row(weapon, section, id .. 'self_burn', 'Burning applied to you', 'f32',
                                    { part(id .. 'self_burn', T_DAMAGE, hurt + 48 + i * 8, 'f32', 100000) }, 0, 1000, 0.1, 1)
                        end
                    end
                end
            end
        end
    end
    -- each magazine attachment: its magazine, reload and heat values, then its stat modifiers (ergonomics
    -- bonus, ...); its rows change only that attachment (and every weapon that can fit it)
    for _, item in ipairs(items) do
        stock(item, true)
        stock(item, false)
        KINDS[TYPES.items].mod_rows(weapon, item_section(item), string.format('item%08X_', item.id), item.mods)
    end
    -- a value saved under a row its attachments took over ('capacity': once every magazine's) goes to theirs
    for id, word in pairs(hidden) do
        weapon.legacy = weapon.legacy or {}
        weapon.legacy[id] = {}
        for _, item in ipairs(items) do
            if item.words[word] then weapon.legacy[id][#weapon.legacy[id] + 1] = string.format('item%08X_', item.id) .. id end
        end
    end
    local data = record(T_WEAPON)
    if data then
        local function w(id, offset) return part(id, T_WEAPON, data + offset, 'f32', 100000) end
        add_row(weapon, 'Handling', 'recoil_h', 'Recoil (horizontal)', 'f32', { w('recoil_dh', 0), w('recoil_ch', 28) }, 0, 2000, 1, 5)
        add_row(weapon, 'Handling', 'recoil_v', 'Recoil (vertical)', 'f32', { w('recoil_dv', 4), w('recoil_cv', 32) }, 0, 2000, 1, 5)
        add_row(weapon, 'Handling', 'spread_h', 'Spread (horizontal)', 'f32', { w('spread_h', 84) }, 0, 5000, 1, 10)
        add_row(weapon, 'Handling', 'spread_v', 'Spread (vertical)', 'f32', { w('spread_v', 88) }, 0, 5000, 1, 10)
        add_row(weapon, 'Handling', 'sway', 'Sway multiplier', 'f32', { w('sway', 104) }, 0, 100, 0.1, 0.5)
        add_row(weapon, 'Handling', 'ergonomics', 'Ergonomics', 'f32', { w('ergonomics', 356) }, 0, 1000, 1, 5)
        -- suppressed (SHODAN Offline Integration): +112 the flag, +132 the firing noise template (the four suppressed
        -- guns: 1 and 10; others 0 and 0 / 6-9 / 14 / 15); no suppressor model, the firing sound stays
        local quiet, noise = part('suppressed', T_WEAPON, data + 112, 'flag', 1), part('suppressed_noise', T_WEAPON, data + 132, 'u32', 15)
        local fv, nv = default_of(quiet.field), default_of(noise.field)
        if (fv == 0 or fv == 1) and ({ [0] = true, [6] = true, [7] = true, [8] = true, [9] = true, [10] = true, [14] = true, [15] = true })[nv] then
            local r = add_row(weapon, 'Handling', 'suppressed', 'Suppressed', 'flag', { quiet, noise }, 0, 1, 1, 1)
            r.lead, r.suppression = true, true
            r.tip = { "Quieter for enemies: the noise of the game's suppressed guns. No suppressor model, same firing sound." }
        end
        -- no bolt pull (from 127MU's fork): the R-36's and R-40's fire animation (+936) and fire ability (+948, +1208)
        -- take the R-63 Diligence's, only where the game still holds the expected values
        local bolt = KINDS[T_WEAPON].stride == 1240
                     and ({ B6AFF2195568767F = { { 936, 0x14FAF8EB, 'anim' }, { 948, 2668, 'ability' }, { 1208, 2668, 'ability' } },
                            ['41F2DEF484634B59'] = { { 948, 2694, 'ability' } } })[weapon.hash]
        local donor = bolt and tables[T_WEAPON].index[hash_key('03E67A19B07C6523')]
        if donor then
            local anim = default_of(field_at(T_WEAPON, donor + 936, 'u32', 4294967295))
            local ability = default_of(field_at(T_WEAPON, donor + 948, 'u32', 100000))
            local fits, parts = anim == 0xAE6CC371 and ability and ability > 0, {}
            for k, s in ipairs(bolt) do
                if default_of(field_at(T_WEAPON, data + s[1], 'u32', 4294967295)) ~= s[2] then fits = false end
                parts[k] = part('no_bolt_' .. s[1], T_WEAPON, data + s[1], 'bolt', 1)
                parts[k].field.bolt_off, parts[k].field.bolt_on = s[2], s[3] == 'anim' and anim or ability
            end
            if fits then
                add_row(weapon, 'Handling', 'no_bolt', 'No bolt pull', 'flag', parts, 0, 1, 1, 1).tip =
                    { 'Skips the bolt pull after each shot. Fire rate, ammo and damage stay as they are.' }
            end
        end
        -- infinite ammo (SHODAN Offline Integration): the game's own switches, WeaponData +960 and the
        -- projectile weapon's +36 (1240-byte layout)
        local inf = KINDS[T_WEAPON].stride == 1240 and { part('infinite_ammo', T_WEAPON, data + 960, 'flag', 1) }
        if inf and fire then inf[2] = part('infinite_ammo_2', T_FIRE, fire + 36, 'flag', 1) end
        if inf and default_of(inf[1].field) == 0 and (not inf[2] or default_of(inf[2].field) == 0) then
            add_row(weapon, 'Ammo', 'infinite_ammo', 'Infinite ammo', 'flag', inf, 0, 1, 1, 1).tip =
                { 'The magazine never runs out. Flamethrowers: also set Ammo per puff to 0.' }
            -- with the other Ammo rows, not under a second Ammo heading below Handling (issue #118)
            local at = #weapon.rows
            for k = #weapon.rows - 1, 1, -1 do
                if weapon.rows[k].section == 'Ammo' then at = k + 1; break end
            end
            table.insert(weapon.rows, at, table.remove(weapon.rows))
        end
        -- the bayonet guns: the bayonet strike's damage row, which every bayonet shares
        local bayonet = MOD.BAYONET[weapon.name] and not weapon.mounted and MOD.melee_rows(weapon, 568, 'Bayonet melee', 'bayonet_')
        if bayonet then
            bayonet.tip = { 'These values are shared by ALL bayonets: they change the Constitution, Sweeper and Amendment at once.' }
        end
        -- fixed sights (SHODAN Offline Integration): a gun with no optic part (the Constitution) keeps its zoom
        -- on itself, WeaponData +116/+120/+124; guns with one edit it on the optic's Attachments page
        local custom = tables[TYPES.custom]
        local at = weapon.key == key and not weapon.mounted and custom and custom.index[key]
        local optic = false
        for slot = 0, at and 9 or -1 do
            local c = custom.copies[1] + HEADER_BYTES + at + slot * 8
            optic = optic or (peek4(c) == 2 and (peek4(c + 4) or 0) ~= 0)
        end
        -- (not melee weapons, not a gun's underbarrel part); one row, the three levels scaled together
        if at and not optic and not weapon.name:find('^CQC%-') and not weapon.name:find('(', 1, true)
           and (weapon.slot == 'Primary' or weapon.slot == 'Secondary' or weapon.slot == 'Support') then
            local zoom = {}
            for k = 1, 3 do
                local p = part('sight_zoom' .. k, T_WEAPON, data + 112 + k * 4, 'f32', 1000)
                if (default_of(p.field) or 0) > 0 then zoom[#zoom + 1] = p end
            end
            if #zoom > 0 then
                add_row(weapon, 'Scope', 'sight_zoom', 'Aim zoom (x)', 'f32', zoom, 0.1, 100, 0.1, 1).tip =
                    { 'How close the view gets when you aim: 1 is the normal view, 2 twice as close, 4 four times.' }
            end
        end
        MOD.spin_rows(weapon, data, record(TYPES.windup))
    end
    local equipment = weapon.key == key and record(TYPES.equipment)
    if equipment then
        local p = part('one_handed', TYPES.equipment, equipment + 196, 'flag', 1)
        local v = default_of(p.field)
        if v == 0 or v == 1 then
            add_row(weapon, 'Handling', 'one_handed', 'One-handed', 'flag', { p }, 0, 1, 1, 1).tip =
                { 'The game treats the weapon as one-handed. On two-handed weapons it breaks the hip-fire animations.' }
        end
    end
    if weapon.key == key and weapon.slot == 'Support' then
        local pack = KINDS[TYPES.rack].pack(key)
        if pack then KINDS[TYPES.jumppack].backpack(weapon, pack, true) end
        -- not on backpack-fed weapons: the backpack does not attach to a primary-slot weapon (issue #115)
        if not pack then MOD.slot.pickup_row(weapon, key) end
    end
    if weapon.key == key then
        KINDS[T_PROJECTILE].swap_row(weapon, sources, shots, fire, extra)
        KINDS[TYPES.throwable].grenade_row(weapon, fire)
    end
end

-- ---------------------------------------------------------------- stratagems
-- A stratagem's definition row (found live, in whichever group table holds its id): +16 debug
-- name (pointer), +80 uses (0xFFFFFFFF = unlimited), +104 cooldown, +152 payload entity list
-- (pointer, count at +160). Strikes add the projectile / explosion / damage records they use
-- (STRATAGEMS, by record id); a payload that is a gun (sentries, emplacements) adds its stats.
local EAGLE_REARM = 3837064536
local FAMILY_ORDER = { orbital = 1, eagle = 2, support = 9 }
local FAMILY_NOTE = { orbital = 'Orbital strike.', eagle = 'Eagle strike. The rearm time is shared by every Eagle.',
                      support = 'Support weapon drop; the weapon itself is under Support.' }

local function id_hex(id) return string.format('%08X%08X', 0, id) end

-- The entities that share `key`'s loadout package: a support weapon's hellpod rack and what it
-- carries (the C4 Pack: its detonator, the charge, the charge backpack).
KINDS[TYPES.package].kin = function(key)
    local t = tables[TYPES.package]
    local at = t and t.index[key]
    local blob = at and api.read(t.copies[1] + HEADER_BYTES, t.payload)
    if not blob or #blob ~= t.payload then return {} end
    local package, out = blob:sub(at + 9, at + 16), {}
    for other, off in pairs(t.index) do
        if other ~= key and blob:sub(off + 9, off + 16) == package then out[#out + 1] = other end
    end
    return out
end

-- The backpack a support weapon's hellpod carries with it (its ammo backpack: Autocannon, Recoilless,
-- Spear, W.A.S.P., Maxigun, Cremator, Belt-Fed GL, Airburst): a rack holding only the weapon and one
-- entity with charges (not a crate of several weapons and supply packs).
KINDS[TYPES.rack].pack = function(key)
    local rt, dt = tables[TYPES.rack], tables[TYPES.deposit]
    if not rt or not dt then return nil end
    local empty = string.rep('\0', 8)
    for _, at in pairs(rt.index) do
        local slots = api.read(rt.copies[1] + HEADER_BYTES + at, 512)
        local has, pack, other = false, nil, false
        for s = 0, slots and #slots == 512 and 7 or -1 do
            local k = slots:sub(s * 64 + 1, s * 64 + 8)
            if k == key then has = true
            elseif dt.index[k] and (pack == nil or pack == k) then pack = k
            elseif k ~= empty then other = true end
        end
        if has and pack and not other then return pack end
    end
end

-- A support weapon you place rather than fire (the C4 Pack: its entity is the charge, which has no
-- weapon record but an explosive one).
KINDS[TYPES.package].placed = function(key)
    return not (tables[T_WEAPON] and tables[T_WEAPON].index[key]) and tables[TYPES.explosive] ~= nil
           and tables[TYPES.explosive].index[key] ~= nil
end

-- A sentry's or emplacement's body, when its gun has no health of its own: the entity that mounts the
-- gun and has health (the Grenadier Battlement's). nil: the gun is the body.
KINDS[TYPES.health].body = function(gun)
    local ht, mt = tables[TYPES.health], tables[TYPES.mount]
    if not ht or not mt or ht.index[gun] then return nil end
    for holder, at in pairs(mt.index) do
        local mounts = ht.index[holder] and api.read(mt.copies[1] + HEADER_BYTES + at, 120)
        for m = 0, mounts and 4 or -1 do
            if mounts:sub(m * 24 + 1, m * 24 + 8) == gun then return holder end
        end
    end
end

-- 'BACKPACK. GUARD DOG (Drone)' -> 'backpack', 'Guard Dog (Drone)'
local function pretty(debug_name)
    local family, rest = debug_name:match('^%s*([^%.]+)%.%s*(.+)$')
    rest = (rest or debug_name):gsub('%a+', function(word)
        if #word <= 2 or word ~= word:upper() or not word:find('[AEIOUY]') then return word end
        return word:sub(1, 1) .. word:sub(2):lower()
    end)
    return (family or 'other'):lower(), rest
end

-- Several vehicles of a kind in a loadout (Settings, on by default): a stratagem's flags (StratagemInfo +260)
-- carry its vehicle kind, 0x00100000 exosuit, 0x00200000 FRV, 0x00400000 tank, and the loadout takes one
-- stratagem of each kind; on clears those bits (in memory), off puts them back. `original`: by stratagem
-- id, the flags as the game had them (kept across rescans).
MOD.vehicles = { on = false, original = {}, defs = {}, BITS = 1048576 }
function MOD.vehicles.collect(defs)
    local V = MOD.vehicles
    V.defs = {}
    for id, def in pairs(defs) do
        local flags = V.original[id] or peek4(def.at + 260)
        if flags and math.floor(flags / V.BITS) % 8 ~= 0 then
            V.original[id] = flags
            V.defs[#V.defs + 1] = { kind = def.kind, off = def.off, flags = flags }
        end
    end
    V.apply()
end
function MOD.vehicles.apply()
    local V = MOD.vehicles
    for _, d in ipairs(V.defs) do
        local want = V.on and d.flags - (math.floor(d.flags / V.BITS) % 8) * V.BITS or d.flags
        local t = tables[d.kind]
        for _, copy in ipairs(t and t.copies or {}) do
            local at = copy + HEADER_BYTES + d.off + 260
            if peek4(at) ~= want then api.write(at, u32_bytes(want)) end
        end
    end
end

-- Settings switches that change a field in many rows (off by default; off puts the game's values back):
--   bounce: stratagem balls stick on more surfaces: StratagemInfo +368 bit 0x02 cleared on every stratagem
--     that has it
--   reticle: sniper rifles show a crosshair in third person: WeaponData crosshair type (+404; +400 before game
--     build 25988413) 3 (the sniper rifles': none in third person) -> 0 (default), as the HD2 Equipment mod does
--   foliage: player rockets, launcher rounds and stratagem ordnance fly through tree canopies and bushes:
--     ProjectileInfo +248 raycast template 0 (damage) -> 3 (damage without foliage, what plasma bolts use) on
--     the impact-exploding player projectiles, by type and name hash (+8); game build 26088801 (build
--     25480438: template +244, no foliage 2)
-- `original`: by row, the value the game had (kept across rescans).
MOD.tweaks = {
    bounce = { on = false, original = {}, rows = {} },
    reticle = { on = false, original = {}, rows = {} },
    foliage = { on = false, original = {}, rows = {}, NO_FOLIAGE = 3, TARGETS = {
        [6] = 0x84F1CDC4, [11] = 0xF73287FE, [12] = 0x6B55E559, [14] = 0xF516C1C8, [17] = 0xA1701744,
        [18] = 0xFD691A89, [27] = 0xF796A3E6, [30] = 0xE3FF617D, [32] = 0x0B3CE509, [37] = 0xCB119C6D,
        [41] = 0x8800F269, [44] = 0x6D4E9963, [67] = 0xD0E7BB89, [69] = 0x84135F91, [72] = 0x91C46E0F,
        [73] = 0x02694B60, [74] = 0xA1701744, [76] = 0x7E66B2AD, [77] = 0xA1701744, [79] = 0xA1701744,
        [80] = 0x72EDB2F8, [82] = 0x12416AAE, [84] = 0x8E7C4D62, [86] = 0x12416AAE, [87] = 0xF62F1CD1,
        [92] = 0xDB3C0FF3, [94] = 0x5D4CBC38, [95] = 0x12416AAE, [98] = 0x844732B0, [101] = 0xD84656B7,
        [102] = 0x12416AAE, [112] = 0x0B3CE509, [117] = 0x122274B8, [118] = 0x0DF27E48, [122] = 0x943BD4B3,
        [129] = 0x9D946B50, [130] = 0x49B9185E, [132] = 0x5E95C9E2, [133] = 0x72EDB2F8, [134] = 0x0B3CE509,
        [139] = 0xF516C1C8, [143] = 0xEDD7AD4C, [147] = 0x780FF8A9, [148] = 0x8E7C4D62, [153] = 0x045580C1,
        [154] = 0x9D946B50, [155] = 0x8C935D03, [160] = 0x4211411F, [163] = 0x9A056E06, [164] = 0x6BD146D6,
        [173] = 0x5E95C9E2, [178] = 0xF3B7C565, [186] = 0xE441DAF0, [191] = 0x6B55E559, [194] = 0x00000000,
        [197] = 0xF516C1C8, [200] = 0xC4AE97A6, [205] = 0x203BCD08, [206] = 0x00000000, [209] = 0x8800F269,
        [211] = 0x89C98FA5, [213] = 0x72EDB2F8, [217] = 0x17D7C9B0, [219] = 0x12416AAE, [223] = 0xAE182F69,
        [227] = 0x74AD0033, [229] = 0xE4F875DB, [235] = 0x345DDEE2, [237] = 0x72EDB2F8, [238] = 0xF516C1C8,
        [242] = 0xF516C1C8, [243] = 0xE6C09ED9, [249] = 0x65466EE5, [251] = 0x00000000, [253] = 0xAFD4B511,
        [265] = 0x1666BC52, [267] = 0xF62F1CD1, [270] = 0x12416AAE, [276] = 0xAA1001AC, [285] = 0x61BA34A9,
        [289] = 0x74AD0033, [298] = 0x0651CEF6, [299] = 0xA2CD0019, [302] = 0x61BA34A9, [303] = 0xBFCC6788,
        [309] = 0x573CAE11, [317] = 0x74AD0033, [318] = 0x3D489B66, [325] = 0x573CAE11, [327] = 0x14AAD316,
        [335] = 0xCB392DF4, [341] = 0xA31CB0BA, [343] = 0x8A2E7689, [344] = 0x1E12F273, [346] = 0x91C46E0F,
        [351] = 0x9FBB83F9, [354] = 0xD45518B3, [355] = 0x07734A24 } },
}
-- the rows each switch changes: { kind, off (the field's offset in the table), want (on), size }
function MOD.tweaks.collect(defs)
    local B, F = MOD.tweaks.bounce, MOD.tweaks.foliage
    B.rows = {}
    for id, def in pairs(defs) do
        local b = api.read(def.at + 368, 1)
        local flags = B.original[id] or (b and b:byte())
        if flags and math.floor(flags / 2) % 2 == 1 then
            B.original[id] = flags
            B.rows[#B.rows + 1] = { kind = def.kind, off = def.off + 368, size = 1, game = flags, want = flags - 2 }
        end
    end
    local R, wt = MOD.tweaks.reticle, tables[T_WEAPON]
    R.rows = {}
    local xoff = KINDS[T_WEAPON].stride == 1240 and 404 or 400
    for key, off in pairs(wt and wt.index or {}) do
        local kind = R.original[key] or peek4(wt.copies[1] + HEADER_BYTES + off + xoff)
        if kind == 3 then
            R.original[key] = kind
            R.rows[#R.rows + 1] = { kind = T_WEAPON, off = off + xoff, size = 4, game = 3, want = 0 }
        end
    end
    F.rows = {}
    local pt = tables[T_PROJECTILE]
    for ptype, name in pairs(F.TARGETS) do
        local off = pt and pt.index[ptype]
        local at = off and pt.copies[1] + HEADER_BYTES + off
        local template = at and (F.original[ptype] or peek4(at + 248))
        if at and peek4(at + 8) == name and template == 0 then
            F.original[ptype] = template
            F.rows[#F.rows + 1] = { kind = T_PROJECTILE, off = off + 248, size = 4, game = 0, want = F.NO_FOLIAGE }
        end
    end
    log(string.format('switches: stratagem bounce %d stratagems, sniper crosshair %d weapons, foliage pass-through %d of %d projectiles',
        #B.rows, #R.rows, #F.rows, (function() local n = 0 for _ in pairs(F.TARGETS) do n = n + 1 end return n end)()))
    MOD.tweaks.apply()
end
function MOD.tweaks.apply()
    for _, name in ipairs({ 'bounce', 'reticle', 'foliage' }) do
        local T = MOD.tweaks[name]
        for _, r in ipairs(T.rows) do
            local value = T.on and r.want or r.game
            local bytes = r.size == 1 and string.char(value) or u32_bytes(value)
            local t = tables[r.kind]
            for _, copy in ipairs(t and t.copies or {}) do
                local at = copy + HEADER_BYTES + r.off
                if api.read(at, r.size) ~= bytes then api.write(at, bytes) end
            end
        end
    end
end

local function build_stratagems()
    for k = #weapons, 1, -1 do
        if weapons[k].stratagem or weapons[k].mounted then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    -- A Guard Dog, from its stratagem's payloads: its hellpod rack carries the backpack (first slot, +0),
    -- whose charges (DepositComponentData) name the drone (+24); the drone's first mount (+0) is its gun.
    -- Returns { drone = key, gun = key or nil }, or nil when no payload leads to a drone.
    local function drone_of(keys)
        local rt, dt, mt = tables[TYPES.rack], tables[TYPES.deposit], tables[TYPES.mount]
        if not rt or not dt then return nil end
        local function entity(t, at)
            local k = api.read(t.copies[1] + HEADER_BYTES + at, 8)
            if k and #k == 8 and (u32(k, 0) ~= 0 or u32(k, 4) ~= 0) then return k end
        end
        for _, key in ipairs(keys) do
            local rack = rt.index[key]
            local pack = rack and entity(rt, rack)
            local deposit = pack and dt.index[pack]
            local drone = deposit and entity(dt, deposit + 24)
            if drone then
                local mount = mt and mt.index[drone]
                return { drone = drone, gun = mount and entity(mt, mount) }
            end
        end
    end
    local guns, sentries = {}, {}
    for _, w in ipairs(weapons) do
        if w.key then guns[w.key] = true end
        if w.slot == 'Stratagems' then
            w.sentry_defs = {}
            local body = KINDS[TYPES.health].body(w.key)
            sentries[w.key] = w
            if body then sentries[body] = w end
        end
    end
    local defs = {}
    for _, group in ipairs(stratagem_groups) do
        local entry = tables[group]
        for id, off in pairs(entry.index) do
            if not defs[id] then defs[id] = { kind = group, off = off, at = entry.copies[1] + HEADER_BYTES + off } end
        end
    end
    MOD.vehicles.collect(defs)
    MOD.tweaks.collect(defs)
    local list, known = {}, {}
    local function add(id, name, family, payloads, nodes, def)
        local keys = {}
        if def then
            local head = api.read(def.at + 152, 12)
            local at, count = head and u32(head, 0) + u32(head, 4) * 4294967296, head and u32(head, 8)
            local blob = count and count > 0 and count <= 32 and api.read(at, 8 * count)
            for k = 1, blob and count or 0 do keys[#keys + 1] = blob:sub(8 * k - 7, 8 * k) end
        end
        for _, h in ipairs(payloads) do keys[#keys + 1] = hash_key(h) end
        -- a sentry's or emplacement's stratagem: its cooldown goes on the sentry's own entry
        local sentry = def and by_hash[KINDS[TYPES.health].sentry_ids[id] or '']
        for _, key in ipairs(keys) do sentry = sentry or sentries[key] end
        if sentry and sentry.sentry_defs then
            table.insert(sentry.sentry_defs, KINDS[TYPES.health].main_ids[id] and 1 or #sentry.sentry_defs + 1, def)
            local bits = peek4(def.at + 104)
            log(string.format('stratagem %s: cooldown on %s (%.1f s)', id_hex(id), sentry.name, bits and bits_to_f32(bits) or -1))
            return nil
        end
        local drone = family == 'backpack' and drone_of(keys) or nil
        -- a vehicle: the payload that is one (VehicleComponentData), of a 'VEHICLES.' stratagem (mission
        -- objects like the Bug Plug and the President's reward Patriot call vehicles in too: not listed)
        local vehicle, vt = nil, tables[TYPES.vehicle]
        for _, key in ipairs(keys) do
            if not vehicle and vt and vt.index[key] and family == 'vehicles' then vehicle = key end
        end
        if vehicle then
            local V = KINDS[TYPES.vehicle]
            name = V.ENTITIES[string.format('%08X%08X', u32(vehicle, 4), u32(vehicle, 0))] or V.TITLES[name] or name
        end
        local entry = { name = name, slot = vehicle and 'Mechas' or 'Stratagems', hash = id_hex(id),
                        note = vehicle and 'Vehicle. The weapons it carries are listed under it.' or FAMILY_NOTE[family] or '',
                        rows = {}, by_id = {},
                        stratagem = { id = id, family = family, def = def, payloads = keys, nodes = nodes, guns = guns,
                                      drone = drone, vehicle = vehicle } }
        list[#list + 1] = entry
        return entry
    end
    for _, s in ipairs(STRATAGEMS) do
        known[s[1]] = true
        add(s[1], s[2], s[3], s[4], s[5], defs[s[1]])
    end
    local named, total = 0, 0
    for id, def in pairs(defs) do
        total = total + 1
        local lo, hi = peek4(def.at + 16), peek4(def.at + 20)
        local text = not known[id] and id ~= EAGLE_REARM and lo and hi and read_text(lo + hi * 4294967296)
        if text then
            local family, name = pretty(text)
            name = family == 'backpack' and KINDS[TYPES.jumppack].TITLES[name] or name
            named = named + 1
            local entry = add(id, name, family, {}, {}, def)
            if entry and entry.stratagem.vehicle then
                log('vehicle ' .. entry.name .. ' (' .. text .. ', ' .. id_hex(id) .. '): entity ' ..
                    string.format('%08X%08X', u32(entry.stratagem.vehicle, 4), u32(entry.stratagem.vehicle, 0)))
            elseif entry then
                entry.note = family:sub(1, 1):upper() .. family:sub(2) .. ' stratagem (' .. text .. ').'
                local d = entry.stratagem.drone
                if d then
                    entry.note = 'Guard Dog backpack: the drone and the gun it carries. ' .. entry.note
                    local function hex8(k) return k and string.format('%08X%08X', u32(k, 4), u32(k, 0)) or 'none' end
                    log('guard dog ' .. entry.name .. ' (' .. id_hex(id) .. '): drone ' .. hex8(d.drone) .. ', gun ' .. hex8(d.gun))
                end
            end
        end
    end
    -- mission vehicles: by their first entity's hash
    for _, v in ipairs(KINDS[TYPES.vehicle].NATIVE) do
        local vt, keys = tables[TYPES.vehicle], {}
        for k = 3, #v do
            if vt and vt.index[hash_key(v[k])] then keys[#keys + 1] = hash_key(v[k]) end
        end
        if keys[1] then
            list[#list + 1] = { name = v[1], short = v[2], slot = 'Mechas', hash = v[3], rows = {}, by_id = {},
                                note = 'Vehicle. The weapons it carries are listed under it.',
                                stratagem = { family = 'vehicles', native = true, payloads = {}, nodes = {}, guns = {},
                                              vehicle = keys[1], twins = { unpack(keys, 2) } } }
        end
    end
    table.sort(list, function(a, b)
        local fa, fb = FAMILY_ORDER[a.stratagem.family] or 5, FAMILY_ORDER[b.stratagem.family] or 5
        if fa ~= fb then return fa < fb end
        if a.stratagem.family ~= b.stratagem.family then return a.stratagem.family < b.stratagem.family end
        return a.name:lower() < b.name:lower()
    end)
    -- the weapons each vehicle carries (its mounts), listed after it; one entry per weapon entity
    local MOUNTS = { [0x7BDEC47B] = 'Left arm', [0x47775624] = 'Right arm', [0x23CC0657] = 'Gun', [0xCB79FA57] = 'Main gun',
                     [0x409652FC] = 'Driver gun', [0x3ECFB64B] = 'Rack', [0x372F0418] = 'Turret' }
    local mt, mounted = tables[TYPES.mount], {}
    for _, entry in ipairs(list) do
        weapons[#weapons + 1] = entry
        by_hash[entry.hash] = entry
        local at = entry.stratagem.vehicle and mt and mt.index[entry.stratagem.vehicle]
        for m = 0, at and 4 or -1 do
            local base = mt.copies[1] + HEADER_BYTES + at + m * 24
            local lo, hi, label = peek4(base), peek4(base + 4), peek4(base + 16)
            local hash = lo and hi and (lo ~= 0 or hi ~= 0) and string.format('%08X%08X', hi, lo)
            local w = hash and mounted[hash]
            if w then
                w.note = w.note:gsub('%.$', '') .. ', ' .. entry.name .. '.'
            elseif hash and not by_hash[hash] then
                w = { name = (entry.short or entry.name) .. ': ' .. (MOUNTS[label or 0] or ('Weapon ' .. (m + 1))), slot = 'Mechas', hash = hash,
                      key = hash_key(hash), rows = {}, by_id = {}, mounted = true, note = 'Mounted on the ' .. entry.name .. '.' }
                mounted[hash] = w
                weapons[#weapons + 1] = w
                by_hash[hash] = w
            end
        end
    end
    log(string.format('stratagems: %d group table(s), %d definitions, %d listed (%d from the catalog, %d named in game)',
        #stratagem_groups, total, #list, #STRATAGEMS, named))
    for _, entry in ipairs(list) do entry.stratagem.rearm = defs[EAGLE_REARM] end
end

-- A sentry's or emplacement's body (issue #44), by its entity (`key`): health +0 (with each zone that has a
-- pool of its own the same size: the emplacements' one zone, 1000 of the HMG's 1000), the durable ratio
-- (+268, with the zones that have the same), the armor (+280, zones +216; sentries and emplacements), then for each destruction level the demolition force that
-- destroys it (its tier; direct hits: the level's own when set).
KINDS[TYPES.destruction].body_rows = function(entry, key, section, prefix)
    local ht = tables[TYPES.health]
    local at = ht and ht.index[key]
    if not at then return end
    local zones = {}
    for z = 0, 37 do
        local base = at + 520 + z * 552
        if (KINDS[TYPES.destruction].at(ht.copies[1] + HEADER_BYTES + base + 96) or 0) ~= 0 then zones[#zones + 1] = { z, base } end
    end
    local function follow(id, offset, zone_offset, storage, limit)
        local parts = { part(prefix .. id, TYPES.health, at + offset, storage, limit) }
        local own = default_of(parts[1].field)
        for _, z in ipairs(zones) do
            local p = part(prefix .. id .. '_z' .. z[1], TYPES.health, z[2] + zone_offset, storage, limit)
            if own and default_of(p.field) == own then parts[#parts + 1] = p end
        end
        return parts
    end
    add_row(entry, section, prefix .. 'health', 'Health', 'u32', follow('health', 0, 232, 'u32', 1000000), 0, 100000, 5, 25)
    local durable = add_row(entry, section, prefix .. 'durable', 'Durable ratio (0-1)', 'f32', follow('durable', 268, 204, 'f32', 1),
                            0, 1, 0.05, 0.1)
    durable.note = "0: hits deal their normal damage, 1: their durable damage (the weapon's lower one)"
    if prefix == 'unit_' then   -- (issue #86; the deployers have their own Armor row) +280, with the zones that match
        add_row(entry, section, prefix .. 'armor', 'Armor', 'u32', follow('armor', 280, 216, 'u32', 10), 0, 10, 1, 1)
    end
    KINDS[TYPES.destruction].demolition_rows(entry, key, section, prefix, at)
end

-- For each destruction level of the entity (`key`) the demolition force that destroys it (its tier; direct
-- hits: the level's own when set). `at`: its health record, when it has one (the tier it dies at).
KINDS[TYPES.destruction].demolition_rows = function(entry, key, section, prefix, at)
    local spec = KINDS[TYPES.destruction]
    local n = spec.ready() and tables[TYPES.destruction_map].index[key]
    local block = n and spec.found[n + 1]
    if not block then return end
    local base = block - spec.found[1]
    local death = at and field_at(TYPES.health, at + spec.DEATH, 'u32', 100)
    local levels = {}
    for level = 0, 2 do
        for _, o in ipairs({ 16, 32 }) do
            local f = field_at(TYPES.destruction, base + level * 48 + o, 'tier', 1000)
            local own = default_of(f)
            if own and own > 0 then
                local t = spec.at(tables[TYPES.destruction].copies[1] + HEADER_BYTES + base + level * 48 + o + 8)
                if death and t and t == default_of(death) then f.death = death end
                levels[#levels + 1] = { f = f, level = level, hit = o == 32 }
            end
        end
    end
    local stages = 0
    for _, l in ipairs(levels) do if not l.hit then stages = stages + 1 end end
    for k, l in ipairs(levels) do
        local id = prefix .. 'demolition' .. (l.level > 0 and l.level + 1 or '') .. (l.hit and '_hit' or '')
        local label = (stages > 1 and not l.hit) and ('Demolition force, stage ' .. (l.level + 1))
                      or ('Demolition force to destroy it' .. (l.hit and ' (direct hits)' or ''))
        local row = add_row(entry, section, id, label, 'u32', { { id = id, field = l.f } }, 1, 250, 10, 10)
        if k == 1 then row.note = 'the game\'s tiers: 10 small arms, 20 HMG, 30 autocannon, 40 Strider, 50 orbital, 60 Hellbomb, 250 never' end
    end
    if #levels > 0 then
        local t = {}
        for _, l in ipairs(levels) do t[#t + 1] = (l.hit and 'hit ' or 'level ') .. (l.level + 1) .. ' ' .. tostring(default_of(l.f)) end
        log('destruction: ' .. entry.name .. ' settings ' .. n .. ': ' .. table.concat(t, ', ') ..
            ', on death ' .. tostring(death and default_of(death)))
    end
end

-- A unit's own rows (a Guard Dog's drone, a sentry or emplacement): health +0, spotting range +0,
-- target search interval +0 / +4, turret turn speed +12 horizontal / +8 vertical, where it has them.
local function unit_rows(entry, key, section, prefix)
    local function unit(kind, id, label, offset, storage, max, small, big)
        local at = tables[kind] and tables[kind].index[key]
        if at then
            add_row(entry, section, prefix .. id, label, storage, { part(prefix .. id, kind, at + offset, storage, 1000000) },
                    0, max, small, big)
        end
    end
    if prefix == 'unit_' then KINDS[TYPES.destruction].body_rows(entry, key, section, prefix)
    else unit(TYPES.health, 'health', 'Health', 0, 'u32', 100000, 5, 25) end
    unit(TYPES.sensor, 'sight', 'Spotting range (m)', 0, 'f32', 1000, 1, 5)
    unit(TYPES.detector, 'search_min', 'Target search interval, min (s)', 0, 'f32', 60, 0.05, 0.25)
    unit(TYPES.detector, 'search_max', 'Target search interval, max (s)', 4, 'f32', 60, 0.05, 0.25)
    unit(TYPES.turret, 'turn_h', 'Turn speed, horizontal (deg/s)', 12, 'f32', 3600, 1, 10)
    unit(TYPES.turret, 'turn_v', 'Turn speed, vertical (deg/s)', 8, 'f32', 3600, 1, 10)
    -- (from LovedeHua's fork) a sentry's aiming limits (TurretComponentData +20 / +24 lowest / highest, +28 / +32
    -- left / right, degrees); an axis that cannot move (lowest = highest) stays as it is
    local tt = section == 'Sentry' and tables[TYPES.turret]
    local at = tt and tt.index[key]
    for _, c in ipairs(at and {
        { 'aim_down', 'Aim limit, down (deg)', 20, -90, 24, 'negative: below level, -90 straight down' },
        { 'aim_up', 'Aim limit, up (deg)', 24, -90, 20, '90: straight up' },
        { 'aim_left', 'Aim limit, left (deg)', 28, -180, 32, '-180 with right at 180: all the way round' },
        { 'aim_right', 'Aim limit, right (deg)', 32, -180, 28, '180 with left at -180: all the way round' },
    } or {}) do
        local f, other = field_at(TYPES.turret, at + c[3], 'f32', 180), field_at(TYPES.turret, at + c[5], 'f32', 180)
        f.signed, other.signed = true, true
        local v, o = default_of(f), default_of(other)
        if v and o and v ~= o and math.abs(v) <= -c[4] then
            local p = part(prefix .. c[1], TYPES.turret, at + c[3], 'f32', 180)
            p.field.signed = true
            add_row(entry, 'Sentry aiming', prefix .. c[1], c[2], 'f32', { p }, c[4], -c[4], 1, 5).note = c[6]
        end
    end
    MOD.faction.row(entry, section, prefix .. 'faction', { key })
end

-- A vehicle's rows (by its entity, `key`): its health component: health +0 (i32), armor +280 (the
-- default zone's), then each damageable zone (38 of 552 bytes from +520; +96 name, 0: unused; +216 armor,
-- +232 health, -1: none). Zones are named from MOD.vehicle_parts (by the name's hash), else numbered.
-- twins: the same vehicle's other entities (the GATER's two), written along.
-- Validated EXO weapon-arm health components; other vehicle mounts are left alone.
MOD.exo_mounted = { ['EXO-45 Patriot Exosuit'] = true, ['EXO-49 Emancipator Exosuit'] = true,
                    ['EXO-51 Lumberer Exosuit'] = true, ['EXO-55 Breakthrough Exosuit'] = true }
KINDS[TYPES.vehicle].rows = function(entry, key, twins)
    local t = tables[TYPES.health]
    local at = t and t.index[key]
    if not at then return end
    local top = t.copies[1] + HEADER_BYTES
    local others = {}
    for _, k in ipairs(twins or {}) do others[#others + 1] = t.index[k] end
    local function parts(id, offset, storage, limit)
        local out = { part(id, TYPES.health, at + offset, storage, limit) }
        for n, o in ipairs(others) do out[#out + 1] = part(id .. '_' .. (n + 1), TYPES.health, o + offset, storage, limit) end
        return out
    end
    add_row(entry, 'Vehicle', 'health', 'Health', 'u32', parts('health', 0, 'u32', 10000000), 0, 1000000, 50, 500)
    add_row(entry, 'Vehicle', 'armor', 'Armor', 'u32', parts('armor', 280, 'u32', 100), 0, 10, 1, 1)
    -- regeneration (issue #73, tested in game by its reporter): health per second +4 and its rate in the
    -- regeneration phase +20, written together; it starts this long after the last damage +12 (all 0 on
    -- vehicles). Damaged parts heal; a destroyed one (a wheel) stays destroyed: that state is not in the file
    local regen_parts = parts('regen', 4, 'f32', 1000000)
    for _, p in ipairs(parts('regen_phase', 20, 'f32', 1000000)) do regen_parts[#regen_parts + 1] = p end
    -- Share this vehicle's regeneration slider with its physical left/right arm
    -- health components. Destroyed parts and shield-plate zones may not restore.
    if MOD.exo_mounted[entry.name] then
        local mt = tables[TYPES.mount]
        local mounts = mt and mt.index[key]
        local seen = {}
        for m = 0, mounts and 4 or -1 do
            local mbase = mt.copies[1] + HEADER_BYTES + mounts + m * 24
            local label = peek4(mbase + 16)
            if label == 0x7BDEC47B or label == 0x47775624 then
                local lo, hi = peek4(mbase), peek4(mbase + 4)
                local mountkey = lo and hi and hash_key(string.format('%08X%08X', hi, lo))
                local arm = mountkey and t.index[mountkey]
                if arm and arm ~= at and not seen[arm] then
                    local hp = default_of(field_at(TYPES.health, arm, 'u32', 10000000))
                    local armor = default_of(field_at(TYPES.health, arm + 280, 'u32', 100))
                    if hp and hp > 0 and hp <= 1000000 and armor and armor <= 10 then
                        seen[arm] = true
                        regen_parts[#regen_parts + 1] = part('regen_arm_' .. m, TYPES.health, arm + 4, 'f32', 1000000)
                        regen_parts[#regen_parts + 1] = part('regen_arm_phase_' .. m, TYPES.health, arm + 20, 'f32', 1000000)
                    end
                end
            end
        end
    end
    local regen = add_row(entry, 'Vehicle', 'regen', 'Regeneration (health/s)', 'f32', regen_parts, 0, 100000, 5, 50)
    regen.note = 'damaged parts heal; destroyed parts stay destroyed'
    add_row(entry, 'Vehicle', 'regen_delay', 'Regeneration delay after damage (s)', 'f32',
            parts('regen_delay', 12, 'f32', 3600), 0, 600, 0.1, 1)
    -- the melee button's stomp is an ability, no record names its damage: row 253 (unnamed), the wiki's 9 values (609, the same, is the Cyborg Lieutenant's)
    if MOD.exo_mounted[entry.name] then MOD.melee_rows(entry, 253, 'Stomp', 'stomp_').tip = { 'Every exosuit shares this stomp.' } end
    MOD.physics.rows(entry, key)
    local n = 0
    for z = 0, 37 do
        local base = 520 + z * 552
        local name = peek4(top + at + base + 96)
        if name and name ~= 0 then
            n = n + 1
            local label = MOD.vehicle_parts[name] or ('Part ' .. n)
            local id = 'zone' .. z
            local health = read_field(field_at(TYPES.health, at + base + 232, 'u32', 10000000))
            if health then
                add_row(entry, 'Body parts', id .. '_health', label .. ' health', 'u32',
                        parts(id .. '_health', base + 232, 'u32', 10000000), 0, 1000000, 10, 100)
            end
            add_row(entry, 'Body parts', id .. '_armor', label .. ' armor', 'u32',
                    parts(id .. '_armor', base + 216, 'u32', 100), 0, 10, 1, 1)
        end
    end
end

-- ---------------------------------------------------------------- vehicle handling (offline)
-- The host reads each vehicle's physics file (named as its entity) out of the game's archives into memory and names
-- it in SHODAN_PHYSICS (base address, files['<entity hex>.<type hex>'] = { at, size }); these rows edit it there like a table
-- (TYPES.physics: one block from `base`), Install writes the changed files into a patch archive (offline/vehicles.lua).
-- Layout (z up, -y the front): the body's mass, then 28 bytes of 0xFF and 44 00 00 00; its centre of
-- mass +56 (x, y, z). 'VR  ' + 16: the vehicle; +12 eight offsets from there to its blocks: [1] wheels ('VRW ': +4
-- count, +8 offsets from the tag; a wheel: +12 position, then +24 grip, +28 radius, +72 spring, +76 damping, +80
-- suspension travel), [2] engine ('VRE ': +24 top rpm, +28 peak torque), [3] gears ('VRT ': +52 count, +56 ratios),
-- [5] brakes ('VRB ': +16, +32 two brake torques, by wheel; tested in game 2026-10-28). Names after the FRV Anti-Flip mod's README.
TYPES.physics = 0x5F7203C8
MOD.physics = { MASS = string.rep('\255', 28) .. '\68\0\0\0' }
MOD.physics.TIPS = {   -- row id (without front_/rear_, gears as 'gear') -> hover tip
    mass = { 'Heavier: speeds up and stops more slowly, shoves enemies and wrecks aside, and is harder to flip.',
             'Lighter: quicker off the line, but bounces over bumps and gets thrown around by explosions.' },
    com = { 'How high the balance point sits. Lower (even below 0): stays flat in hard turns and over rocks.',
            'Higher: leans more and tips over in sharp turns.' },
    torque = { 'How hard the engine pushes. Higher: faster acceleration and steeper hills, but more wheelspin.',
               'It does not raise the top speed by itself: that comes from the engine speed and the gears.' },
    rpm = { 'How fast the engine may spin before it stops pulling. Higher: a higher top speed in every gear,',
            'as long as the engine torque is enough to get there.' },
    gear = { 'How much this gear multiplies the engine. Higher: stronger pull, but it tops out sooner.',
             'Lower: faster in this gear, weaker on hills and from a stop.' },
    brake = { 'Higher: stops in a shorter distance. Too high locks the wheels, and it skids instead of stopping.',
              '0: these wheels do not brake at all.' },
    grip = { 'How well the tyres hold the ground. Higher: sharper turns, less sliding and wheelspin.',
             'Front grip lower than the rear: it turns wide. Rear lower than the front: the back slides out.' },
    radius = { 'Bigger wheels: a higher top speed and more room under the body, but a weaker pull.',
               'Smaller: quicker to speed up, slower at the top, and it scrapes over rocks.' },
    spring = { 'Higher: a stiffer ride, less lean in turns, bumps kick harder.',
               'Lower: a softer ride, the body leans in turns and sags.' },
    damping = { 'How fast the springs settle after a bump. Higher: settles at once, a firmer ride.',
                'Lower: keeps bouncing after every bump.' },
    travel = { 'More: soaks up big bumps and keeps the wheels on the ground on rough terrain.',
               'Less: bumps go straight into the body and it wobbles.' },
}
function MOD.physics.host()
    local host = rawget(_G, 'SHODAN_PHYSICS')
    if host then
        tables[TYPES.physics] = tables[TYPES.physics]
                                or { copies = { host.base - HEADER_BYTES }, index = {}, type = TYPES.physics, fixed = true }
    end
    return host
end
function MOD.physics.rows(entry, key)
    local host = MOD.physics.host()
    if not host then return end
    if MOD.exo_mounted[entry.name] then return MOD.physics.exo_rows(entry, host) end
    local file = host.files[string.format('%08X%08X', u32(key, 4), u32(key, 0)) .. '.5F7203C8F280DAB8']
    local d = file and api.read(host.base + file.at, file.size)
    if not d then return end
    local function f32(o) return bits_to_f32(u32(d, o)) end
    local function row(section, id, label, offsets, min, max, small, big, note)
        local list = {}
        for n, o in ipairs(offsets) do
            list[n] = part('phys_' .. id .. (n > 1 and '_' .. n or ''), TYPES.physics, file.at + o, 'f32', 1000000)
            list[n].field.signed = min < 0
        end
        local r = add_row(entry, section, 'phys_' .. id, label, 'f32', list, min, max, small, big)
        r.note = note
        r.tip = MOD.physics.TIPS[(id:gsub('^front_', ''):gsub('^rear_', ''):gsub('^gear%d+$', 'gear'))]
        return r
    end
    local mass = d:find(MOD.physics.MASS, 1, true)
    mass = mass and mass - 5
    if mass then
        row('Handling', 'mass', 'Weight (kg)', { mass }, 1, 1000000, 50, 500, 'heavier: slower to speed up, harder to push or roll')
        row('Handling', 'com', 'Center of mass height (m)', { mass + 64 }, -5, 5, 0.05, 0.25, 'lower: harder to roll over')
    end
    local vr = d:find('VR  ', 1, true)
    local base = vr and vr - 1 + 16
    local function block(k, tag)
        local o = base and base + u32(d, base + 12 + 4 * (k - 1))
        return o and o + 4 <= #d and d:sub(o + 1, o + 4) == tag and o or nil
    end
    local engine, gears, brakes, wheels = block(2, 'VRE '), block(3, 'VRT '), block(5, 'VRB '), block(1, 'VRW ')
    if engine then
        row('Handling', 'torque', 'Engine torque', { engine + 28 }, 0, 1000000, 50, 500, 'pulling power: how fast it speeds up and climbs')
        row('Handling', 'rpm', 'Top engine speed (rpm)', { engine + 24 }, 100, 100000, 100, 1000, 'with the gears, sets the top speed')
    end
    local count = gears and u32(d, gears + 52) or 0
    for g = 1, count <= 8 and count or 0 do
        row('Handling', 'gear' .. g, 'Gear ' .. g .. ' ratio', { gears + 52 + 4 * g }, 0.05, 50, 0.05, 0.25,
            g == 1 and 'lower: a higher top speed in that gear, a weaker pull' or nil)
    end
    -- the brakes: two strengths, each wheel's -8 picks one (FRVs: 0 the rear, 1 the front); the handbrake grabs the
    -- wheels with +68 set (the FRVs' rear), at their strength (ids kept from the first labels: saved values still apply)
    local n = wheels and u32(d, wheels + 4) or 0
    if brakes then
        local front, rear, hand = { false, false }, { false, false }, { false, false }
        for w = 0, n <= 64 and n - 1 or -1 do
            local w0 = wheels + u32(d, wheels + 8 + 4 * w) + 12
            local k = u32(d, w0 - 8) + 1
            if k <= 2 then
                if f32(w0 + 4) > 0 then rear[k] = true else front[k] = true end
                hand[k] = hand[k] or u32(d, w0 + 68) == 1
            end
        end
        for _, k in ipairs({ 2, 1 }) do   -- (the front's first, on all five)
            local id = k == 1 and 'brake' or 'handbrake'
            local label = front[k] and rear[k] and 'Brake strength (' .. k .. ')' or front[k] and 'Front brake strength'
                          or rear[k] and 'Rear brake strength'
            if label then
                row('Handling', id, label, { brakes + 16 * k }, 0, 1000000, 100, 1000,
                    hand[k] and 'the handbrake uses these brakes too' or nil).tip = MOD.physics.TIPS.brake
            end
        end
    end
    -- the wheels: front and rear on four, all together on more (the tanks' road wheels)
    local groups = n == 4 and { { 'front_', 'Front ' }, { 'rear_', 'Rear ' } } or { { '', '' } }
    local at = { {}, {} }
    for w = 0, n <= 64 and n - 1 or -1 do
        local w0 = wheels + u32(d, wheels + 8 + 4 * w) + 12
        local side = n == 4 and f32(w0 + 4) > 0 and 2 or 1
        at[side][#at[side] + 1] = w0
    end
    for k, g in ipairs(groups) do
        local function list(o) local out = {}; for i, w0 in ipairs(at[k]) do out[i] = w0 + o end return out end
        local function L(text) return g[2] == '' and text:sub(1, 1):upper() .. text:sub(2) or g[2] .. text end
        if #at[k] > 0 then
            row('Wheels', g[1] .. 'grip', L('wheel grip'), list(24), 0, 20, 0.05, 0.25)
            row('Wheels', g[1] .. 'radius', L('wheel radius (m)'), list(28), 0.05, 5, 0.01, 0.05)
            row('Wheels', g[1] .. 'spring', L('spring stiffness'), list(72), 0, 1000, 1, 5,
                'lower: softer, the body sags (at 1 it barely moves)')
            row('Wheels', g[1] .. 'damping', L('damping'), list(76), 0, 100, 0.05, 0.25, 'higher: less bounce')
            row('Wheels', g[1] .. 'travel', L('suspension travel'), list(80), 0, 100, 0.1, 1,
                'how far the wheels can move up and down; lower: the body wobbles a lot')
        end
    end
end

-- The exosuits share one state machine (79E4B3D2DA5E45E3.A486D4045106165C); their walk is root motion, played at
-- move_speed / a constant (the walk states' speed formula: variable 0, the constant, divide, stop) and their turn at
-- a constant (turn_left, turn_right: the constant, stop), so these set how fast they walk and turn; the other
-- clips (STATES) play at a constant too (all tested in game 2026-10-28). Layout: +8 the groups (count, offsets); a
-- layer: +8 state count, +12 offsets; a state: +0 name, +80 formula word count, +84 its offset from the state.
MOD.physics.STATES = {   -- state name -> row
    ['418EC822255AD5EC'] = 'exo_turn', BFAD4C0A776AF89B = 'exo_turn',                         -- turn_left, turn_right
    ['2AA09DE1A0451563'] = 'exo_stomp', A89ACDE8773C980F = 'exo_stomp',                       -- stomp, stomp_dash
    ['77725261E4F3414A'] = 'exo_enter', E6072F6900D7DB47 = 'exo_enter',                       -- enter, exit
    AA31B8995EC829C5 = 'exo_land', ['3484F2A8401196AE'] = 'exo_land',                         -- land, transport_land
    ['98C31BA14A25FA73'] = 'exo_stagger', AA32D8EE1A17E7F5 = 'exo_stagger', ['1876EADD7093399C'] = 'exo_stagger',
    ['3F8244CA5C2C2357'] = 'exo_stagger', B1F86E505DDD8839 = 'exo_stagger', ['2FECF347ABE5F357'] = 'exo_stagger',
    ['415D903053F3AE2A'] = 'exo_stagger', E9E0C2EE3CF1C524 = 'exo_stagger',                   -- the stagger clips
}
function MOD.physics.exo_rows(entry, host)
    local file = host.files['79E4B3D2DA5E45E3.A486D4045106165C']
    local d = file and api.read(host.base + file.at, file.size)
    if not d then return end
    local at_of = { exo_walk = {}, exo_turn = {}, exo_stomp = {}, exo_enter = {}, exo_land = {}, exo_stagger = {} }
    local groups = u32(d, 8)
    for g = 0, u32(d, groups) - 1 do
        local layer = groups + u32(d, groups + 4 + 4 * g)
        for k = 0, u32(d, layer + 8) - 1 do
            local at = layer + u32(d, layer + 12 + 4 * k)
            local n, f = u32(d, at + 80), at + u32(d, at + 84)
            if f + 16 <= #d and n >= 4 and u32(d, f) == 0x7f900000 and u32(d, f + 8) == 0x7f800003
               and u32(d, f + 12) == 0x7fa00000 then
                table.insert(at_of.exo_walk, file.at + f + 4)
            elseif f + 8 <= #d and n == 2 and u32(d, f + 4) == 0x7fa00000 then
                local id = MOD.physics.STATES[string.format('%08X%08X', u32(d, at + 4), u32(d, at))]
                if id then table.insert(at_of[id], file.at + f) end
            end
        end
    end
    -- one value for all four (field 'exo:<id>'): it multiplies the game's, or divides for the walk's divisor
    for _, s in ipairs({ { 'exo_walk', 'Walk speed (x)', true }, { 'exo_turn', 'Turn speed (x)' },
                         { 'exo_stomp', 'Stomp speed (x)' }, { 'exo_enter', 'Get in and out speed (x)' },
                         { 'exo_land', 'Drop landing speed (x)' }, { 'exo_stagger', 'Stagger recovery speed (x)' } }) do
        local list = at_of[s[1]]
        if #list > 0 then
            local lead = { id = s[1], field = field_at(0, 'exo:' .. s[1], 'virtual', 1000) }
            lead.field.default = 1
            local p = { lead }
            for n, o in ipairs(list) do p[#p + 1] = part(s[1] .. '_' .. n, TYPES.physics, o, 'f32', 1000000) end
            local r = add_row(entry, 'Movement', s[1], s[2], 'f32', p, 0.05, 10, 0.05, 0.25)
            r.lead, r.mult, r.inverse, r.note = true, true, s[3], 'all four exosuits share it'
        end
    end
end

-- Enemy animation speed: the state machine of each enemy's unit (MOD.ENEMY_ANIM, loaded by the host like the
-- exosuits'), every state that plays at a constant (the constant, stop) x the row of its kind (attacks, hit
-- reactions, the rest). Their attacks follow their animations (bugs at 2x attacked sooner in game, 2026-10-28; the
-- Helldiver's actions did not). Enemies with the same state machine share the values (one field per state machine).
function MOD.physics.constants(d)   -- the offsets of the states' constant playback speeds
    local out = {}
    local groups = u32(d, 8)
    for g = 0, groups + 4 <= #d and u32(d, groups) - 1 or -1 do
        local layer = groups + u32(d, groups + 4 + 4 * g)
        for k = 0, layer + 12 <= #d and u32(d, layer + 8) - 1 or -1 do
            local at = layer + u32(d, layer + 12 + 4 * k)
            local n, f = u32(d, at + 80), at + u32(d, at + 84)
            local exponent = n >= 2 and f + 8 <= #d and math.floor(u32(d, f) / 8388608) % 256
            if exponent and exponent ~= 0 and exponent ~= 255 and u32(d, f + 4) == 0x7fa00000 then out[#out + 1] = f end
        end
    end
    return out
end
function MOD.physics.anim_rows(entry)
    local host = MOD.physics.host()
    if not host or not MOD.ENEMY_ANIM then return end
    local function sm_of(page) local m = page.enemy.members[1]; return m and MOD.ENEMY_ANIM[m.e[5]] end
    local sm = sm_of(entry)
    local file = sm and host.files[sm .. '.A486D4045106165C']
    if not file then return end
    -- each state's kind (MOD.ENEMY_ANIM_KIND, by its name: scratch\enemy_actions.py); a count that differs (the game
    -- changed the file): all 'o'
    local offsets = MOD.physics.constants(api.read(host.base + file.at, file.size))
    local kinds = MOD.ENEMY_ANIM_KIND and MOD.ENEMY_ANIM_KIND[sm] or ''
    if #kinds ~= #offsets then kinds = '' end
    local fields = { o = {}, a = {}, h = {} }
    for n, o in ipairs(offsets) do
        local list = fields[kinds:sub(n, n)] or fields.o
        list[#list + 1] = { TYPES.physics, file.at + o }
    end
    local others = {}
    for _, page in ipairs(weapons) do
        if page ~= entry and page.enemy and page.enemy.members and sm_of(page) == sm then others[#others + 1] = page.name end
    end
    local shared = #others > 0 and '; shared with ' .. table.concat(others, ', ', 1, math.min(#others, 4)) .. (#others > 4 and ', ...' or '') or ''
    for _, s in ipairs({ { 'a', 'anim_attack', 'Attack animation speed (x)', 'their wind-ups and attacks' },
                         { 'h', 'anim_hit', 'Stagger recovery speed (x)', 'hit reactions, staggers and stuns' },
                         { 'o', 'anim_speed', 'Animation speed (x)', 'walking, turning, idling and the rest' } }) do
        if #fields[s[1]] > 0 then
            local r = MOD.enemy.mult_row(entry, 'Movement', s[2], s[3], fields[s[1]], 10, nil, s[4] .. shared,
                                         'anim:' .. sm .. (s[1] == 'o' and '' or ':' .. s[1]))
            r.tip = MOD.physics.ANIM_TIP
        end
    end
end
MOD.physics.ANIM_TIP = { 'How fast their animations play. Most attacks follow the animation, so they come sooner or later too.',
                         'Some actions keep their own timing and can fall out of step with the animation.' }

-- names: by the stratagem's debug name (as `pretty` gives it), or by the vehicle's entity (exosuits whose
-- debug names do not say which they are); MOUNTS: a mount's label by its name
KINDS[TYPES.vehicle].TITLES = {
    ['Bastion(tank)'] = 'TD-220 Bastion MK XVI', ['Storm(tank)'] = 'TD-110 Maelstrom',
    ['Fast Recon Vehicle (FRV)'] = 'M-102 Gunner FRV', ['Fast Recon Vehicle (Ramming Flamethrower)'] = 'M-104 Incinerator FRV',
    ['Fast Recon Vehicle (Resupply Auto Turret)'] = 'M-103 Supply FRV', ['Combat Walker Lumberer'] = 'EXO-51 Lumberer Exosuit',
    ['Combat Walker Breakthrough'] = 'EXO-55 Breakthrough Exosuit', ['Combat Walker Breacher'] = 'EXO-55 Breakthrough Exosuit', ['Combat Walker Emancipator'] = 'EXO-49 Emancipator Exosuit',
    ['Combat Walker Patriot'] = 'EXO-45 Patriot Exosuit' }
KINDS[TYPES.vehicle].ENTITIES = { ['79E4B3D2DA5E45E3'] = 'EXO-45 Patriot Exosuit', ['C2D449ECF7FACAB1'] = 'EXO-49 Emancipator Exosuit' }
-- vehicles no stratagem calls in (mission vehicles): { name, short name (its weapons'), its entities } (the GATER: two
-- identical ones)
KINDS[TYPES.vehicle].NATIVE = { { 'Ground All-Terrain Extraction Rig (GATER)', 'GATER', '0801B6B3C5D12EBC', '423FF97D57AB04F5' } }

-- The player's shields, by the entity listed (a stratagem's payload, a throwable): the energy shield
-- (ShieldComponentData: +0 radius, +76 capacity, +88 recharge delay, +92 recharge delay once broken,
-- +96 recharge rate, +100 charge it comes back with) and the bodies with health (health component:
-- health +0, armor +280, durable ratio +268 and each named zone's +204).
KINDS[TYPES.shield].OF = {
    ['12C8D71AC3897A5C'] = { shield = '12C8D71AC3897A5C' },                                         -- SH-32 Shield Generator Pack
    ['A4E796F84801B40A'] = { shield = 'B56FA3F5510000AB',                                           -- SH-51 Directional Shield
                             bodies = { { 'A4E796F84801B40A', 'Backpack' }, { 'B56FA3F5510000AB', 'Shield emitter' } } },
    ['967ED15E0BAE363B'] = { bodies = { { '967ED15E0BAE363B', 'Ballistic shield' } } },            -- SH-20 Ballistic Shield Backpack
    ['ED13DDC480EC6910'] = { shield = 'ED13DDC480EC6910', bodies = { { 'ED13DDC480EC6910', 'Generator' } } },   -- FX-12 Relay
    ['C91FB921947AD273'] = { shield = '1B9AC59697006337' },                                         -- G/SH-39 Shield
    ['1B9AC59697006337'] = { shield = '1B9AC59697006337' },
}
KINDS[TYPES.shield].rows = function(entry, hex)
    local of = KINDS[TYPES.shield].OF[hex]
    if not of then return false end
    local st, ht = tables[TYPES.shield], tables[TYPES.health]
    local at = of.shield and st and st.index[hash_key(of.shield)]
    if at then
        local function r(id, label, offset, max, small, big)
            add_row(entry, 'Shield', id, label, 'f32', { part(id, TYPES.shield, at + offset, 'f32', 1000000) }, 0, max, small, big)
        end
        r('shield_capacity', 'Shield capacity', 76, 1000000, 50, 250)
        if (read_field(field_at(TYPES.shield, at, 'f32', 1000)) or 0) > 0 then r('shield_radius', 'Radius (m)', 0, 200, 0.1, 1) end
        r('shield_delay', 'Recharge delay (s)', 88, 600, 1, 5)
        r('shield_broken', 'Recharge delay once broken (s)', 92, 600, 1, 5)
        r('shield_rate', 'Recharge rate (per s)', 96, 1000000, 10, 50)
        r('shield_restart', 'Charge when it comes back', 100, 1000000, 10, 50)
    end
    for k, b in ipairs(of.bodies or {}) do
        local hat = ht and ht.index[hash_key(b[1])]
        if hat then
            local p = 'body' .. k .. '_'
            add_row(entry, b[2], p .. 'health', 'Health', 'u32', { part(p .. 'health', TYPES.health, hat, 'u32', 10000000) }, 0, 1000000, 50, 250)
            add_row(entry, b[2], p .. 'armor', 'Armor', 'u32', { part(p .. 'armor', TYPES.health, hat + 280, 'u32', 100) }, 0, 10, 1, 1)
            if (read_field(field_at(TYPES.health, hat + 268, 'f32', 1)) or 0) > 0 then
                local parts = { part(p .. 'durable', TYPES.health, hat + 268, 'f32', 1) }
                for z = 0, 37 do
                    local base = hat + 520 + z * 552
                    if (peek4(ht.copies[1] + HEADER_BYTES + base + 96) or 0) ~= 0 then
                        parts[#parts + 1] = part(p .. 'durable_z' .. z, TYPES.health, base + 204, 'f32', 1)
                    end
                end
                add_row(entry, b[2], p .. 'durable', 'Durable ratio (0-1)', 'f32', parts, 0, 1, 0.05, 0.1)
            end
        end
    end
    return true
end

-- A backpack's rows, by the entity its hellpod carries (`key`, 8 bytes):
--   jump / hover pack: recharge +0 (RechargeComponentData); +156 > 0: hovers (6 s climb gate; -1 on jump
--     packs). Each pack gets only the fields its flight code reads (HD2Runtime 0.30.3 research): the Jump
--     Pack its launch force +0 (x (1 - t^2) over the launch duration +24), forward share of it +32, the
--     boost after it (duration +40; its force +36 is capped by the game at 2.5 x speed per second, so not
--     offered) and mid-air steering +60 (both packs); the Hover Pack (skips the launch) its hover speed +176,
--     horizontal acceleration +160 / +164 (blended over a zero-width speed range: always written together),
--     fuel rates +200 / +204, climb speed (+196 with +180), climb acceleration +168 and climb time limit +156
--   Warp Pack: explosion +56 (set off by an unsafe warp), warp distance +120, reach up +128 / down +132,
--     heat: safe below +140, unsafe above +144, per warp +148, cooling per second +152; injuries of an
--     unsafe warp: 12 of 24 bytes from +160 (+0 body part, +4 damage): head, 2 arms, 2 legs
--   charges: +0 capacity, +4 at the start (-1: full), +8 from resupply
-- backpack stratagems' names, by their debug names (as `pretty` gives them)
KINDS[TYPES.jumppack].TITLES = {
    ['Jumppack Backpack'] = 'LIFT-850 Jump Pack', ['Hoverpack Backpack'] = 'LIFT-860 Hover Pack',
    ['Displacement Backpack'] = 'LIFT-182 Warp Pack', ['Supply Backpack'] = 'B-1 Supply Pack',
    ['Hellbomb'] = 'B-100 Portable Hellbomb', ['Generator Pack'] = 'SH-32 Shield Generator Pack',
    ['Ballistic Shield Backpack'] = 'SH-20 Ballistic Shield Backpack', ['Directional Energy Shield'] = 'SH-51 Directional Shield',
    ['Guard Dog (Drone)'] = 'AX/AR-23 "Guard Dog"', ['Laser Rifle (Drone)'] = 'AX/LAS-5 "Guard Dog" Rover',
    ['Guard Dog Gas Projector (Drone)'] = 'AX/TX-13 "Guard Dog" Dog Breath',
    ['Guard Dog Flamethrower (Drone)'] = 'AX/FLAM-75 "Guard Dog" Hot Dog', ['Guard Dog (Drone) Stun'] = 'AX/ARC-3 "Guard Dog" K-9' }
KINDS[TYPES.jumppack].backpack = function(entry, key, ammo)
    if entry.backpack then return end
    entry.backpack = true
    local function at(kind)
        local t = tables[kind]
        return t and t.index[key]
    end
    local function r(section, id, label, kind, offset, storage, max, small, big, parts)
        return add_row(entry, section, id, label, storage, parts or { part(id, kind, offset, storage, 1000000) }, 0, max, small, big)
    end
    local jump, recharge = at(TYPES.jumppack), at(TYPES.recharge)
    if jump then
        local hover = (read_field(field_at(TYPES.jumppack, jump + 156, 'f32', 1000000)) or -1) > 0
        local section = hover and 'Hover pack' or 'Jump pack'
        if recharge then r(section, 'bp_recharge', 'Recharge time (s)', TYPES.recharge, recharge, 'f32', 600, 0.5, 2) end
        if not hover then
            r(section, 'bp_launch', 'Launch force', TYPES.jumppack, jump, 'f32', 1000, 1, 5)
            r(section, 'bp_takeoff', 'Launch duration (s)', TYPES.jumppack, jump + 24, 'f32', 5, 0.05, 0.25)
            r(section, 'bp_forward', 'Forward share of the launch (0-1)', TYPES.jumppack, jump + 32, 'f32', 1, 0.05, 0.1)
            r(section, 'bp_landing_time', 'Boost after the launch (s)', TYPES.jumppack, jump + 40, 'f32', 10, 0.05, 0.25)
        end
        r(section, 'bp_steer', 'Mid-air steering force', TYPES.jumppack, jump + 60, 'f32', 200, 0.5, 2)
        -- hover fuel is the recharge meter: each second hovering adds 1 + a fuel rate (+200 holding height,
        -- +204 at 8 m/s vertical speed) seconds to it, and the pack cuts out once it is full; times: the
        -- recharge time over 1 + that rate, kept when the recharge time changes (+156 only gates climbing)
        local tank = recharge and hover and field_at(TYPES.recharge, recharge, 'f32', 1000000)
        if tank then
            local keeps = {}
            local function fuel(id, label, offset)
                local p = part(id, TYPES.jumppack, jump + offset, 'f32', 1000000)
                p.field.signed = true
                local row = add_row(entry, section, id, label, 'f32', { p }, 0.1, 3600, 0.5, 2)
                row.span, row.span_default = function() return read_field(tank) end, function() return default_of(tank) end
                row.rate_plus = 1
                keeps[#keeps + 1] = row
            end
            fuel('bp_hover_fuel', 'Hover time, holding height (s)', 200)
            fuel('bp_climb_fuel', 'Hover time, full-speed climb (s)', 204)
            for _, row in ipairs(entry.rows) do
                if row.id == 'bp_recharge' then row.keeps = keeps end
            end
        end
        if hover then
            r(section, 'bp_hover_speed', 'Hover speed (m/s)', TYPES.jumppack, jump + 176, 'f32', 50, 0.5, 2)
            -- agility: how fast the hover speeds up toward the movement input; its two ends of a zero-width
            -- speed range must stay equal (one alone divides by zero), so the second follows the first
            local agility = add_row(entry, section, 'bp_agility', 'Hover agility (acceleration)', 'f32',
                { part('bp_agility', TYPES.jumppack, jump + 160, 'f32', 1000000),
                  part('bp_agility_high', TYPES.jumppack, jump + 164, 'f32', 1000000) }, 0.1, 200, 0.5, 2)
            agility.lead = true
            -- climbing: the speed nears the end of the vertical speed range +196 (the acceleration +168 fades to
            -- +172 = 0 there; the climb target +180 sits above it), so the row shows +196 and scales +180 with it
            local climb = add_row(entry, section, 'bp_climb_speed', 'Climb speed (m/s)', 'f32',
                { part('bp_climb_speed', TYPES.jumppack, jump + 196, 'f32', 1000000),
                  part('bp_climb_target', TYPES.jumppack, jump + 180, 'f32', 1000000) }, 0.5, 50, 0.5, 2)
            climb.lead = true
            r(section, 'bp_climb_accel', 'Climb acceleration', TYPES.jumppack, jump + 168, 'f32', 200, 0.5, 2)
            -- +156 > 0 marks a hover pack, so it stays above 0
            add_row(entry, section, 'bp_climb_time', 'Climb time limit (s)', 'f32',
                { part('bp_climb_time', TYPES.jumppack, jump + 156, 'f32', 1000000) }, 0.5, 600, 0.5, 2)
        end
    end
    local warp = at(TYPES.warp)
    if warp then
        local function w(id, label, offset, max, small, big)
            r('Warp pack', id, label, TYPES.warp, warp + offset, 'f32', max, small, big)
        end
        w('bp_warp_range', 'Warp distance (m)', 120, 1000, 0.5, 5)
        w('bp_warp_up', 'Reach upward (m)', 128, 100, 0.1, 1)
        w('bp_warp_down', 'Reach downward (m)', 132, 100, 0.1, 1)
        w('bp_warp_heat', 'Heat per warp (%)', 148, 100, 1, 5)
        w('bp_warp_cool', 'Cooling (% per s)', 152, 100, 0.5, 2)
        w('bp_warp_safe', 'Safe below heat (%)', 140, 100, 1, 5)
        w('bp_warp_unsafe', 'Injures you above heat (%)', 144, 100, 1, 5)
        local function hurt(id, label, list)
            local parts = {}
            for k, n in ipairs(list) do
                local o = warp + 160 + n * 24 + 4
                parts[k] = part(k == 1 and id or (id .. '_' .. k), TYPES.warp, o, 'f32', 1000000)
            end
            if read_field(parts[1].field) then
                r('Unsafe warp: damage to you', id, label, nil, nil, 'f32', 10000, 1, 5, parts)
            end
        end
        hurt('bp_warp_head', 'Head', { 0 })
        hurt('bp_warp_arms', 'Each arm', { 1, 2 })
        hurt('bp_warp_legs', 'Each leg', { 3, 4 })
        local id = read_field(field_at(TYPES.warp, warp + 56, 'u32', 100000))
        local xrow = id and id > 0 and tables[T_EXPLOSION] and tables[T_EXPLOSION].index[id]
        if xrow then
            local section = 'Unsafe warp: explosion'
            local qrow = read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
            qrow = qrow and qrow > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[qrow]
            if qrow then
                damage_rows(entry, section, 'bp_warp_x_', qrow)
                status_rows(entry, section, 'bp_warp_x_', qrow, 'blast')
            end
            for _, f in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                 { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                r(section, 'bp_warp_x_' .. f[1], f[2], T_EXPLOSION, xrow + f[3], 'f32', 200, 0.1, 1)
            end
            MOD.explosion_extras(entry, section, 'bp_warp_x_', xrow)
        end
    end
    local deposit = at(TYPES.deposit)
    if deposit and ammo then
        -- a support weapon's ammo backpack: the spare rockets / magazines it reloads from, or the rounds
        -- a belt-fed weapon fires from it
        -- the game sends a backpack's ammo count in 10 bits: rows stop at 1023, and going past it says why
        local cap = 'The game holds at most 1023 rounds in a backpack.'
        local first = add_row(entry, 'Backpack', 'bp_ammo', 'Ammo carried', 'u32',
                              { part('bp_ammo', TYPES.deposit, deposit, 'u32', 1000000) }, 0, 1023, 1, 10)
        first.note, first.limit = 'the spare ammo in its backpack; read when the backpack is called in', cap
        local start = read_field(field_at(TYPES.deposit, deposit + 4, 'u32', 0xFFFFFFFF))
        if start and start ~= 0xFFFFFFFF then r('Backpack', 'bp_ammo_start', 'Ammo at the start', TYPES.deposit, deposit + 4, 'u32', 1023, 1, 10).limit = cap end
        local refill = r('Backpack', 'bp_ammo_supply', 'Ammo from resupply', TYPES.deposit, deposit + 8, 'u32', 1023, 1, 10)
        refill.limit, refill.tip = cap, { 'A resupply box gives this much. An ammo box on the map gives half, rounded down.' }
    elseif deposit then
        r('Backpack', 'bp_charges', 'Charges', TYPES.deposit, deposit, 'u32', 999, 1, 5)
        local start = read_field(field_at(TYPES.deposit, deposit + 4, 'u32', 0xFFFFFFFF))
        if start and start < 1000 then r('Backpack', 'bp_charges_start', 'Starting charges', TYPES.deposit, deposit + 4, 'u32', 999, 1, 5) end
        r('Backpack', 'bp_charges_supply', 'Charges from resupply', TYPES.deposit, deposit + 8, 'u32', 999, 1, 5)
    end
end

-- A minefield stratagem's rows, by its pod (`key`): thrower (formation 1): +40 panels, +44 mines per panel,
-- +248 arming time, +260 / +264 throw velocity min / max, +280 spread (degrees); spawner: +8 / +12 field
-- width / depth, +16 / +20 mines wide / deep, +24 position scatter; minefield: +8 trigger delay, +12 chain
-- reaction delay, +24 explosion (its damage and radii). true when `key` is one.
KINDS[TYPES.minefield].rows = function(entry, key)
    local function at(kind) return tables[kind] and tables[kind].index[key] end
    local thrower, spawner, mine = at(TYPES.thrower), at(TYPES.mine_spawner), at(TYPES.minefield)
    if entry.mines or not (thrower or spawner or mine) then return entry.mines end
    entry.mines = true
    local function r(section, id, label, kind, offset, storage, min, max, small, big)
        add_row(entry, section, id, label, storage, { part(id, kind, offset, storage, 1000000) }, min, max, small, big)
    end
    if thrower then
        -- the pod throws each mine from a node of its model (panel_<p>_mine_<m>): more panels or mines than
        -- it has crashes the game, so these only go down from the game's values
        -- (`most` caps every write, saved values and presets included)
        for _, c in ipairs({ { 'mine_panels', 'Panels', 40 }, { 'mine_per_panel', 'Mines per panel', 44 } }) do
            local f = field_at(TYPES.thrower, thrower + c[3], 'u32', 1000000)
            f.most = default_of(f) or 0
            local row = add_row(entry, 'Minefield', c[1], c[2], 'u32', { { id = c[1], field = f } }, 0, f.most, 1, 1)
            if c[3] == 40 then row.note = 'panels, mines per panel: lower only (more than the default crashes the game)' end
        end
        r('Minefield', 'mine_arming', 'Arming time (s)', TYPES.thrower, thrower + 248, 'f32', 0, 60, 0.1, 1)
        r('Minefield', 'mine_throw_min', 'Throw velocity, min (m/s)', TYPES.thrower, thrower + 260, 'f32', 0, 200, 0.5, 2)
        r('Minefield', 'mine_throw_max', 'Throw velocity, max (m/s)', TYPES.thrower, thrower + 264, 'f32', 0, 200, 0.5, 2)
        r('Minefield', 'mine_spread', 'Throw spread (degrees)', TYPES.thrower, thrower + 280, 'f32', 0, 360, 1, 5)
    end
    if spawner then
        r('Minefield', 'mine_wide', 'Mines wide', TYPES.mine_spawner, spawner + 16, 'u32', 1, 48, 1, 1)
        r('Minefield', 'mine_deep', 'Mines deep', TYPES.mine_spawner, spawner + 20, 'u32', 1, 48, 1, 1)
        r('Minefield', 'mine_width', 'Field width (m)', TYPES.mine_spawner, spawner + 8, 'f32', 0, 500, 1, 5)
        r('Minefield', 'mine_depth', 'Field depth (m)', TYPES.mine_spawner, spawner + 12, 'f32', 0, 500, 1, 5)
        r('Minefield', 'mine_scatter', 'Position scatter (m)', TYPES.mine_spawner, spawner + 24, 'f32', 0, 100, 0.5, 2)
    end
    if mine then
        r('Mine', 'mine_trigger', 'Trigger delay (s)', TYPES.minefield, mine + 8, 'f32', 0, 60, 0.05, 0.5)
        r('Mine', 'mine_chain', 'Chain reaction delay (s)', TYPES.minefield, mine + 12, 'f32', 0, 60, 0.05, 0.5)
        local id = read_field(field_at(TYPES.minefield, mine + 24, 'u32', 100000))
        local xrow = id and id > 0 and tables[T_EXPLOSION] and tables[T_EXPLOSION].index[id]
        if xrow then
            local section = 'Mine explosion'
            local q = read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
            q = q and q > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[q]
            if q then
                damage_rows(entry, section, 'mine_x_', q)
                status_rows(entry, section, 'mine_x_', q, 'blast')
            end
            for _, f in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                 { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                r(section, 'mine_x_' .. f[1], f[2], T_EXPLOSION, xrow + f[3], 'f32', 0, 200, 0.1, 1)
            end
            MOD.explosion_extras(entry, section, 'mine_x_', xrow)
        end
    end
    -- the pod itself (enemies go for it like a sentry): health, durable ratio, demolition force, armor +280
    if thrower then
        KINDS[TYPES.destruction].body_rows(entry, key, 'Deployer', 'pod_')
        local body = tables[TYPES.health] and tables[TYPES.health].index[key]
        if body then r('Deployer', 'pod_armor', 'Armor', TYPES.health, body + 280, 'u32', 0, 10, 1, 1) end
    end
    return true
end

-- Extra stratagem (issue #64): StratagemInfo +200 additional_stratagem, a stratagem type (+0) given along when
-- this one is in your loadout (the Eagles' is Eagle Rearm, so they are offered as extras only). The choices:
-- every stratagem the game has (mission and President's reward ones too: the Dark Fluid and Medic backpacks
-- work, tested), by name; 0: none. A choice that leads back to the stratagem is refused.
MOD.extra = { FAMILIES = { support = true, backpack = true, sentry = true, emplacements = true, orbital = true,
                           vehicles = true, eagle = true } }
function MOD.extra.choices()
    if MOD.extra.list then return MOD.extra.list, MOD.extra.by_type end
    local list, by_type, names = {}, {}, {}
    for _, w in ipairs(weapons) do
        local def, family = w.stratagem and w.stratagem.def, w.stratagem and w.stratagem.family
        if not w.stratagem and w.sentry_defs and w.sentry_defs[1] then def, family = w.sentry_defs[1], 'sentry' end
        local t = def and peek4(def.at)
        if t and t > 0 and not by_type[t] then
            -- (a second stratagem with a name, e.g. the President's reward Health Pack Rack: its family after it)
            local name = names[w.name] and (w.name .. ' (' .. family:sub(1, 1):upper() .. family:sub(2) .. ')') or w.name
            names[w.name] = true
            w.extra_id = t         -- (shown after its name in the list, for typing a choice in)
            by_type[t] = { type = t, name = name, def = def, family = family }
            list[#list + 1] = by_type[t]
        end
    end
    table.sort(list, function(a, b) return a.name:lower() < b.name:lower() end)
    for n, c in ipairs(list) do c.n = n end
    MOD.extra.list, MOD.extra.by_type = list, by_type
    return list, by_type
end
-- the next / previous choice by name for `def` (n steps; 0 sits before the first), skipping what it can't have
-- (itself, a loop); nil: none that way
function MOD.extra.step(def, current, n)
    local list, by_type = MOD.extra.choices()
    local at = current ~= 0 and by_type[current] and by_type[current].n or 0
    local to = math.max(0, math.min(#list, at + n))
    local dir = n > 0 and 1 or -1
    while to > 0 and to <= #list and MOD.extra.refused(def, list[to].type) do to = to + dir end
    if to > #list then return nil end
    return to <= 0 and 0 or list[to].type
end
-- why `target` can't be `def`'s extra (itself, or a chain of extras back to it), or nil
function MOD.extra.refused(def, target)
    local _, by_type = MOD.extra.choices()
    if target == 0 then return nil end
    if not by_type[target] then return 'No stratagem ' .. tostring(target) .. ' to choose.' end
    local own = peek4(def.at)
    -- (itself included: the game follows extras with no end, and crashes as the mission starts; tested)
    local t = target
    for _ = 1, 64 do
        if t == own then return 'That would make a loop of extra stratagems.' end
        local c = by_type[t]
        t = c and peek4(c.def.at + 200) or 0
        if not t or t == 0 then return nil end
    end
    return 'That would make a loop of extra stratagems.'
end
function MOD.extra.row(entry, def)
    local row = add_row(entry, 'Extra stratagem', 'extra', 'Extra stratagem (choice)', 'u32',
                        { part('extra', def.kind, def.off + 200, 'u32', 100000) }, 0, 100000, 1, 10)
    row.choice = 'stratagem'
    row.def = def
    -- the row shows the chosen stratagem's name (its number, shown in the list, is the value, for typing)
    row.label_of = function()
        local t = read_field(row.parts[1].field) or 0
        local _, by_type = MOD.extra.choices()
        if t == 0 then return 'None' end
        return by_type[t] and by_type[t].name or ('Stratagem ' .. t)
    end
    row.note = 'also in your loadout when you bring this one'
    row.after = { '- / + steps through the stratagems by name (-- / ++: 10 at a time).',
                  "Or type the number shown after a stratagem's name in the list; 0 = none.",
                  "It doesn't take a loadout slot, but the HUD's stratagem list can fill up." }
    row.after_h = #row.after * 16 + 6
end

-- Call-in code: StratagemInfo +64 the code (the host resolves it to the array's address: a u32 per arrow, 1 up,
-- 2 right, 3 down, 4 left), +72 the arrow count. Offline only: the host writes the codes at Install (a longer
-- one is appended to its table, hostdata.lua M.codes). The row's value is the code as a number, an arrow per
-- base-5 digit (Up Right = 12 in base 5 = 7), so it is saved, preset and reset like any other value.
-- Recorded with the arrow keys or WASD, like the game's own entry.
MOD.code = { ARROWS = { '↑', '→', '↓', '←' }, MAX = 9 }
function MOD.code.native(def)
    local b = api.read(def.at + 64, 16)
    if not b then return nil end
    local at, count = u32(b, 0) + u32(b, 4) * 4294967296, u32(b, 8)
    if at < 65536 or count < 1 or count > MOD.code.MAX then return nil end
    local arrows = {}
    for k = 1, count do
        local a = peek4(at + (k - 1) * 4)
        if not a or a < 1 or a > 4 then return nil end
        arrows[k] = a
    end
    return arrows
end
function MOD.code.number(arrows)
    local v = 0
    for _, a in ipairs(arrows) do v = v * 5 + a end
    return v
end
function MOD.code.arrows(v)
    local out = {}
    v = math.floor((v or 0) + 0.5)
    while v > 0 do
        local a = v % 5
        if a == 0 then return nil end
        table.insert(out, 1, a)
        v = (v - a) / 5
    end
    return #out > 0 and #out <= MOD.code.MAX and out or nil
end
function MOD.code.text(v, arrows, gap)
    arrows = arrows or MOD.code.arrows(v)
    if not arrows then return '?' end
    local out = {}
    for k, a in ipairs(arrows) do out[k] = MOD.code.ARROWS[a] end
    return table.concat(out, gap or ' ')
end
function MOD.code.field(def) return fields[def.kind .. ':code' .. def.off] end
-- the stratagem's code as it stands (edited or the game's)
function MOD.code.current(def)
    local f = MOD.code.field(def)
    return f and MOD.code.arrows(read_field(f)) or MOD.code.native(def)
end
-- In every mission: a code that clashes with theirs is refused. Clashes with what a loadout can hold are
-- pointed out; the mission, tutorial and unused ones are not checked.
-- Always bring it: hung on the end of the chains of Reinforcement, SOS and Resupply (MOD.donors), which are in every
-- mission. Eagles are left out: their +200 is Eagle Rearm, which holds no page to walk past.
function MOD.extra.always_row(entry, def)
    local lead = { id = 'always', field = field_at(def.kind, 'always' .. def.off, 'virtual', 1) }
    lead.field.default, lead.field.always = 0, def
    def.page = entry.name
    add_row(entry, 'Extra stratagem', 'always', 'Always bring it', 'flag', { lead }, 0, 1, 1, 1).tip = {
        'In every mission, whatever your loadout. It takes no loadout slot. Applies on Install.',
        'At most 4 across all stratagems: more can crash the game at deployment.',
        'Projectile swap shares those 4, so weapons it loads leave fewer here.' }
end
function MOD.extra.always_undo(set)
    for _, l in ipairs(MOD.extra.links or {}) do set(l[1], l[2], 200, l[3]) end
    MOD.extra.links = {}
end
-- tails: the ends of the always-loaded chains; taken: how many of the 4 Projectile swap already holds
function MOD.extra.always_apply(tails, set, taken)
    local tail, list, seen, left = tails[#tails], {}, {}, {}
    if not tail then return left end
    for _, f in pairs(fields) do if f.always and read_field(f) == 1 then list[#list + 1] = f.always end end
    table.sort(list, function(a, b) return a.at < b.at end)
    local _, by_type = MOD.extra.choices()
    for k, def in ipairs(list) do
        local kind = peek4(def.at)
        if k > 4 - taken then
            log('always bring: no room for stratagem ' .. tostring(kind))
            left[#left + 1] = def.page
        elseif not seen[kind] then   -- (already reached through another one's Extra stratagem: a second link would loop)
            if k > 1 then
                MOD.extra.links[#MOD.extra.links + 1] = { tail[1], tail[2], read_field(field_at(tail[1], tail[2] + 200, 'u32', 4294967295)) }
            end
            set(tail[1], tail[2], 200, kind)
            local last = def
            while true do
                seen[peek4(last.at)] = true
                local after = by_type[peek4(last.at + 200)]
                if not after or seen[peek4(after.def.at)] then break end
                last = after.def
            end
            tail = { last.kind, last.off }
        end
    end
    return left
end

MOD.code.ALWAYS = { ['Reinforcement Beacon'] = true, ['Resupply'] = true, ['Sos Beacon'] = true }
MOD.code.LOADOUT = { orbital = true, eagle = true, support = true, backpack = true, sentry = true, emplacements = true,
                     vehicles = true }
-- arrows for def: nil, why (refused) or true, warning (a clash with a stratagem you may bring along)
function MOD.code.check(def, arrows)
    local list = MOD.extra.choices()
    local own = peek4(def.at)
    local function starts(a, b)   -- a begins with the whole of b
        if #b > #a then return false end
        for k = 1, #b do if a[k] ~= b[k] then return false end end
        return true
    end
    local same, under, over = {}, {}, {}
    for _, c in ipairs(list) do
        local other = c.type ~= own and (MOD.code.ALWAYS[c.name] or MOD.code.LOADOUT[c.family]) and MOD.code.current(c.def)
        if other then
            local hit = (#other == #arrows and starts(arrows, other) and same)
                        or (starts(other, arrows) and under)   -- theirs begins with this one
                        or (starts(arrows, other) and over)    -- this one begins with theirs
            if hit then
                if MOD.code.ALWAYS[c.name] then
                    local name = c.name == 'Reinforcement Beacon' and 'Reinforce' or c.name == 'Sos Beacon' and 'SOS Beacon' or c.name
                    if hit == same then return nil, 'Same code as ' .. name .. ', which is in every mission: not set.' end
                    if hit == under then return nil, name .. "'s code starts with that one, and it is in every mission: not set." end
                    return nil, 'That code starts with ' .. name .. "'s, which is in every mission: not set."
                end
                hit[#hit + 1] = c.name
            end
        end
    end
    local function names(t) return table.concat(t, ', ', 1, math.min(#t, 3)) .. (#t > 3 and ' and others' or '') end
    if #same > 0 then return true, 'Same code as ' .. names(same) .. ': bring only one of them.' end
    if #under > 0 then return true, names(under) .. " can't be called while this one is ready: their codes start with it." end
    if #over > 0 then return true, "This one can't be called while " .. names(over) .. ' is ready: its code starts with theirs.' end
    return true
end
function MOD.code.row(entry, def)
    if not MOD.offline then return end   -- (live, the HUD keeps the arrows it drew: offline only)
    local native = MOD.code.native(def)
    if not native then return end
    local f = field_at(def.kind, 'code' .. def.off, 'virtual', 1e7)
    f.default, f.def = MOD.code.number(native), def
    local row = add_row(entry, 'Stratagem', 'code', 'Call-in code', 'u32', { { id = 'code', field = f } }, 1, 1953124, 1, 1)
    row.code = true
    row.tip = { 'The arrows you enter to call it in: click Record (or press Enter on this row), then enter',
                'the new code with the arrow keys or WASD, 1 to 9 arrows. Enter keeps it, Backspace takes one back,',
                'Esc cancels. The HUD shows the new code too.' }
end

-- Call-in (issue #43), StratagemInfo +84 spawn_time: the beacon's countdown before the delivery is sent (every
-- stratagem; ship upgrades take some off). The hellpod's fall (4.75 s), a Pelican's flight and an Eagle's are the
-- game's own; +96 extra_travel_time and +100 (vehicles 10.5) change neither (tested in game). With every ship
-- upgrade: the 380mm's countdown edit applies, the EAT's and the MG sentry's are skipped (tested).
function MOD.callin_rows(entry, defs)
    local parts = {}
    for k, def in ipairs(defs) do parts[k] = part(k == 1 and 'callin' or 'callin' .. k, def.kind, def.off + 84, 'f32', 100000) end
    local row = add_row(entry, 'Stratagem', 'callin', 'Countdown before delivery (s)', 'f32', parts, 0, 60, 0.5, 5)
    row.show_first = true
    row.tip = { "The beacon's countdown before the delivery is sent.",
                "A hellpod lands this many seconds plus its 4.75 s fall after the beacon, so 0 is the fastest it gets.",
                'Ship upgrades that make support weapons and sentries launch at once skip it (tested).' }
end

local function resolve_stratagem(entry)
    local s = entry.stratagem
    local def = s.def
    if def then
        add_row(entry, 'Stratagem', 'cooldown', 'Cooldown (s)', 'f32',
                { part('cooldown', def.kind, def.off + 104, 'f32', 100000) }, 0, 10000, 1, 10)
        if read_field(field_at(def.kind, def.off + 80, 'u32', 999)) then
            add_row(entry, 'Stratagem', 'uses', s.family == 'eagle' and 'Uses per rearm' or 'Uses per mission', 'u32',
                    { part('uses', def.kind, def.off + 80, 'u32', 999) }, 0, 999, 1, 5)
        end
        MOD.code.row(entry, def)
        if s.family ~= 'eagle' then MOD.callin_rows(entry, { def }) end
        if s.family ~= 'eagle' and MOD.extra.FAMILIES[s.family] then
            MOD.extra.row(entry, def)
            MOD.extra.always_row(entry, def)
        end
    end
    if s.family == 'eagle' and s.rearm then
        add_row(entry, 'Stratagem', 'rearm', 'Eagle rearm time (s)', 'f32',
                { part('rearm', s.rearm.kind, s.rearm.off + 104, 'f32', 100000) }, 0, 10000, 1, 10)
    end
    for _, key in ipairs(s.payloads) do
        local bomb = tables[TYPES.bombard] and tables[TYPES.bombard].index[key]
        if bomb then
            local function b(id, label, offset, storage, min, max, small, big)
                add_row(entry, 'Barrage', id, label, storage, { part(id, TYPES.bombard, bomb + offset, storage, 100000) }, min, max, small, big)
            end
            b('barrage_salvos', 'Salvos', 24, 'u32', 1, 100, 1, 5)
            b('barrage_shells', 'Shells per salvo', 4, 'u32', 1, 500, 1, 5)
            b('barrage_shell_gap', 'Time between shells (s)', 8, 'f32', 0, 60, 0.05, 0.25)
            b('barrage_salvo_gap', 'Time between salvos (s)', 28, 'f32', 0, 120, 0.5, 2)
            b('barrage_area', 'Spread area (m)', 36, 'f32', 0, 500, 1, 5)
            if (read_field(field_at(TYPES.bombard, bomb + 96, 'f32', 100000)) or 0) > 0 then
                b('barrage_speed', 'Walking speed (m/s)', 96, 'f32', 0, 100, 0.5, 2)
            end
            -- (from Thodmcniujiao's fork) +0 delay, +12 random extra gap, +16 / +20 drift from the last shell, +44 height
            b('barrage_delay', 'Delay before the first shell (s)', 0, 'f32', 0, 60, 0.5, 2)
            b('barrage_shell_random', 'Random extra time between shells (s)', 12, 'f32', 0, 60, 0.05, 0.25)
            b('barrage_drift_min', 'Drift from the last shell, least (m)', 16, 'f32', 0, 500, 1, 5)
            b('barrage_drift_max', 'Drift from the last shell, most (m)', 20, 'f32', 0, 500, 1, 5)
            b('barrage_height', 'Height the shells fall from (m)', 44, 'f32', 0, 10000, 50, 250)
            if (read_field(field_at(TYPES.bombard, bomb + 96, 'f32', 100000)) or 0) > 0 then
                b('barrage_walk_angle', 'Walking direction (deg)', 132, 'f32', -360, 360, 5, 45)
                b('barrage_walk_start', 'Path start (0 to 1)', 136, 'f32', 0, 1, 0.05, 0.25)
                entry.by_id.barrage_walk_start.row.note = '0: walks away from the beacon, 0.5: centred on it, 1: ends on it'
            end
            -- (from Thodmcniujiao's fork) +64 eight shell slots, fired in turn (0: none); a row per projectile the
            -- game puts there (the 120mm: its first shell, then the rest)
            local groups = {}
            for n = 0, 7 do
                local f = field_at(TYPES.bombard, bomb + 64 + 4 * n, 'u32', 100000)
                local id = default_of(f) or 0
                if id > 0 then
                    local g = groups[#groups]
                    if not (g and g.id == id) then g = { id = id, slots = {} }; groups[#groups + 1] = g end
                    g.slots[#g.slots + 1] = n
                end
            end
            for k, g in ipairs(groups) do
                local id = 'barrage_shell' .. (k > 1 and k or '')
                local parts = {}
                for m, n in ipairs(g.slots) do parts[m] = part(id .. (m > 1 and ('_' .. m) or ''), TYPES.bombard, bomb + 64 + 4 * n, 'u32', 100000) end
                local label = #groups == 1 and 'Shell fired (id)' or k == 1 and 'First shell (id)' or 'Shells after it (id)'
                local r = add_row(entry, 'Barrage', id, label, 'u32', parts, 0, 100000, 1, 10)
                r.choice = 'shrapnel'
                r.note = function()
                    local now = read_field(parts[1].field)
                    return (now or 0) > 0 and ('fires ' .. MOD.records.label(T_PROJECTILE, now)) or 'none'
                end
            end
            break
        end
        local eagle = tables[TYPES.eagle] and tables[TYPES.eagle].index[key]
        if eagle then
            local moved = KINDS[TYPES.eagle].offsets or {}
            local function e(id, label, offset, min, max, small, big, also)
                local parts = { part(id, TYPES.eagle, eagle + (moved[offset] or offset), 'f32', 100000) }
                if also then parts[2] = part(id .. '_2', TYPES.eagle, eagle + (moved[also] or also), 'f32', 100000) end
                return add_row(entry, 'Eagle', id, label, 'f32', parts, min, max, small, big)
            end
            local approach = e('eagle_approach', 'Approach distance (m)', 52, 0, 10000, 10, 100, 56)
            approach.tip = { 'How far away the jet starts its run. With its speed, it sets how long the Eagle takes to arrive.',
                             "The beacon's timer still counts down the usual time (tested)." }
            e('eagle_speed', 'Speed until it has fired (m/s)', 76, 0, 5000, 10, 50)
            local payload = read_field(field_at(TYPES.eagle, eagle + 16, 'u32', 100))
            if payload == 5 then
                e('eagle_bomb_gap', 'Time between bombs (s)', 44, 0, 10, 0.05, 0.25)
                -- +20 the drop pattern (EagleAirstrikePattern), which fixes the bomb count (SHODAN Offline Integration)
                local p = part('eagle_pattern', TYPES.eagle, eagle + 20, 'u32', 7)
                if default_of(p.field) then
                    local r = add_row(entry, 'Eagle', 'eagle_pattern', 'Bomb pattern', 'u32', { p }, 0, 7, 1, 1)
                    r.label_of = function()
                        local n = read_field(p.field) or 0
                        return 'Bomb pattern ' .. n .. ': ' .. KINDS[TYPES.eagle].BOMBS[n] .. ' bombs'
                    end
                    r.tip = { 'How many bombs one run drops and how they land. The bombs stay this Eagle\'s own.' }
                end
            else e('eagle_fire_time', 'Fire duration (s)', 40, 0, 30, 0.1, 0.5) end
            if (read_field(field_at(TYPES.eagle, eagle + (moved[108] or 108), 'f32', 100000)) or 0) > 0 then
                e('eagle_run_length', 'Run length (m)', 108, 0, 500, 1, 5)
            end
            -- (from Thodmcniujiao's fork) +24 the projectile its bombs or rockets are (the guns' none)
            local shot = part('eagle_projectile', TYPES.eagle, eagle + 24, 'u32', 100000)
            if (default_of(shot.field) or 0) > 0 then
                local r = add_row(entry, 'Eagle', 'eagle_projectile', payload == 4 and 'Rocket fired (id)' or 'Bomb dropped (id)', 'u32',
                                  { shot }, 0, 100000, 1, 10)
                r.choice = 'shrapnel'
                r.note = function()
                    local now = read_field(shot.field)
                    return (now or 0) > 0 and ((payload == 4 and 'fires ' or 'drops ') .. MOD.records.label(T_PROJECTILE, now)) or 'none'
                end
            end
            break
        end
    end
    for _, key in ipairs(s.payloads) do
        local beam = tables[T_ORBITAL] and tables[T_ORBITAL].index[key]
        if beam then
            local function b(id, label, offset, min, max, small, big)
                add_row(entry, 'Orbital beam', id, label, 'f32', { part(id, T_ORBITAL, beam + offset, 'f32', 100000) }, min, max, small, big)
            end
            b('beam_duration', 'Duration (s)', 460, 0, 600, 1, 5)
            b('beam_speed', 'Tracking speed', 468, 0, 200, 1, 5)
            b('beam_radius', 'Search radius (m)', 472, 0, 500, 1, 10)
            b('beam_tick', 'Damage tick (s)', 480, 0.01, 10, 0.01, 0.05)
            -- (from Thodmcniujiao's fork) +488 / +492 / +496 the damage area's size (the laser's: 1 m each way); +540
            -- the delay before a fired projectile (+532: the Railcannon's shot)
            if (read_field(field_at(T_ORBITAL, beam + 488, 'f32', 100000)) or 0) > 0 then
                local area = add_row(entry, 'Orbital beam', 'beam_area', 'Damage area size (m)', 'f32',
                                     { part('beam_area', T_ORBITAL, beam + 488, 'f32', 100000), part('beam_area_2', T_ORBITAL, beam + 492, 'f32', 100000),
                                       part('beam_area_3', T_ORBITAL, beam + 496, 'f32', 100000) }, 0, 100, 0.5, 2)
                area.lead = true
            end
            if (read_field(field_at(T_ORBITAL, beam + 532, 'u32', 100000)) or 0) > 0 then
                b('beam_shot_delay', 'Delay before the shot (s)', 540, 0, 60, 0.1, 0.5)
            end
            break
        end
    end
    for _, node in ipairs(s.nodes) do
        local kind, record, section = node[1], node[2], node[3]
        if kind == 'P' then
            local row = tables[T_PROJECTILE] and tables[T_PROJECTILE].index[record]
            if row then
                local id = 'p' .. record .. '_velocity'
                add_row(entry, section, id, 'Velocity (m/s)', 'f32', { part(id, T_PROJECTILE, row + 32, 'f32', 100000) }, 0, 100000, 10, 100)
                id = 'p' .. record .. '_gravity'
                add_row(entry, section, id, 'Gravity factor', 'f32', { part(id, T_PROJECTILE, row + 44, 'f32', 100000) }, 0, 100, 0.05, 0.5)
            end
        elseif kind == 'X' then
            local row = tables[T_EXPLOSION] and tables[T_EXPLOSION].index[record]
            if row then
                for _, f in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                     { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                    local id = 'x' .. record .. '_' .. f[1]
                    add_row(entry, section, id, f[2], 'f32', { part(id, T_EXPLOSION, row + f[3], 'f32', 10000) }, 0, 500, 0.5, 2)
                end
                MOD.explosion_extras(entry, section, 'x' .. record .. '_', row)
            end
        elseif kind == 'D' then
            local row = tables[T_DAMAGE] and tables[T_DAMAGE].index[record]
            if row then
                damage_rows(entry, section, 'd' .. record .. '_', row, nil, 9, true)
            end
        end
    end
    if s.vehicle then KINDS[TYPES.vehicle].rows(entry, s.vehicle, s.twins); return end
    -- a backpack (in its hellpod rack's first slot): its own rows; a shield (the Shield Generator Relay, a
    -- shield backpack)
    local rt = tables[TYPES.rack]
    -- how many of the rack's filled slots the pod drops (+556 spawn_payload_size; issue #104): the EAT-17's 2 of
    -- 2, the Commando's and MG-43's 1 of 2 (one per side)
    for _, key in ipairs(s.payloads) do
        local rack = rt and rt.index[key]
        local slots = rack and api.read(rt.copies[1] + HEADER_BYTES + rack, 512)
        local filled = 0
        for k = 0, slots and #slots == 512 and 7 or -1 do   -- (the game's slots: a copy this mod put in does not count)
            if (default_of(field_at(TYPES.rack, rack + k * 64, 'u32', 4294967295)) or 0) ~= 0
               or (default_of(field_at(TYPES.rack, rack + k * 64 + 4, 'u32', 4294967295)) or 0) ~= 0 then filled = filled + 1 end
        end
        if filled >= 2 and not entry.by_id.pod_items then
            add_row(entry, 'Hellpod', 'pod_items', 'Items per drop', 'u32', { part('pod_items', TYPES.rack, rack + 556, 'u32', 8) },
                    1, filled, 1, 1).note = 'how many of the items on its rack come down in one pod'
        elseif filled == 1 and u32(slots, 8) == MOD.pod.LEFT and not entry.by_id.pod_twin then
            MOD.pod.twin_row(entry, rack)
        end
    end
    for _, key in ipairs(s.payloads) do
        local rack = rt and rt.index[key]
        local carried = rack and api.read(rt.copies[1] + HEADER_BYTES + rack, 8)
        if carried and #carried == 8 then KINDS[TYPES.jumppack].backpack(entry, carried) end
        -- a minefield: the pod, or what the stratagem's hellpod carries
        for _, k in ipairs({ key, carried }) do KINDS[TYPES.minefield].rows(entry, k) end
        for _, k in ipairs({ key, carried }) do
            if KINDS[TYPES.shield].rows(entry, string.format('%08X%08X', u32(k, 4), u32(k, 0))) then
                -- how long it stays once deployed, as the sentries' (the Relay: issue #109)
                local pt = tables[TYPES.payload]
                local pat = pt and pt.index[k]
                local life = pat and default_of(field_at(TYPES.payload, pat + 4, 'f32', 100000))
                if life and life > 0 and life <= 7200 then
                    local of = KINDS[TYPES.shield].OF[string.format('%08X%08X', u32(k, 4), u32(k, 0))]
                    add_row(entry, of.bodies and of.bodies[1][2] or 'Shield', 'unit_lifetime', 'Time deployed (s)', 'f32',
                            { part('unit_lifetime', TYPES.payload, pat + 4, 'f32', 100000) }, 1, 7200, 5, 30)
                end
                return
            end
        end
    end
    -- a Guard Dog: its drone (health +0, spotting range +0, target search interval +0 / +4), then
    -- the gun it carries
    if s.drone then
        unit_rows(entry, s.drone.drone, 'Drone', 'drone_')
        if s.drone.gun then resolve_gun(entry, s.drone.gun) end
        return
    end
    -- the first payload that is a gun of its own (not a weapon listed elsewhere; strikes have
    -- their records above)
    for _, key in ipairs(s.payloads) do
        if not s.guns[key] and #s.nodes == 0 then
            local before = #entry.rows
            resolve_gun(entry, key)
            if #entry.rows > before then break end
        end
    end
end

-- Throwables: throwable component (+100 starting, +104 max, +108 from supply, +16 max throw
-- distance), explosive component (+0 mode: 0 timed, 3 timed then burning; +12 fuse; +36 explosion),
-- sticky component (+44 damage row: the throwing knife's hit). The explosion: its damage set,
-- statuses and radii, its arc (+120: G-31), its shrapnel (+80 count, +84 projectile) and the
-- shrapnel's own explosion (projectile +144: the Pineapple's bomblets). `placed`: a support weapon's
-- charge (the C4 Pack's), whose counts are its backpack's: only the throw distance, under 'Charge'.
local function resolve_throwable(entry, placed)
    local function record(kind)
        local t = tables[kind]
        return t and t.index[entry.key]
    end
    local function damage(id)
        return id and id > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[id]
    end
    local th = record(TYPES.throwable)
    if th then
        for _, r in ipairs(placed and {} or { { 'throw_start', 'Starting count', 100 }, { 'throw_max', 'Max carried', 104 },
                                              { 'throw_supply', 'From supply', 108 } }) do
            add_row(entry, 'Throwable', r[1], r[2], 'u32', { part(r[1], TYPES.throwable, th + r[3], 'u32', 10000) }, 0, 999, 1, 5)
        end
        add_row(entry, placed and 'Charge' or 'Throwable', 'throw_distance', 'Max throw distance (m)', 'f32',
                { part('throw_distance', TYPES.throwable, th + 16, 'f32', 100000) }, 0, 200, 0.5, 5)
    end
    KINDS[TYPES.shield].rows(entry, entry.hash)   -- the G/SH-39's shield
    local sticky = record(TYPES.sticky)
    local hit = sticky and damage(read_field(field_at(TYPES.sticky, sticky + 44, 'u32', 100000)))
    if hit then
        damage_rows(entry, 'Damage', '', hit)
        status_rows(entry, 'Damage', '', hit, 'hit')
    end
    -- the G-142 Pyrotech's sparks: a spray (SprayWeaponComponentData +200 damage row; their count, range and spray
    -- time are not in it, all 0)
    local spray = record(T_SPRAY)
    local sparks = spray and damage(read_field(field_at(T_SPRAY, spray + 200, 'u32', 100000)))
    if sparks then
        damage_rows(entry, 'Sparks', 'spark_', sparks, 'Spark')
        status_rows(entry, 'Sparks', 'spark_', sparks, 'hit')
    end
    local ex = record(TYPES.explosive)
    if not ex then return end
    local function explosion(id, prefix, section, deep)
        local xrow = id and id > 0 and tables[T_EXPLOSION] and tables[T_EXPLOSION].index[id]
        if not xrow then return false end
        local qrow = damage(read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000)))
        if qrow then
            damage_rows(entry, section, prefix, qrow, section == 'Explosion' and 'Explosion' or nil)
            status_rows(entry, section, prefix, qrow, 'blast')
        end
        for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                             { 'shockwave', 'Shockwave radius (m)', 24 } }) do
            add_row(entry, section, prefix .. r[1], r[2], 'f32', { part(prefix .. r[1], T_EXPLOSION, xrow + r[3], 'f32', 100000) }, 0, 200, 0.1, 1)
        end
        MOD.explosion_extras(entry, section, prefix, xrow)
        if not deep then return true end
        local arc = tables[TYPES.arc] and tables[TYPES.arc].index[read_field(field_at(T_EXPLOSION, xrow + 120, 'u32', 100000)) or -1]
        if arc then
            add_row(entry, 'Arc', 'arc_range', 'Range (m)', 'f32', { part('arc_range', TYPES.arc, arc + 8, 'f32', 100000) }, 0, 1000, 1, 5)
            add_row(entry, 'Arc', 'arc_chain', 'Chain length', 'u32', { MOD.solo(part('arc_chain', TYPES.arc, arc + 28, 'u32', 1000)) }, 0, 20, 1, 1)
            add_row(entry, 'Arc', 'arc_split', 'Chain split', 'u32', { MOD.solo(part('arc_split', TYPES.arc, arc + 32, 'u32', 1000)) }, 0, 20, 1, 1)
            local q = damage(read_field(field_at(TYPES.arc, arc + 36, 'u32', 100000)))
            if q then damage_rows(entry, 'Arc', 'arc_', q, 'Arc') end
        end
        local count = read_field(field_at(T_EXPLOSION, xrow + 80, 'u32', 100000))
        local pid = count and count > 0 and read_field(field_at(T_EXPLOSION, xrow + 84, 'u32', 100000))
        local prow = pid and pid > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[pid]
        if prow then
            add_row(entry, 'Shrapnel', 'shrapnel_count', 'Shrapnel pieces', 'u32',
                    { part('shrapnel_count', T_EXPLOSION, xrow + 80, 'u32', 10000) }, 0, 500, 1, 5)
            local q = damage(read_field(field_at(T_PROJECTILE, prow + 60, 'u32', 100000)))
            if q then damage_rows(entry, 'Shrapnel', 'shrapnel_', q, 'Shrapnel') end
            add_row(entry, 'Shrapnel', 'shrapnel_velocity', 'Velocity (m/s)', 'f32',
                    { part('shrapnel_velocity', T_PROJECTILE, prow + 32, 'f32', 100000) }, 0, 100000, 10, 100)
            add_row(entry, 'Shrapnel', 'shrapnel_gravity', 'Gravity factor', 'f32',
                    { part('shrapnel_gravity', T_PROJECTILE, prow + 44, 'f32', 100000) }, 0, 100, 0.05, 0.5)
            explosion(read_field(field_at(T_PROJECTILE, prow + 144, 'u32', 100000)), 'bomblet_', 'Shrapnel explosion', false)
        end
        return true
    end
    local id = read_field(field_at(TYPES.explosive, ex + 36, 'u32', 100000))
    local mode = read_field(field_at(TYPES.explosive, ex, 'u32', 100000))
    local fuse = read_field(field_at(TYPES.explosive, ex + 12, 'f32', 100000))
    local has = id and id > 0 and tables[T_EXPLOSION] and tables[T_EXPLOSION].index[id]
    -- (on an impact throwable, mode 2, +12 is the earliest it goes off: the Urchin, the G-31 Arc)
    -- (not the Urchin's: its own timer, not in the files, sets when it goes off; issue #97, tested)
    if has and (mode == 0 or mode == 2 or mode == 3) and fuse and fuse > 0 and entry.hash ~= '3FA94F58F596BC0B' then
        local row = add_row(entry, 'Throwable', 'fuse', 'Fuse time (s)', 'f32', { part('fuse', TYPES.explosive, ex + 12, 'f32', 100000) }, 0, 60, 0.1, 1)
        if mode == 2 then row.note = 'goes off on impact, but not before this' end
    end
    -- a burning throwable (the Thermite): once the fuse is out, a timed status effect (+252: its effects
    -- from +256, lifetime +292) burns, then it explodes; it is removed +16 after going off (the burn +
    -- 0.25 s), so that follows the burn time
    if has and mode == 3 and (read_field(field_at(TYPES.explosive, ex + 256, 'u32', 100000)) or 0) > 0 then
        local burn = add_row(entry, 'Throwable', 'burn', 'Burn time (s)', 'f32',
                             { part('burn', TYPES.explosive, ex + 292, 'f32', 100000),
                               part('burn_removal', TYPES.explosive, ex + 16, 'f32', 100000) }, 0.1, 120, 0.5, 2)
        burn.lead = true
    end
    explosion(id, 'blast_', 'Explosion', true)
end

-- A missile's flight rows (`seek`: its SeekingMissile record), ids 'missile_' .. stat; `steered` false:
-- without the steering rows (turn speeds, target lost angle, guidance delay).
KINDS[TYPES.seeking].flight = function(weapon, seek, steered)
    for _, r in ipairs({
        { 'launch_speed', 'Launch speed (m/s)', 68, 2000, 5, 25 },
        { 'cruise_speed', 'Cruise speed (m/s)', 76, 2000, 5, 25 },
        { 'min_speed', 'Minimum speed (m/s)', 72, 2000, 5, 25 },
        { 'acceleration', 'Acceleration (m/s2)', 80, 10000, 10, 50 },
        { 'turn_cruise', 'Turn speed at cruise', 88, 100, 0.1, 1, true },
        { 'turn_slow', 'Turn speed at slowest', 92, 100, 0.1, 1, true },
        { 'lost_angle', 'Loses its target past (deg)', 28, 180, 1, 10, true },
        { 'lifetime', 'Max flight time (s)', 64, 600, 1, 5 },
        { 'guidance_after', 'Guidance on after (s)', 12, 60, 0.1, 0.5, true },
    }) do
        local id = 'missile_' .. r[1]
        if steered ~= false or not r[7] then
            add_row(weapon, 'Missile flight', id, r[2], 'f32', { part(id, TYPES.seeking, seek + r[3], 'f32', 1000000) }, 0, r[4], r[5], r[6])
        end
    end
    -- a missile that weaves (+180 on: the W.A.S.P., P-33): how far, +192 / +196 and the vectors +200 / +212
    -- (55, (20, 40, 20) / (30, 50, 30) for the W.A.S.P.), scaled together; off: it flies its line. Not
    -- +184 / +188 (-75 / 75 for the W.A.S.P.): no visible change in game (the Warrant has them all 0)
    -- (the game's values: the rows stay when switched off)
    if default_of(field_at(TYPES.seeking, seek + 180, 'flag', 1)) == 1
       and (default_of(field_at(TYPES.seeking, seek + 196, 'f32', 1000000)) or 0) > 0 then
        add_row(weapon, 'Missile flight', 'missile_weave', 'Weaves', 'flag',
                { part('missile_weave', TYPES.seeking, seek + 180, 'flag', 1) }, 0, 1, 1, 1)
        local parts = { part('missile_deviation', TYPES.seeking, seek + 196, 'f32', 1000000) }
        for k, off in ipairs({ 192, 200, 204, 208, 212, 216, 220 }) do
            parts[#parts + 1] = part('missile_deviation_' .. k, TYPES.seeking, seek + off, 'f32', 1000000)
        end
        local row = add_row(weapon, 'Missile flight', 'missile_deviation', 'Deviation', 'f32', parts, 0.1, 1000, 1, 5)
        row.lead = true   -- the others scale with it
    end
end

-- A weapon that fires a missile: its fire mode's projectile entity (+40: spawned instead of a projectile;
-- the Patriot's rockets, Spear, Commando, W.A.S.P., Warrant...) with a SeekingMissile record: that record,
-- whose speeds it flies at (the projectile's velocity, drag and gravity are not used).
KINDS[TYPES.seeking].fired = function(fire)
    local ft, st = tables[T_FIRE], tables[TYPES.seeking]
    local entity = ft and st and api.read(ft.copies[1] + HEADER_BYTES + fire + 40, 8)
    return entity and #entity == 8 and st.index[entity] or nil
end

-- Whether a weapon steers its missile: a lock-on missile does; one that follows the aim (+0: 1) only
-- with the weapon's laser designator (the Commando's; the Patriot's rockets fly straight).
KINDS[TYPES.seeking].steered = function(weapon)
    local st, lt = tables[TYPES.seeking], tables[TYPES.laser]
    local mode = api.read(st.copies[1] + HEADER_BYTES + weapon.missile, 4)
    return mode ~= string.char(1, 0, 0, 0) or not lt or lt.index[weapon.key] ~= nil
end

-- The MS-11 Solo Silo (its entry is the missile, an explosive you place): the silo that holds it (the
-- hellpod rack carrying the missile's entity), its health (+0), armor (+280), regeneration per second (+4)
-- (its rack spawns 2 payloads, rack +556: not offered as a missile count), then the
-- missile's health and flight (SeekingMissileComponentData). Its ids stay 'charge_' for the missile's
-- health (saved before it had its own section). False: not a seeking missile.
KINDS[TYPES.seeking].silo_rows = function(weapon)
    local st = tables[TYPES.seeking]
    local seek = st and st.index[weapon.key]
    local rt, silo, rack = tables[TYPES.rack], nil, nil
    for holder, at in pairs(rt and rt.index or {}) do
        local slots = api.read(rt.copies[1] + HEADER_BYTES + at, 512)
        for k = 0, slots and #slots == 512 and 7 or -1 do
            if slots:sub(k * 64 + 1, k * 64 + 8) == weapon.key then silo, rack = holder, at end
        end
    end
    local ht = tables[TYPES.health]
    local body = silo and ht and ht.index[silo]
    if not (seek or body) then return false end
    if body then
        add_row(weapon, 'Silo', 'silo_health', 'Health', 'u32', { part('silo_health', TYPES.health, body, 'u32', 10000000) },
                0, 1000000, 50, 500)
        add_row(weapon, 'Silo', 'silo_armor', 'Armor', 'u32', { part('silo_armor', TYPES.health, body + 280, 'u32', 100) }, 0, 10, 1, 1)
        add_row(weapon, 'Silo', 'silo_regen', 'Regeneration (health/s)', 'f32',
                { part('silo_regen', TYPES.health, body + 4, 'f32', 1000000) }, 0, 10000, 1, 10)
    end
    unit_rows(weapon, weapon.key, 'Missile', 'charge_')
    if seek then KINDS[TYPES.seeking].flight(weapon, seek) end
    return true
end

-- Boosters (the Boosters tab): the ones whose values are in the data files. The rest keep theirs in a
-- table in game.dll (HD2Runtime's booster research, docs/booster-authoring.md), out of reach offline.
-- Each finds its rows the way the game picks them: a status effect by its debug name (+8), an explosion
-- among candidate ids by what it looks like (smoke: no damage and no shockwave; it moved 400 -> 401 in
-- 25988413), the Armed Resupply Pods' turret by its entity, Surplus EAT's one-shot EAT by its stratagem id.
-- { enum value (the entry's hash), name, note, kind, what }
MOD.boosters = { LIST = {
    { 11, 'Experimental Infusion', 'Stims give this effect instead of the normal one.', 'status', 'Stim Combat Drugs' },
    { 12, 'Firebomb Hellpods', 'Every hellpod sets this off where it lands.', 'blast', { 83 }, 5 },
    { 14, 'Dead Sprint', 'Sprinting out of stamina costs health instead.', 'drain', 'Death March' },
    { 15, 'Armed Resupply Pods', 'The machine gun turret on each resupply pod.', 'turret', '73681FFD58FA1A90' },
    { 17, 'Stun Pods', 'Every hellpod sets this off where it lands.', 'blast', { 335 }, 41 },
    { 18, 'Concealed Insertion', 'Every hellpod leaves this smoke where it lands.', 'smoke', { 401, 400 } },
    { 20, 'Surplus EAT Allocation', 'The free one-shot EAT it adds to your stratagems.', 'eat', 0xDFB589B2 } } }

-- booster id -> name, in capitals, description (text ids)
MOD.boosters.TEXTS = { [11] = { 0x89F6921F, 0x00B22672 }, [12] = { 0x9097BB88, 0xA88337E6, 0x7A343F36 },
    [14] = { 0x174DF35E, 0x8D0053F8, 0x5B24729F }, [15] = { 0x4014FD10, 0xE9B5BACA, 0x0BB15A34 },
    [17] = { 0xC6B5F30A, 0xB3AFCC76 }, [18] = { 0x6E417BA8, 0x8F22DA6C, 0x672FC2C4 }, [20] = { 0x1CF90DEA, 0x4F268774 } }

MOD.boosters.WHY = "Booster selection is limited due to the other boosters keeping their values in the game's program " ..
                   '(game.dll), not in the data files SSEO edits. Those could only be changed while the game runs, which ' ..
                   'is currently impossible.'

-- A pointer in a status row: an address in game, a payload offset offline (the host leaves this table's as they are).
function MOD.boosters.at(t, lo, hi)
    local v = lo and hi and lo + hi * 4294967296
    if not v or v == 0 then return nil end
    return v < t.payload and t.copies[1] + HEADER_BYTES + v or v
end

-- A status effect's row by its debug name, or nil.
function MOD.boosters.status(name)
    local t = tables[T_STATUS]
    if not t then return nil end
    for id, off in pairs(t.index) do
        local top = t.copies[1] + HEADER_BYTES
        if type(id) == 'number' and read_text(MOD.boosters.at(t, peek4(top + off + 8), peek4(top + off + 12))) == name then return off end
    end
end

-- The first candidate explosion that fits: `status` (its damage row's first status), or none for smoke.
function MOD.boosters.blast(ids, status)
    local t = tables[T_EXPLOSION]
    for _, id in ipairs(ids) do
        local xrow = t and t.index[id]
        local did = xrow and default_of(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
        local qrow = did and did > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
        if status and qrow and default_of(field_at(T_DAMAGE, qrow + 44, 'u32', 100000)) == status then return xrow, qrow end
        if not status and xrow and did == 0 and default_of(field_at(T_EXPLOSION, xrow + 24, 'f32', 100000)) == 0 then return xrow end
    end
end

-- The list: the boosters this game build has, after the stratagems.
function MOD.boosters.build()
    for k = #weapons, 1, -1 do
        if weapons[k].booster then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    local list = {}
    for _, b in ipairs(MOD.boosters.LIST) do
        local hash = string.format('FFFFFFFD%08X', b[1])
        list[#list + 1] = { name = b[2], slot = 'Boosters', hash = hash, rows = {}, by_id = {}, booster = b,
                            note = 'Booster. ' .. b[3] }
        by_hash[hash] = list[#list]
    end
    table.sort(list, function(a, b) return a.name:lower() < b.name:lower() end)
    for _, entry in ipairs(list) do weapons[#weapons + 1] = entry end
end

function MOD.boosters.resolve(entry)
    local b = entry.booster
    local kind = b[4]
    if kind == 'status' then
        local srow = MOD.boosters.status(b[5])
        if not srow then return end
        add_row(entry, 'Effect', 'duration', 'Duration (s)', 'f32', { part('duration', T_STATUS, srow + 40, 'f32', 100000) }, 0, 600, 0.5, 5)
        add_row(entry, 'Effect', 'speed', 'Movement speed (multiplier)', 'f32',
                { part('speed', T_STATUS, srow + 36, 'f32', 100) }, 0, 10, 0.05, 0.25)
        -- its stat modifiers (+112 list, +120 count; 8 bytes each: stat, value): stat 2 = damage taken
        local t = tables[T_STATUS]
        local top = t.copies[1] + HEADER_BYTES
        local list, n = MOD.boosters.at(t, peek4(top + srow + 112), peek4(top + srow + 116)), peek4(top + srow + 120)
        local at = list and n and n > 0 and n <= 8 and list - top
        for k = 0, at and n - 1 or -1 do
            if peek4(top + at + k * 8) == 2 then
                add_row(entry, 'Effect', 'damage_taken', 'Damage taken (multiplier)', 'f32',
                        { part('damage_taken', T_STATUS, at + k * 8 + 4, 'f32', 100) }, 0, 10, 0.05, 0.25)
            end
        end
    elseif kind == 'drain' then
        local srow = MOD.boosters.status(b[5])
        local did = srow and default_of(field_at(T_STATUS, srow + 44, 'u32', 100000))
        local qrow = did and did > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
        if qrow then damage_rows(entry, 'Health drain', 'drain_', qrow, nil, 2) end
    elseif kind == 'blast' or kind == 'smoke' then
        local xrow, qrow = MOD.boosters.blast(b[5], b[6])
        if not xrow then return end
        if qrow then
            damage_rows(entry, 'Explosion', 'x_', qrow, 'Explosion')
            status_rows(entry, 'Explosion', 'x_', qrow, 'blast')
        end
        local radii = kind == 'smoke' and { { 'inner', 'Smoke radius, full (m)', 16 }, { 'outer', 'Smoke radius, edge (m)', 20 } }
                      or { { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 }, { 'shockwave', 'Shockwave radius (m)', 24 } }
        for _, r in ipairs(radii) do
            add_row(entry, kind == 'smoke' and 'Smoke' or 'Explosion', 'x_' .. r[1], r[2], 'f32',
                    { part('x_' .. r[1], T_EXPLOSION, xrow + r[3], 'f32', 100000) }, 0, 200, 0.1, 1)
        end
        MOD.explosion_extras(entry, kind == 'smoke' and 'Smoke' or 'Explosion', 'x_', xrow)
    elseif kind == 'turret' then
        resolve_gun(entry, hash_key(b[5]))
    elseif kind == 'eat' then
        for _, group in ipairs(stratagem_groups) do
            local off = tables[group] and tables[group].index[b[5]]
            if off then
                add_row(entry, 'Stratagem', 'uses', 'Uses per mission', 'u32', { part('uses', group, off + 80, 'u32', 999) }, 0, 999, 1, 5)
                break
            end
        end
    end
end

-- ---------------------------------------------------------------- the Enemy Editor
-- The Enemy Editor button turns the panel into the enemies' editor (its own tabs, red): one page per enemy
-- and structure of MOD.ENEMY_LIST (HD2Runtime's enemy catalogue: faction, kind, name, variant, entity, zone
-- names), and a Spawning page per faction. Saved and installed with everything else.
-- Variants of one enemy whose health records are the same share a page (every one is written).
MOD.enemy = { on = false, TABS = { 'Terminids', 'Automatons', 'Illuminate', 'SEAF', 'Spawning' },
              FACTIONS = { terminids = 'Terminids', automatons = 'Automatons', illuminate = 'Illuminate', seaf = 'SEAF' },
              ZONE = 552, ZONES = 520 }

-- 'leg_right' -> 'Right leg', 'l_wrist' -> 'Left wrist'
-- Body parts no catalogue names, by the name hash at zone +96 (murmur64a's upper half, found by trying names;
-- the Heatsink also by the wiki's numbers)
MOD.enemy.PART_NAMES = {
    [0x2B047266] = 'heatsink', [0xB709FE1C] = 'back_leg', [0x83BAB375] = 'back_lower_leg',
    [0x70828B7A] = 'back_upper_leg', [0x3B75843B] = 'back_upper_leg_top', [0x7778AF66] = 'backpack',
    [0x73757F26] = 'boss_head', [0x21014345] = 'engine_rear_weakspot', [0xB455B1EE] = 'eye_top',
    [0x2D0AC038] = 'headplate', [0x47344B93] = 'jetpack', [0xF73F6AF7] = 'left_arm_armor',
    [0x718CE684] = 'left_arm_weakspot', [0xC10B192C] = 'left_back_leg_armor', [0x19C4C9A6] = 'left_collar',
    [0xA6323908] = 'left_front_leg_armor', [0x0D324590] = 'left_gun_weakspot',
    [0x15B7E16D] = 'left_lower_arm', [0x5E8233FA] = 'left_lower_leg', [0x39241507] = 'left_middle_leg',
    [0x93C0058D] = 'left_upper_leg', [0x83A150AB] = 'left_upper_leg_top', [0x23128279] = 'pilot',
    [0x49807680] = 'right_arm_armor', [0x61DCC7A6] = 'right_arm_weakspot',
    [0xCA9ED401] = 'right_back_leg_armor', [0x6E41F493] = 'right_collar',
    [0x53DF0BFD] = 'right_front_leg_armor', [0xD19627FC] = 'right_gun_weakspot',
    [0x20C2028D] = 'right_lower_arm', [0x50C392D7] = 'right_lower_leg', [0xFF9A5522] = 'right_middle_leg',
    [0x56EB4767] = 'right_upper_leg', [0x04B52E77] = 'right_upper_leg_top', [0xA2BF8B44] = 'weakspot',
    [0x46C655CA] = 'weakspot_engine',
}

function MOD.enemy.zone_name(name)
    if not name or name == '' then return nil end
    local words = {}
    for w in name:gsub('_', ' '):gmatch('%S+') do words[#words + 1] = w end
    local side = { l = 'left', r = 'right', left = 'left', right = 'right' }
    for k = #words, 2, -1 do
        if side[words[k]] then table.insert(words, 1, side[table.remove(words, k)]) end
    end
    if side[words[1]] then words[1] = side[words[1]] end
    local text = table.concat(words, ' ')
    return text:sub(1, 1):upper() .. text:sub(2)
end

-- The pages: per faction and name, the variants with the same health record together.
function MOD.enemy.build()
    for k = #weapons, 1, -1 do
        if weapons[k].enemy then by_hash[weapons[k].hash] = nil; table.remove(weapons, k) end
    end
    local ht = tables[TYPES.health]
    if not ht then return end
    local top = ht.copies[1] + HEADER_BYTES
    local groups, order = {}, {}
    for _, e in ipairs(MOD.ENEMY_LIST or {}) do
        local key = hash_key(e[5])
        local at = ht.index[key]
        -- or none: a structure that only jams (the Stratagem Jammer's health is on another entity)
        if at or (tables[TYPES.jammer] and tables[TYPES.jammer].index[key])
              or (tables[TYPES.scrambler] and tables[TYPES.scrambler].index[key]) then
            local id = e[1] .. '|' .. e[2] .. '|' .. e[3]
            if not groups[id] then groups[id] = {}; order[#order + 1] = id end
            local bytes = at and api.read(top + at, KINDS[TYPES.health].stride) or ''
            local into
            for _, b in ipairs(groups[id]) do if b.bytes == bytes then into = b; break end end
            if not into then into = { bytes = bytes, members = {} }; table.insert(groups[id], into) end
            into.members[#into.members + 1] = { e = e, key = key, at = at }
        end
    end
    local list = {}
    for _, id in ipairs(order) do
        local buckets = groups[id]
        for _, b in ipairs(buckets) do
            local first = b.members[1].e
            -- the variant's words that differ from the others' (all start 'Conscript ...': 'Shotgun')
            local label = nil
            if #buckets > 1 then
                local best = first[4]
                for _, m in ipairs(b.members) do if m.e[4] ~= '' and (#m.e[4] < #best or best == '') then best = m.e[4] end end
                label = best ~= '' and best:gsub('^Entry (%d+)$', 'variant %1') or nil
            end
            local name = first[3] .. (label and (' (' .. label .. ')') or '')
            local hash = first[5]
            -- every variant's attacks, once each
            local attacks, had = {}, {}
            for _, m in ipairs(b.members) do
                for a in (m.e[7] or ''):gmatch('[^;]+') do
                    if not had[a] then had[a] = true; attacks[#attacks + 1] = a end
                end
            end
            list[#list + 1] = { name = name, slot = MOD.enemy.FACTIONS[first[1]], hash = hash, rows = {}, by_id = {},
                                enemy = { members = b.members, zones = first[6], attacks = table.concat(attacks, ';'), structure = first[2] == 'structure' },
                                note = (first[2] == 'structure' and 'Structure.' or first[1] == 'seaf' and 'SEAF soldier: an ally.' or 'Enemy.') ..
                                       (#b.members > 1 and (' ' .. #b.members .. ' variants share these values.') or '') }
        end
    end
    -- the same name twice (two variants named alike): numbered
    local seen = {}
    for _, entry in ipairs(list) do
        local k = entry.slot .. entry.name
        seen[k] = (seen[k] or 0) + 1
        if seen[k] > 1 then entry.name = entry.name .. ' ' .. seen[k] end
    end
    table.sort(list, function(a, b)
        if a.enemy.structure ~= b.enemy.structure then return not a.enemy.structure end
        return a.name:lower() < b.name:lower()
    end)
    for _, entry in ipairs(list) do weapons[#weapons + 1] = entry; by_hash[entry.hash] = entry end
    MOD.enemy.guns_build(list)
    MOD.enemy.spawning_build()
end

-- Enemy guns: each enemy's own gun (its entity has a weapon record: the Hulk's arms), the ones it mounts
-- (MountComponent: 5 x 24 bytes, +0 the mounted entity; two levels, tank -> turret -> gun) and carries
-- (InventoryComponent +0 / +8 / +16: primary, sidearm, support). A page per gun, after the first enemy that
-- has it; its rows are a weapon's (resolve_gun). A gun that is the enemy itself gets a page hash of its own
-- (the entity's halves swapped), so the enemy page keeps its own.
MOD.enemy.GUN_KINDS = { T_WEAPON, T_BEAM_WEAPON, T_SPRAY }
-- An enemy's weapon page without the rows an AI has no use for (a player gun's handling and resupply; spread
-- stays). SEAF soldiers carry real player weapons: theirs are kept whole.
MOD.enemy.GUN_DROP = { recoil_h = true, recoil_v = true, sway = true, ergonomics = true, mags_start = true,
                       mags_supply = true, mags_max = true, suppressed = true }
function MOD.enemy.gun_tidy(weapon)
    if weapon.slot == 'SEAF' then return end
    local kept = {}
    for _, r in ipairs(weapon.rows) do
        if MOD.enemy.GUN_DROP[r.id] then
            for _, p in ipairs(r.parts) do
                if weapon.by_id[p.id] == p then weapon.by_id[p.id] = nil end
                local users = p.field.users
                for k = #users, 1, -1 do if users[k] == weapon then table.remove(users, k) end end
            end
        else kept[#kept + 1] = r end
    end
    -- nothing but spread and a magazine (a body's empty gun part): no page
    local real = false
    for _, r in ipairs(kept) do if r.section ~= 'Handling' and r.section ~= 'Ammo' then real = true end end
    weapon.rows = real and kept or {}
end

-- The Terminids' attacks by their page's first name -> what it is (the page's number stays: saved values keep applying)
MOD.enemy.GUN_NAMES = {
    ['Bile Spewer (Base): mounted weapon 1'] = 'bile spray', ['Bile Spewer (Base): mounted weapon 2'] = 'bile mortar',
    ['Bile Spitter: weapon'] = 'acid spit', ['Bile Titan: weapon'] = 'bile spray', ['Spore Burst Bile Titan: weapon'] = 'spore spray',
    ['Dragonroach: mounted weapon'] = 'fire breath', ['Hive Lord: mounted weapon 1'] = 'acid spit 1',
    ['Hive Lord: mounted weapon 2'] = 'acid spit 2', ['Nursing Spewer: mounted weapon 1'] = 'bile spray',
    ['Predator Hunter: mounted weapon'] = 'acid spray',
}

function MOD.enemy.guns_build(list)
    local mt, it = tables[TYPES.mount], tables[TYPES.inventory]
    local top = function(t) return t.copies[1] + HEADER_BYTES end
    local function is_gun(key)
        for _, kind in ipairs(MOD.enemy.GUN_KINDS) do
            if tables[kind] and tables[kind].index[key] then return true end
        end
        return false
    end
    local function hex(key)
        local out = {}
        for k = #key, 1, -1 do out[#out + 1] = string.format('%02X', key:byte(k)) end
        return table.concat(out)
    end
    local seen, added = {}, {}
    for _, entry in ipairs(list) do
        local guns = {}
        local function add(key, label)
            if key and key ~= string.rep('\0', 8) and is_gun(key) and not guns[key] then
                guns[key] = true
                guns[#guns + 1] = { key = key, label = label }
            end
        end
        local function mounts(key, depth)
            local at = mt and mt.index[key]
            if not at then return end
            local bytes = api.read(top(mt) + at, 120)
            for m = 0, 4 do
                local sub = bytes:sub(m * 24 + 1, m * 24 + 8)
                if sub ~= string.rep('\0', 8) then
                    add(sub, 'Mounted weapon')
                    if depth < 2 then mounts(sub, depth + 1) end
                end
            end
        end
        for _, m in ipairs(entry.enemy.members) do
            add(m.key, 'Weapon')
            mounts(m.key, 1)
            local at = it and it.index[m.key]
            if at then
                local bytes = api.read(top(it) + at, 24)
                add(bytes:sub(1, 8), 'Primary weapon')
                add(bytes:sub(9, 16), 'Sidearm')
                add(bytes:sub(17, 24), 'Support weapon')
            end
        end
        local count = {}
        for _, g in ipairs(guns) do count[g.label] = (count[g.label] or 0) + 1 end
        local n = {}
        for _, g in ipairs(guns) do
            if seen[g.key] then
                local page = seen[g.key]
                page.users = page.users .. ', ' .. entry.name
            else
                n[g.label] = (n[g.label] or 0) + 1
                local h = hex(g.key)
                if g.key == entry.enemy.members[1].key or by_hash[h] then
                    h = h:sub(9) .. h:sub(1, 8)
                end
                local name = entry.name .. ': ' .. g.label:lower() .. (count[g.label] > 1 and (' ' .. n[g.label]) or '')
                local page = { name = MOD.enemy.GUN_NAMES[name] and (entry.name .. ': ' .. MOD.enemy.GUN_NAMES[name]) or name,
                               slot = entry.slot, hash = h, key = g.key, rows = {}, by_id = {},
                               enemy = { gun = true, structure = entry.enemy.structure }, users = entry.name }
                seen[g.key] = page
                added[#added + 1] = { page = page, after = entry }
            end
        end
    end
    -- each after its enemy
    for _, a in ipairs(added) do
        local at = #weapons + 1
        for k, w in ipairs(weapons) do if w == a.after then at = k + 1 end end
        while weapons[at] and weapons[at].enemy and weapons[at].enemy.gun do at = at + 1 end
        table.insert(weapons, at, a.page)
        by_hash[a.page.hash] = a.page
        a.page.note = 'A weapon of ' .. a.page.users .. '.'
    end
end

-- An enemy's rows: its health component (every variant on the page written): health +0, armor +280 (the
-- body's, where no zone has its own), durable ratio +268, explosive damage share +388, bleed-out health
-- (constitution) +24, regeneration +4 / delay +12; then each named zone (+520, 552 bytes; +96 its name):
-- health +232 (-1: the body's), armor +216, durable ratio +204, explosive share +324 (unset: FLT_MAX),
-- damage passed to the body +248, fatal +244 (byte).
function MOD.enemy.resolve(entry)
    local members = entry.enemy.members
    -- a structure's demolition force (after its health rows)
    local function demolition()
        if entry.enemy.structure then KINDS[TYPES.destruction].demolition_rows(entry, members[1].key, 'Health', '', members[1].at) end
    end
    if not members[1].at then demolition(); MOD.enemy.more_rows(entry); return end
    local function parts(id, offset, storage, limit)
        local out = {}
        for n, m in ipairs(members) do out[n] = part(n == 1 and id or (id .. '_' .. n), TYPES.health, m.at + offset, storage, limit) end
        return out
    end
    local function row(section, id, label, offset, storage, limit, max, small, big, note)
        local p = parts(id, offset, storage, limit)
        if read_field(p[1].field) == nil then return nil end
        local r = add_row(entry, section, id, label, storage, p, 0, max, small, big)
        r.lead = #p > 1 or nil   -- (same values: the first stands for all)
        r.note = note
        return r
    end
    row('Health', 'health', 'Health', 0, 'u32', 10000000, 1000000, 10, 100)
    row('Health', 'armor', 'Armor', 280, 'u32', 100, 10, 1, 1, 'body parts without their own armor use this')
    row('Health', 'durable', 'Durable ratio (0-1)', 268, 'f32', 1, 1, 0.05, 0.1,
        "0: hits deal their normal damage, 1: their durable damage (the weapon's lower one)")
    for _, p in ipairs(parts('explosive', 388, 'f32', 100)) do p.field.unset = 1 end   -- (most: not set, normal damage)
    row('Health', 'explosive', 'Explosive damage taken (x)', 388, 'f32', 100, 100, 0.05, 0.25)
    local ht = tables[TYPES.health]
    local top = ht.copies[1] + HEADER_BYTES
    -- only where the game sets it (a million on a Hulk, which has none, did nothing in game)
    if (peek4(top + members[1].at + 24) or 0) > 0 then
        row('Health', 'bleed', 'Bleed-out health', 24, 'u32', 10000000, 1000000, 10, 100,
            'what it has left once its health is gone, lost over time')
        -- +28 the bleed-out health's change per second (negative: shown as the health lost)
        for _, p in ipairs(parts('bleed_drain', 28, 'f32', 10000000)) do p.field.signed = true end
        local drain = row('Health', 'bleed_drain', 'Bleed-out drain (health/s)', 28, 'f32', 10000000, 1000000, 1, 10,
                          'how fast the bleed-out health runs out')
        if drain then drain.scale = -1 end
    end
    -- +322 the part bleeds out at all (turning it on did nothing in game, Hulk arms; no rows without it)
    local function bleeds(base)
        return (peek4(top + members[1].at + base + 96) or 0) ~= 0
               and math.floor((peek4(top + members[1].at + base + 320) or 0) / 65536) % 256 ~= 0
    end
    local any_bleeds = false
    for z = 0, 37 do any_bleeds = any_bleeds or bleeds(MOD.enemy.ZONES + z * MOD.enemy.ZONE) end
    -- +36 the health lost per second by its body parts' bleed-out health (issue #91; positive, unlike +28)
    local zone_drain = any_bleeds and row('Health', 'zone_drain', 'Body part bleed-out drain (health/s)', 36, 'f32', 10000000, 1000000, 1, 10,
        "how fast a body part's bleed-out health runs out")
    row('Health', 'regen', 'Regeneration (health/s)', 4, 'f32', 1000000, 100000, 1, 10)
    row('Health', 'regen_delay', 'Regeneration delay after damage (s)', 12, 'f32', 3600, 600, 0.1, 1)
    demolition()
    local names = {}
    for z, n in (entry.enemy.zones or ''):gmatch('(%d+)=([^;]*)') do names[tonumber(z)] = n end
    local count = 0
    for z = 0, 37 do
        local base = MOD.enemy.ZONES + z * MOD.enemy.ZONE
        if (peek4(top + members[1].at + base + 96) or 0) ~= 0 then
            count = count + 1
            local section = MOD.enemy.zone_name(names[z] or MOD.enemy.PART_NAMES[peek4(top + members[1].at + base + 96)])
                            or ('Body part ' .. count)
            local id = 'zone' .. z
            row(section, id .. '_health', 'Health', base + 232, 'u32', 10000000, 1000000, 10, 100)
            -- (where it does not bleed out, what the game sets is extra health: Hulk legs, 500 that never drains)
            local drains = bleeds(base)
            local bleed = (drains or (peek4(top + members[1].at + base + 236) or 0) > 0)
                          and row(section, id .. '_bleed', 'Bleed-out health', base + 236, 'u32', 10000000, 1000000, 10, 100,
                                  drains and 'what it has left once its health is gone, lost over time'
                                         or 'extra health for this part, it does not run out by itself')
            -- the game has one drain per enemy (+36), so a part's time (issue #119) is its bleed-out health over that:
            -- this row shows the bleed-out health's parts in seconds
            if drains and bleed and zone_drain and read_field(zone_drain.parts[1].field) > 0 then
                local time = add_row(entry, section, id .. '_bleed_time', 'Bleed-out time (s)', 'f32', bleed.parts, 0, 3600, 0.1, 1)
                time.lead, time.drain = bleed.lead, zone_drain
                time.note = 'how long it lasts once its health is gone; this sets its bleed-out health, so it also takes more shots to finish'
            end
            row(section, id .. '_armor', 'Armor', base + 216, 'u32', 100, 10, 1, 1)
            row(section, id .. '_durable', 'Durable ratio (0-1)', base + 204, 'f32', 1, 1, 0.05, 0.1)
            row(section, id .. '_explosive', 'Explosive damage taken (x)', base + 324, 'f32', 100, 100, 0.05, 0.25)
            row(section, id .. '_to_body', 'Damage passed to the body (x)', base + 248, 'f32', 100, 100, 0.05, 0.25)
            row(section, id .. '_fatal', 'Killing it kills the enemy', base + 244, 'flag', 1, 1, 1, 1)
        end
    end
    MOD.enemy.more_rows(entry)
end

-- The status rows (StatusEffectSusceptibilityType kinds; +144 / +148 the buildup thresholds, +168 damage taken)
MOD.enemy.STATUSES = {
    { id = 'stun_resist', label = 'Stun resistance (x)', kinds = { [22] = true, [23] = true }, offsets = { 144, 148 },
      note = 'how much stun it takes to stun it' },
    { id = 'gas_resist', label = 'Gas resistance (x)', kinds = { [27] = true, [28] = true }, offsets = { 144, 148 },
      note = 'how much gas it takes to confuse it' },
    { id = 'fire_taken', label = 'Fire damage taken (x)', kinds = { [6] = true, [12] = true }, offsets = { 168 } },
    { id = 'acid_taken', label = 'Acid damage taken (x)', kinds = { [10] = true }, offsets = { 168 } },
    { id = 'electric_taken', label = 'Electric damage taken (x)', kinds = { [20] = true }, offsets = { 168 } },
    { id = 'gas_taken', label = 'Gas damage taken (x)', kinds = { [27] = true, [28] = true }, offsets = { 168 } },
}

-- The rest of an enemy's page, from its other components (each variant on the page written):
-- Movement: AiEnemy (736 bytes in this build) state speeds guard +0, patrol +36, investigate +60, combat +100,
-- strafe +124, drift +152, retreat +244, charge +276; AiCharacter +0 preferred / +4 maximum speed.
-- Senses: SensorEye +0 sight distance, +12 / +16 cone angles; SensorEar +4 hearing multiplier.
-- Size: Unit +8 / +12 scale. Attacks: its melee damage rows (MOD.ENEMY_LIST's 7th field).
MOD.enemy.SPEEDS = { 0, 36, 60, 100, 124, 152, 244, 276 }
MOD.enemy.SPEED_LABELS = { 'Idle walking speed (m/s)', 'Patrolling speed (m/s)', 'Searching speed (m/s)', 'Fighting speed (m/s)',
                           'Strafing speed (m/s)', 'Drifting speed (m/s)', 'Retreating speed (m/s)', 'Charging speed (m/s)' }
function MOD.enemy.more_rows(entry)
    local members = entry.enemy.members
    local function at(kind, m) return tables[kind] and tables[kind].index[m.key] end
    -- rows over every variant's record of `kind` that has one
    local function row(kind, section, id, label, offsets, storage, limit, min, max, small, big, note)
        local p = {}
        for n, m in ipairs(members) do
            local base = at(kind, m)
            if base then
                for k, off in ipairs(offsets) do
                    local pid = id .. (n > 1 and ('_' .. n) or '') .. (k > 1 and ('_' .. k) or '')
                    p[#p + 1] = part(#p == 0 and id or pid, kind, base + off, storage, limit)
                end
            end
        end
        if #p == 0 or read_field(p[1].field) == nil then return nil end
        local r = add_row(entry, section, id, label, storage, p, min, max, small, big)
        r.lead = #p > 1 or nil
        r.note = note
        return r
    end
    -- movement: one multiplier over every speed the enemy has (0: a state it doesn't use)
    local fields = {}
    for _, m in ipairs(members) do
        local ai, ch = at(TYPES.ai_enemy, m), at(TYPES.ai_character, m)
        if ai then
            for _, off in ipairs(MOD.enemy.SPEEDS) do
                local v = read_field(field_at(TYPES.ai_enemy, ai + off, 'f32', 1000))
                if v and v > 0 and v < 1000 then fields[#fields + 1] = { TYPES.ai_enemy, ai + off } end
            end
        end
        if ch then fields[#fields + 1] = { TYPES.ai_character, ch }; fields[#fields + 1] = { TYPES.ai_character, ch + 4 } end
    end
    if #fields > 0 then
        MOD.enemy.mult_row(entry, 'Movement', 'speed', 'Movement speed (x)', fields, 10, nil,
                           'walking, patrolling, searching, fighting and charging speeds together')
        -- each state's own speed, for the states it uses (the first variant's speed above 0)
        local ai = at(TYPES.ai_enemy, members[1])
        for k, label in ipairs(MOD.enemy.SPEED_LABELS) do
            local v = ai and read_field(field_at(TYPES.ai_enemy, ai + MOD.enemy.SPEEDS[k], 'f32', 1000))
            if v and v > 0 and v < 1000 then
                row(TYPES.ai_enemy, 'Movement', 'move_' .. k, label, { MOD.enemy.SPEEDS[k] }, 'f32', 1000, 0, 50, 0.1, 0.5)
            end
        end
    end
    MOD.physics.anim_rows(entry)
    row(TYPES.sensor, 'Senses', 'sight', 'Sight range (m)', { 0 }, 'f32', 10000, 0, 1000, 1, 10)
    local keys = {}
    for _, m in ipairs(members) do keys[#keys + 1] = m.key end
    MOD.faction.row(entry, 'Senses', 'faction', keys)
    -- the weapons it carries (inventory +0 / +8 / +16): SEAF only, a SEAF or player weapon instead
    -- (an enemy's gun in SEAF hands crashed the game; enemies keep theirs)
    for _, slot in ipairs(entry.slot == 'SEAF' and { { 0, 'gun_primary', 'Primary weapon' }, { 8, 'gun_sidearm', 'Sidearm' }, { 16, 'gun_support', 'Support weapon' } } or {}) do
        local p = {}
        for n, m in ipairs(members) do
            local base = at(TYPES.inventory, m)
            local bytes = base and api.read(tables[TYPES.inventory].copies[1] + HEADER_BYTES + base + slot[1], 8)
            if bytes and bytes ~= string.rep('\0', 8) then
                p[#p + 1] = part(#p == 0 and slot[2] or (slot[2] .. '_' .. n), TYPES.inventory, base + slot[1], 'gun', 4294967295)
            end
        end
        if #p > 0 and read_field(p[1].field) then
            local r = add_row(entry, 'Weapons carried', slot[2], slot[3], 'gun', p, 1, 4294967295, 1, 10)
            r.choice = 'gun'
            r.label_of = function()
                local g = MOD.enemy.gun_choices().by_id[read_field(p[1].field) or 0]
                return slot[3] .. ': ' .. (g and g.label or '?')
            end
        end
    end
    -- how long it keeps tracking you out of sight (target retention +16: how fast it forgets; x2: half as fast)
    local keep = {}
    for _, m in ipairs(members) do
        local r = at(TYPES.retention, m)
        if r and (read_field(field_at(TYPES.retention, r + 16, 'f32', 1000)) or 0) > 0 then keep[#keep + 1] = { TYPES.retention, r + 16 } end
    end
    -- statuses: per kind (StatusEffectReceiver), the buildup it needs (thresholds) or the damage it takes (x)
    for _, st in ipairs(MOD.enemy.STATUSES) do
        local fields = {}
        for _, m in ipairs(members) do
            local rx = at(TYPES.status_rx, m)
            for z = 0, rx and 7 or -1 do
                for k = 0, 32 do
                    local e = rx + z * 5816 + 8 + k * 176
                    local kind = read_field(field_at(TYPES.status_rx, e + 140, 'u32', 1000))
                    if kind and st.kinds[kind] then
                        for _, off in ipairs(st.offsets) do
                            local v = read_field(field_at(TYPES.status_rx, e + off, 'f32', 100000))
                            if v and v > 0 then fields[#fields + 1] = { TYPES.status_rx, e + off } end
                        end
                    end
                end
            end
        end
        if #fields > 0 then MOD.enemy.mult_row(entry, 'Statuses', st.id, st.label, fields, 20, nil, st.note) end
    end
    -- how hard a hit must be to stagger it (each hit size's force threshold)
    local hold = {}
    for _, m in ipairs(members) do
        local h = at(TYPES.hitreact, m)
        if h then
            for k = 0, 5 do
                local size = read_field(field_at(TYPES.hitreact, h + 4 + k * 36, 'u32', 100))
                local need = read_field(field_at(TYPES.hitreact, h + 8 + k * 36, 'u32', 100000))
                if size and size >= 1 and size <= 4 and need and need > 0 then hold[#hold + 1] = { TYPES.hitreact, h + 8 + k * 36, 'u32' } end
            end
        end
    end
    if #hold > 0 then
        MOD.enemy.mult_row(entry, 'Health', 'stagger_resist', 'Stagger resistance (x)', hold, 20, nil,
                           'the force a hit needs to stagger it (hit sizes it never staggers from stay that way)')
    end
    if #keep > 0 then
        MOD.enemy.mult_row(entry, 'Senses', 'retention', 'Tracking after losing sight (x)', keep, 20, true,
                           'how long it keeps hunting you once you break line of sight; x1: as in the game, x2: twice as long')
    end
    row(TYPES.sensor, 'Senses', 'sight_h', 'Sight cone width (degrees)', { 12 }, 'f32', 360, 0, 360, 1, 10)
    row(TYPES.sensor, 'Senses', 'sight_v', 'Sight cone height (degrees)', { 16 }, 'f32', 360, 0, 360, 1, 10)
    row(TYPES.ear, 'Senses', 'hearing', 'Hearing (x)', { 4 }, 'f32', 100, 0, 100, 0.05, 0.25)
    row(TYPES.danger, 'Suppression', 'danger_radius', 'Shots count within (m)', { 4 }, 'f32', 1000, 0, 100, 0.5, 2,
        'how close your shots must land to rattle it')
    row(TYPES.targeting, 'Suppression', 'flinch', 'Flinch from your fire', { 36 }, 'f32', 1000, 0, 100, 0.1, 0.5,
        'how hard your fire throws off its aim; 0: never; higher: a little fire throws it off fully')
    -- shown as the seconds a fully thrown-off aim takes to settle: the flinch cap (+44) over how fast it drains (+40)
    local tg = members[1] and at(TYPES.targeting, members[1])
    if tg then
        local cap = field_at(TYPES.targeting, tg + 44, 'f32', 1000)
        local r = row(TYPES.targeting, 'Suppression', 'flinch_recover', 'Aim steadies again after (s)', { 40 }, 'f32', 10000, 0.01, 60, 0.05, 0.25,
                      'how long its aim stays thrown off after your fire stops; Never: it never steadies')
        if r then   -- (every variant written from the first's cap, so not a lead row)
            r.span, r.span_default, r.lead = function() return read_field(cap) end, function() return default_of(cap) end, nil
            r.never = true   -- a drain of 0 shows as Never (Tanks, Berserkers...), not blank
        end
    end
    row(TYPES.unit, 'Size', 'scale', 'Size (x)', { 8, 12 }, 'f32', 100, 0.1, 10, 0.05, 0.25,
        'the model and its body parts; on some enemies the hitboxes may not match the model, and on others it may not work at all')
    local jam_note = 'stratagems cannot be called within this distance while it stands'
    for _, m in ipairs(members) do   -- the kind it blocks (+0): 7 every kind, 0 Eagles
        local j = at(TYPES.jammer, m)
        if j then
            local kind = read_field(field_at(TYPES.jammer, j, 'u32', 100))
            if kind == 0 then jam_note = 'Eagles cannot be called within this distance while it stands'
            elseif kind and kind ~= 7 then jam_note = 'one kind of stratagem cannot be called within this distance while it stands' end
            break
        end
    end
    -- 0 (or less) is no limit in the game: it jams the whole map, so 0.1 m is the least
    row(TYPES.jammer, 'Jamming', 'jam_radius', 'Stratagem jamming radius (m)', { 12 }, 'f32', 100000, 0.1, 10000, 5, 25, jam_note)
    row(TYPES.scrambler, 'Jamming', 'scramble_radius', 'Stratagem scrambling radius (m)', { 12 }, 'f32', 100000, 0.1, 10000, 5, 25,
        'stratagem codes and names are scrambled within this distance while it stands')
    row(TYPES.curve, 'Movement', 'flight_height', 'Flight height (m)', { 52 }, 'f32', 10000, 0, 1000, 1, 5,
        'its height above its flight route; lower flies closer to the ground (terrain still holds it up)')
    -- its energy shield (ShieldComponentData, as the player's shields)
    row(TYPES.shield, 'Shield', 'shield_capacity', 'Shield capacity', { 76 }, 'f32', 1000000, 0, 1000000, 50, 250)
    row(TYPES.shield, 'Shield', 'shield_delay', 'Recharge delay (s)', { 88 }, 'f32', 600, 0, 600, 1, 5)
    row(TYPES.shield, 'Shield', 'shield_broken', 'Recharge delay once broken (s)', { 92 }, 'f32', 600, 0, 600, 1, 5)
    row(TYPES.shield, 'Shield', 'shield_rate', 'Recharge rate (per s)', { 96 }, 'f32', 1000000, 0, 1000000, 10, 50)
    for drow_id, label in (entry.enemy.attacks or ''):gmatch('(%d+)=([^;]*)') do
        local drow = tables[T_DAMAGE] and tables[T_DAMAGE].index[tonumber(drow_id)]
        if drow then
            local section = 'Attack: ' .. label
            local prefix = 'atk' .. drow_id .. '_'
            for _, s in ipairs({ { 'damage', 'Damage', 4, 1, 10 }, { 'durable', 'Durable damage', 8, 1, 10 },
                                 { 'ap', 'Armor penetration', 12, 1, 1 }, { 'stagger', 'Stagger force', 32, 1, 10 },
                                 { 'push', 'Push force', 36, 1, 10 } }) do
                local r = add_row(entry, section, prefix .. s[1], s[2], 'u32',
                                  { part(prefix .. s[1], T_DAMAGE, drow + s[3], 'u32', 1000000) }, 0,
                                  s[1] == 'ap' and 10 or 100000, s[4], s[5])
                if s[1] == 'damage' then r.note = 'every enemy with this attack shares it' end
            end
        end
    end
end

-- Spawning (HiveMindComponentData, one record per mission type, +0 faction: 2 Terminids, 4 Illuminate, 8
-- Automatons; FileDiver's names, the fields Little Enemy Kontrol and HD2Runtime 0.40 tested): multipliers over
-- every record of the faction. Each scales the 4 player-count multipliers (1-4 players) of a mission-difficulty
-- modifier; rows marked `inverse` hold a duration (shown as how often: 2 = twice as often).
-- (s[7]: the row's (?) tip)
MOD.enemy.MODIFIER_TIP = { "The patrols a planet or mission modifier adds: gunships, Dragonroaches, Leviathans and the like.",
                           "Separate from the normal ground patrols. Does nothing on a mission without such a modifier." }
MOD.enemy.SPAWN = {
    { 'Reinforcements', 'reinf_on', 'Reinforcements (flares, breaches, drops)', 1077, 'flag' },
    { 'Reinforcements', 'reinf_budget', 'Reinforcement size (x)', 316 },
    { 'Reinforcements', 'reinf_rate', 'Reinforcement frequency (x)', 376 },
    { 'Reinforcements', 'cap', 'Enemy cap (x)', 128, 'one',
      'the game holds back reinforcements past about 100 enemies at x1; it has crashed past 200-240 enemies alive' },
    { 'Patrols', 'patrol_rate', 'Patrol frequency (x)', 496 },
    { 'Patrols', 'patrol_max', 'Patrols at once (x)', 436, nil, '0: no patrols' },
    { 'Patrols', 'traveler_rate', 'Modifier patrol frequency (x)', 976, 'inverse', nil, MOD.enemy.MODIFIER_TIP },
    { 'Patrols', 'traveler_size', 'Modifier patrol size (x)', 1036, nil, nil, MOD.enemy.MODIFIER_TIP },
    { 'Outposts and spawners', 'guard', 'Outpost garrison size (x)', 856 },
    { 'Outposts and spawners', 'spawner_queue', 'Fabricator / bug hole queue (x)', 556 },
    { 'Outposts and spawners', 'spawner_count', 'Fabricator / bug hole batch size (x)', 676 },
    { 'Outposts and spawners', 'spawner_production', 'Fabricator / bug hole refill speed (x)', 616 },
    { 'Outposts and spawners', 'spawner_release', 'Fabricator / bug hole release speed (x)', 796 },
}
MOD.enemy.FACTION_IDS = { Terminids = 2, Automatons = 8, Illuminate = 4, SEAF = 16 }

function MOD.enemy.spawning_build()
    for _, name in ipairs({ 'Terminids', 'Automatons', 'Illuminate' }) do
        local hash = string.format('FFFFFFFC%08X', MOD.enemy.FACTION_IDS[name])
        local entry = { name = name, slot = 'Spawning', hash = hash, rows = {}, by_id = {},
                        enemy = { spawning = MOD.enemy.FACTION_IDS[name] },
                        note = 'Spawning on ' .. name .. ' missions (every mission type). Multipliers of the game\'s values.' }
        weapons[#weapons + 1] = entry
        by_hash[hash] = entry
    end
    local hash = 'FFFFFFFC000000FF'
    local entry = { name = 'All factions', slot = 'Spawning', hash = hash, rows = {}, by_id = {}, enemy = { floors = true },
                    note = 'Spawning limits every faction shares.' }
    weapons[#weapons + 1] = entry
    by_hash[hash] = entry
    -- a faction-wide page, first in each faction's list (MOD.enemy.faction_refresh writes its rows)
    for _, name in ipairs({ 'Terminids', 'Automatons', 'Illuminate', 'SEAF' }) do
        local h = string.format('FFFFFFFB%08X', MOD.enemy.FACTION_IDS[name])
        local page = { name = 'All ' .. name, slot = name, hash = h, rows = {}, by_id = {}, enemy = { faction = name },
                       note = name == 'SEAF' and 'Every SEAF soldier at once. Soldiers you have edited on their own page keep their values.'
                              or 'Every enemy of this faction at once. Enemies you have edited on their own page keep their values.' }
        local at = #weapons + 1
        for k, w in ipairs(weapons) do if w.slot == name then at = k; break end end
        table.insert(weapons, at, page)
        by_hash[h] = page
        -- its death explosions, after the enemies (before the structures)
        local blasts = MOD.enemy.BLASTS[name]
        if blasts then
            local bh = string.format('FFFFFFFA%08X', MOD.enemy.FACTION_IDS[name])
            local bp = { name = 'Death explosions', slot = name, hash = bh, rows = {}, by_id = {}, enemy = { blasts = blasts, structure = true },
                         note = 'What goes off when they die. Each explosion is shared by every enemy that uses it.' }
            local spot = #weapons + 1
            for k, w in ipairs(weapons) do if w.slot == name and w.enemy and w.enemy.structure then spot = k; break end end
            table.insert(weapons, spot, bp)
            by_hash[bh] = bp
        end
    end
end

-- The weapons SEAF can carry: the player weapons' SEAF versions, then SEAF's own guns; a choice's number
-- is its entity's lower 32 bits, so saved choices outlast changes to the list. gun_id: 8 entity bytes -> number.
function MOD.enemy.gun_choices()
    local c = MOD.enemy.choices
    if c then return c end
    c = { list = {}, by_id = {}, by_key = {} }
    MOD.enemy.choices = c
    local function key_of(w)
        if w.key and #w.key == 8 then return w.key end
        if not (w.hash and #w.hash == 16) then return nil end
        local out = {}
        for k = 15, 1, -2 do out[#out + 1] = string.char(tonumber(w.hash:sub(k, k + 1), 16)) end
        return table.concat(out)
    end
    local function add(key, label)
        if not key or c.by_key[key] then return end
        local b1, b2, b3, b4 = key:byte(1, 4)
        local id = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
        if id == 0 or c.by_id[id] then return end
        local g = { id = id, key = key, label = label, n = #c.list + 1 }
        c.list[#c.list + 1] = g
        c.by_id[id], c.by_key[key] = g, id
    end
    -- only weapons the game loads for SEAF: a player weapon nobody brought shows as a missing model and never fires
    for _, w in ipairs(weapons) do
        if not w.enemy and w.name:find('(SEAF)', 1, true) then add(key_of(w), w.name) end
    end
    for _, w in ipairs(weapons) do   -- 'SEAF Leader: primary weapon' -> 'SEAF primary weapon'
        if w.enemy and w.enemy.gun and w.slot == 'SEAF' then add(key_of(w), (w.name:gsub('^SEAF [%a ]-: ', 'SEAF '))) end
    end
    return c
end
function MOD.enemy.gun_id(bytes)
    if not bytes or #bytes ~= 8 then return nil end
    local c = MOD.enemy.gun_choices()
    if not c.by_key[bytes] then   -- a weapon no page lists: kept as it is, under its hash
        local h = {}
        for k = 8, 1, -1 do h[#h + 1] = string.format('%02X', bytes:byte(k)) end
        local b1, b2, b3, b4 = bytes:byte(1, 4)
        local id = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
        if c.by_id[id] then return nil end
        local g = { id = id, key = bytes, label = 'weapon ' .. table.concat(h), n = #c.list + 1 }
        c.list[#c.list + 1] = g
        c.by_id[id], c.by_key[bytes] = g, id
    end
    return c.by_key[bytes]
end

-- The faction-wide rows: each scales (or, `add`, raises) one stat of every enemy page of the faction and its gun
-- pages. Only its own value is saved; MOD.enemy.faction_refresh writes the fields, leaving those another page
-- has a change on. `pick(page, row, part)`: whether a part of a page's row is one it covers.
function MOD.enemy.damage_part(p)   -- a damage row's damage / durable damage (+4 / +8 of a 76-byte record)
    local t = p.field and p.field.kind == T_DAMAGE and tables[T_DAMAGE]
    if not t then return false end
    t.starts = t.starts or {}
    if not next(t.starts) then for _, off in pairs(t.index) do t.starts[off] = true end end
    return t.starts[p.field.offset - 4] or t.starts[p.field.offset - 8] or false
end
MOD.enemy.FACTION_STATS = {
    { 'Toughness', 'all_health', 'Health (x)', 'mult', 20, 'the body and every body part, bleed-out health too',
      function(page, r) return not page.enemy.gun and (r.id == 'health' or r.id == 'bleed' or r.id:match('^zone%d+_health$')) end },
    { 'Toughness', 'all_armor', 'Armor (+)', 'add', 10, 'added to every armor value, up to 10; lowered: down to 0',
      function(page, r) return not page.enemy.gun and (r.id == 'armor' or r.id:match('^zone%d+_armor$')) end },
    { 'Toughness', 'all_stagger', 'Stagger resistance (x)', 'mult', 20, 'the force a hit needs to stagger them',
      function(page, r, p) return r.id == 'stagger_resist' and p ~= r.parts[1] end },
    { 'Toughness', 'all_status', 'Stun and gas resistance (x)', 'mult', 20, nil,
      function(page, r, p) return (r.id == 'stun_resist' or r.id == 'gas_resist') and p ~= r.parts[1] end },
    { 'Toughness', 'all_fire', 'Fire damage taken (x)', 'mult', 20, nil,
      function(page, r, p) return r.id == 'fire_taken' and p ~= r.parts[1] end },
    { 'Attacks', 'all_damage', 'Damage (x)', 'mult', 20, 'melee, guns and death explosions, shared ones included',
      function(page, r, p) return MOD.enemy.damage_part(p) end },
    { 'Attacks', 'all_spread', 'Weapon spread (x)', 'mult', 10, 'lower: their shots land closer to where they aim (0: dead on)',
      function(page, r) return r.id == 'spread_h' or r.id == 'spread_v' end },
    { 'Movement', 'all_speed', 'Movement speed (x)', 'mult', 10, nil,
      function(page, r, p) return r.id == 'speed' and p ~= r.parts[1] end },
    { 'Movement', 'all_anim', 'Animation speed (x)', 'mult', 10, 'how fast they attack, turn and react',
      function(page, r, p) return (r.id == 'anim_speed' or r.id == 'anim_attack' or r.id == 'anim_hit') and p ~= r.parts[1] end, 'anim' },
    { 'Senses', 'all_sight', 'Sight range (x)', 'mult', 10, nil,
      function(page, r) return not page.enemy.gun and r.id == 'sight' end },
    { 'Suppression', 'all_flinch', 'Flinch from your fire (x)', 'mult', 20, 'enemies at 0 stay immune',
      function(page, r) return not page.enemy.gun and r.id == 'flinch' end },
    { 'Suppression', 'all_danger_radius', 'Shots count within (x)', 'mult', 10, nil,
      function(page, r) return not page.enemy.gun and r.id == 'danger_radius' end },
}

-- Death explosions (ExplosionType ids of this build, checked against their records: the acid deaths carry acid):
-- { id, label }
MOD.enemy.BLASTS = {
    Terminids = { { 71, 'Scavenger acid burst' }, { 310, 'Warrior acid burst' }, { 275, 'Bile Spewer acid burst' },
                  { 276, 'Charger acid burst' } },
    Automatons = { { 10, 'Hulk death (and medium vehicles)' }, { 103, 'Vehicle death (medium, ground)' }, { 13, 'Vehicle death (large, ground)' },
                   { 39, 'Vehicle death (large, air)' }, { 346, 'Vehicle death (huge)' }, { 37, 'Fabricator death' },
                   { 114, 'Dropship death (air)' }, { 153, 'Dropship death (ground)' } },
    Illuminate = { { 311, 'Illusionist death' }, { 61, 'Spawner death' }, { 137, 'Dark Fluid burst' } },
}
function MOD.enemy.blasts_resolve(entry)
    for _, b in ipairs(entry.enemy.blasts) do
        local xrow = tables[T_EXPLOSION] and tables[T_EXPLOSION].index[b[1]]
        if xrow then
            local prefix = 'x' .. b[1] .. '_'
            local did = read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
            local qrow = did and did > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
            if qrow then damage_rows(entry, b[2], prefix, qrow, 'Explosion') end
            for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                 { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                add_row(entry, b[2], prefix .. r[1], r[2], 'f32', { part(prefix .. r[1], T_EXPLOSION, xrow + r[3], 'f32', 100000) }, 0, 200, 0.1, 1)
            end
            MOD.explosion_extras(entry, b[2], prefix, xrow)
        end
    end
end

function MOD.enemy.faction_resolve(entry)
    for _, s in ipairs(MOD.enemy.FACTION_STATS) do
        local lead = { id = s[2], field = field_at(0, 'enemy:' .. entry.hash .. ':' .. s[2], 'virtual', 1000) }
        local add = s[4] == 'add'
        lead.field.default = add and 0 or 1
        local r = add_row(entry, s[1], s[2], s[3], add and 'u32' or 'f32', { lead }, add and -10 or 0, s[5],
                          add and 1 or 0.05, add and 1 or 0.25)
        r.faction, r.add, r.note = s, add or nil, s[6]
        if s[8] == 'anim' then r.tip = MOD.physics.ANIM_TIP end
        lead.field.signed = add or nil
        if s == MOD.enemy.FACTION_STATS[#MOD.enemy.FACTION_STATS] then   -- under the last row: the blue marks
            r.after = { 'Enemies and values this page changes are marked in blue in the list and on their pages.',
                        "A value changed on an enemy's own page stays red: this page leaves it as it is." }
            r.after_h = #r.after * 16 + 6
        end
    end
end

-- A multiplier row: a value of its own (1: the game's) and the fields it multiplies (row.mult: each written as
-- its game value x the multiplier, or / it for `inverse`).
function MOD.enemy.mult_row(entry, section, id, label, fields, max, inverse, note, key)   -- key: a value pages share
    local lead = { id = id, field = field_at(0, key or ('enemy:' .. entry.hash .. ':' .. id), 'virtual', 1000) }
    lead.field.default = 1
    local p = { lead }
    for n, f in ipairs(fields) do p[#p + 1] = part(id .. '_' .. n, f[1], f[2], f[3] or 'f32', 1000000) end
    local r = add_row(entry, section, id, label, 'f32', p, inverse and 0.05 or 0, max or 10, 0.05, 0.25)
    r.lead, r.mult, r.inverse, r.note = true, true, inverse or nil, note
    return r
end

-- The example difficulties (Enemy Editor presets, added once): { name, { { faction id or 'all', 'page' (faction-wide)
-- / 'spawn' (its Spawning page) / 'floors' (All factions), row id, value }, ... } }
MOD.enemy.EXAMPLES = {
    { 'Default', {} },   -- no changes: loading it puts every enemy and spawning value back to the game's
    { 'Horde', { { 'all', 'spawn', 'reinf_budget', 2 }, { 'all', 'spawn', 'reinf_rate', 2 }, { 'all', 'spawn', 'patrol_rate', 2 },
                 { 'all', 'spawn', 'patrol_max', 2 }, { 'all', 'spawn', 'cap', 1.5 }, { 'all', 'page', 'all_health', 0.8 } } },
    { 'Glass Cannon', { { 'all', 'page', 'all_health', 0.5 }, { 'all', 'page', 'all_damage', 2 } } },
    { 'Elite', { { 'all', 'page', 'all_health', 1.5 }, { 'all', 'page', 'all_armor', 1 }, { 'all', 'page', 'all_damage', 1.25 },
                 { 'all', 'page', 'all_speed', 1.15 }, { 'all', 'page', 'all_sight', 1.5 } } },
}

function MOD.enemy.spawning_resolve(entry)
    if entry.enemy.floors then
        local ft = tables[TYPES.spawn_floor]
        local at = ft and next(ft.index) and ft.index[next(ft.index)]
        if not at then return end
        MOD.enemy.mult_row(entry, 'Lowest rates', 'floor_patrol', 'Lowest patrol frequency (x)',
                           { { TYPES.spawn_floor, at + 80 }, { TYPES.spawn_floor, at + 84 } }, 10, nil,
                           'the faction multipliers cannot slow patrols below this: lower it with them')
        MOD.enemy.mult_row(entry, 'Lowest rates', 'floor_reinf', 'Lowest reinforcement frequency (x)',
                           { { TYPES.spawn_floor, at + 88 }, { TYPES.spawn_floor, at + 92 } }, 10)
        MOD.enemy.mult_row(entry, 'SEAF', 'seaf_reinf', 'SEAF reinforcement cooldown (x)',
                           { { TYPES.spawn_floor, at + 48 }, { TYPES.spawn_floor, at + 52 }, { TYPES.spawn_floor, at + 56 },
                             { TYPES.spawn_floor, at + 60 } }, 10)
        MOD.enemy.mult_row(entry, 'SEAF', 'seaf_wave', 'SEAF wave cooldown (x)',
                           { { TYPES.spawn_floor, at + 64 }, { TYPES.spawn_floor, at + 68 }, { TYPES.spawn_floor, at + 72 },
                             { TYPES.spawn_floor, at + 76 } }, 10)
        return
    end
    local t = tables[TYPES.hivemind]
    if not t then return end
    local top = t.copies[1] + HEADER_BYTES
    local records = {}
    for _, off in pairs(t.index) do
        if peek4(top + off) == entry.enemy.spawning then records[#records + 1] = off end
    end
    table.sort(records)
    if #records == 0 then return end
    for _, s in ipairs(MOD.enemy.SPAWN) do
        if s[5] == 'flag' then
            local p = {}
            for n, off in ipairs(records) do p[n] = part(s[2] .. (n > 1 and ('_' .. n) or ''), TYPES.hivemind, off + s[4], 'flag', 1) end
            local r = add_row(entry, s[1], s[2], s[3], 'flag', p, 0, 1, 1, 1)
            r.lead = true
        else
            local fields = {}
            for _, off in ipairs(records) do
                for k = 0, s[5] == 'one' and 0 or 3 do fields[#fields + 1] = { TYPES.hivemind, off + s[4] + k * 4 } end
            end
            MOD.enemy.mult_row(entry, s[1], s[2], s[3], fields, s[5] == 'one' and 10 or 20, s[5] == 'inverse', s[6]).tip = s[7]
        end
    end
end

local function resolve(weapon)
    weapon.rows, weapon.by_id, weapon.aliases, weapon.backpack, weapon.mines, weapon.legacy = {}, {}, nil, nil, nil, nil
    weapon.swaps = nil
    weapon.grenade_swap = nil
    if weapon.slot == 'Throwables' then resolve_throwable(weapon); return end
    -- a support weapon you place (the C4 Pack): the backpack that shares its loadout package (its
    -- charges), the charge (health, throw distance) and its explosion
    if weapon.slot == 'Support' and KINDS[TYPES.package].placed(weapon.key) then
        local dt = tables[TYPES.deposit]
        for _, k in ipairs(KINDS[TYPES.package].kin(weapon.key)) do
            if dt and dt.index[k] then KINDS[TYPES.jumppack].backpack(weapon, k) end
        end
        if not KINDS[TYPES.seeking].silo_rows(weapon) then unit_rows(weapon, weapon.key, 'Charge', 'charge_') end
        resolve_throwable(weapon, true)
        return
    end
    if weapon.booster then MOD.boosters.resolve(weapon); return end
    if weapon.enemy then
        if weapon.slot == 'Spawning' then MOD.enemy.spawning_resolve(weapon)
        elseif weapon.enemy.faction then MOD.enemy.faction_resolve(weapon)
        elseif weapon.enemy.blasts then MOD.enemy.blasts_resolve(weapon)
        elseif weapon.enemy.gun then resolve_gun(weapon, weapon.key); MOD.enemy.gun_tidy(weapon)
        else MOD.enemy.resolve(weapon) end
        return
    end
    if weapon.passive then KINDS[TYPES.passive].resolve(weapon); return end
    if weapon.kits then MOD.kits.resolve(weapon); return end
    if weapon.player then KINDS[TYPES.avatar].resolve(weapon); return end
    if weapon.stratagem then resolve_stratagem(weapon); return end
    if weapon.attachment then
        KINDS[TYPES.items].mod_rows(weapon, 'Attachment', '', weapon.attachment.mods)
        local scope = weapon.attachment.scope   -- zoom: 1 = normal view, 2 = half the field of view; zeroing in m
        for k = 1, 3 do
            local z = scope and scope['236:' .. (112 + k * 4)]
            if z then
                add_row(weapon, 'Scope', 'zoom' .. k, 'Zoom level ' .. k .. ' (x)', 'f32', { { id = 'zoom' .. k, field = field_at(TYPES.deltas, z, 'f32', 1000) } }, 0.1, 100, 0.1, 1).tip =
                    { 'How close this zoom step looks: 1 is the normal view, 2 twice as close, 4 four times.' }
            end
        end
        for k = 1, 3 do
            local z = scope and scope['236:' .. (336 + k * 4)]
            if z then
                add_row(weapon, 'Scope', 'zero' .. k, 'Zeroing distance ' .. k .. ' (m)', 'f32', { { id = 'zero' .. k, field = field_at(TYPES.deltas, z, 'f32', 100000) } }, 0, 5000, 5, 50).tip =
                    { 'The range the sights are set for at this step (you switch steps in game). At that range the shot lands',
                      'on the crosshair; closer or farther it lands a bit high or low. Does not change the zoom.' }
            end
        end
        -- per zoom level: how quickly the view follows your aim (+316; 0.6 on most optics, the 10x sniper scopes'
        -- 0.8 / 1 / 1.25; high zoom with a high follow speed spins the view, issue #89)
        for k = 1, 3 do
            local z = scope and scope['236:' .. (312 + k * 4)]
            if z then
                local r = add_row(weapon, 'Scope', 'follow' .. k, 'Zoom level ' .. k .. ' follow speed', 'f32', { { id = 'follow' .. k, field = field_at(TYPES.deltas, z, 'f32', 1000) } }, 0.01, 10, 0.05, 0.25)
                r.tip = { 'How quickly the scoped view catches up when you move your aim at this zoom (0.6 on most optics).',
                          'Lower it if a high zoom spins the view.' }
            end
        end
        return
    end
    -- sentries and emplacements (listed as weapons on the Stratagems tab): their body, then their gun
    if weapon.slot == 'Stratagems' then
        local parts = {}
        for k, def in ipairs(weapon.sentry_defs or {}) do
            parts[k] = part(k == 1 and 'cooldown' or 'cooldown' .. k, def.kind, def.off + 104, 'f32', 100000)
        end
        if parts[1] then add_row(weapon, 'Stratagem', 'cooldown', 'Cooldown (s)', 'f32', parts, 0, 10000, 1, 10).show_first = true end
        if weapon.sentry_defs[1] then MOD.code.row(weapon, weapon.sentry_defs[1]) end
        if weapon.sentry_defs[1] then MOD.callin_rows(weapon, weapon.sentry_defs) end
        if weapon.sentry_defs[1] then
            MOD.extra.row(weapon, weapon.sentry_defs[1])
            MOD.extra.always_row(weapon, weapon.sentry_defs[1])
        end
        unit_rows(weapon, KINDS[TYPES.health].body(weapon.key) or weapon.key, weapon.name:find('^E/') and 'Emplacement' or 'Sentry', 'unit_')
        -- how long it stays once deployed (HellpodPayloadComponentData +4; SHODAN Offline Integration)
        local pt = tables[TYPES.payload]
        local pat = pt and pt.index[weapon.key]
        local life = pat and default_of(field_at(TYPES.payload, pat + 4, 'f32', 100000))
        if life and life > 0 and life <= 7200 then
            add_row(weapon, weapon.name:find('^E/') and 'Emplacement' or 'Sentry', 'unit_lifetime', 'Time deployed (s)', 'f32',
                    { part('unit_lifetime', TYPES.payload, pat + 4, 'f32', 100000) }, 1, 7200, 5, 30)
        end
    end
    -- Separate EXO mounted-arm durability and the Breakthrough physical shield.
    local exo, arm_name = weapon.name:match('^(EXO%-%d%d .+): (.+)$')
    if weapon.mounted and MOD.exo_mounted[exo] and (arm_name == 'Left arm' or arm_name == 'Right arm') then
        local ht = tables[TYPES.health]
        local at = ht and ht.index[weapon.key]
        if at then
            local hp = default_of(field_at(TYPES.health, at, 'u32', 10000000))
            local armor = default_of(field_at(TYPES.health, at + 280, 'u32', 100))
            if hp and hp > 0 and hp <= 1000000 and armor and armor <= 10 then
                -- the arm's own zone (+520) takes the hits: with health of its own (-1: none, the arm's) it leads,
                -- the arm's values follow (the Patriot's arm went at its zone's 800 with the arm's at 5000, in game)
                local health_parts = { part('arm_health', TYPES.health, at, 'u32', 10000000) }
                local armor_parts = { part('arm_armor', TYPES.health, at + 280, 'u32', 100) }
                local zone_hp = default_of(field_at(TYPES.health, at + 520 + 232, 'u32', 10000000))
                if zone_hp and zone_hp > 0 then
                    table.insert(health_parts, 1, part('arm_zone_health', TYPES.health, at + 520 + 232, 'u32', 10000000))
                    table.insert(armor_parts, 1, part('arm_zone_armor', TYPES.health, at + 520 + 216, 'u32', 100))
                end
                local hp_row = add_row(weapon, 'Arm durability', 'arm_health', 'Arm health', 'u32', health_parts, 1, 1000000, 50, 500)
                local armor_row = add_row(weapon, 'Arm durability', 'arm_armor', 'Arm armor', 'u32', armor_parts, 0, 10, 1, 1)
                hp_row.lead, armor_row.lead = true, true
                if exo == 'EXO-55 Breakthrough Exosuit' and arm_name == 'Left arm' then
                    local shield_arm_armor = default_of(field_at(TYPES.health, at + 520 + 216, 'u32', 100))
                    local plate_hp = default_of(field_at(TYPES.health, at + 520 + 552 + 232, 'u32', 10000000))
                    local plate_armor = default_of(field_at(TYPES.health, at + 520 + 552 + 216, 'u32', 100))
                    if shield_arm_armor and shield_arm_armor <= 10 and plate_hp and plate_hp > 0
                       and plate_hp <= 1000000 and plate_armor and plate_armor <= 10 then
                        add_row(weapon, 'Physical shield', 'shield_arm_armor', 'Shield arm zone armor', 'u32',
                                { part('shield_arm_armor', TYPES.health, at + 520 + 216, 'u32', 100) }, 0, 10, 1, 1)
                        add_row(weapon, 'Physical shield', 'shield_plate_health', 'Shield plate health', 'u32',
                                { part('shield_plate_health', TYPES.health, at + 520 + 552 + 232, 'u32', 10000000) }, 1, 1000000, 250, 1000)
                        add_row(weapon, 'Physical shield', 'shield_plate_armor', 'Shield plate armor', 'u32',
                                { part('shield_plate_armor', TYPES.health, at + 520 + 552 + 216, 'u32', 100) }, 0, 10, 1, 1)
                    end
                    -- the bash is an ability, no record of the arm names its damage: row 251 (unnamed), the only one with the wiki's 9 values
                    MOD.melee_rows(weapon, 251, 'Shield bash', 'bash_')
                end
            end
        end
    end
    resolve_gun(weapon, weapon.key)
    if not weapon.mounted and (weapon.slot == 'Primary' or weapon.slot == 'Secondary') then
        MOD.slot.row(weapon)
        if weapon.slot == 'Primary' then MOD.holster.row(weapon) end
    end
end

-- The shots a weapon fires besides its projectile, read as the game had them: a second ammo type
-- (rounds +68 when not +64's: the SG-20 Halt's stun rounds, toggled in game; named for a stun it
-- applies) and a patterned magazine's other rounds (magazine +0 type 1, +4: 32 projectiles fired in
-- turn: the MG-43's and Bullet Storm's tracers, the machine gun sentries'). { id, prow, name, prefix,
-- field (the second ammo type's) or slots (the pattern's fields, every round's) }, nil when none.
KINDS[T_ROUNDS].extra = function(rounds, magazine, projectile)
    local list = {}
    local function prow_of(id) return id and id > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[id] end
    local f = rounds and field_at(T_ROUNDS, rounds + 68, 'u32', 100000)
    local alt = f and default_of(f)
    if prow_of(alt) and alt ~= projectile then
        local did = read_field(field_at(T_PROJECTILE, prow_of(alt) + 60, 'u32', 100000))
        local drow = did and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
        local stun = nil
        for i = 0, 3 do
            local kind = drow and read_field(field_at(T_DAMAGE, drow + 44 + i * 8, 'u32', 100000))
            stun = stun or (kind and KINDS[T_STATUS].stuns[kind])
        end
        list[#list + 1] = { id = alt, prow = prow_of(alt), name = stun and 'Stun rounds' or 'Second ammo', prefix = 'a2_', field = f }
    end
    if magazine and default_of(field_at(T_MAGAZINE, magazine, 'u32', 100000)) == 1 then
        local slots, other = {}, nil
        for k = 0, 31 do
            local slot = field_at(T_MAGAZINE, magazine + 4 + k * 4, 'u32', 100000)
            local id = default_of(slot)
            if id and id > 0 then
                slots[#slots + 1] = slot
                if id ~= projectile then other = other or id end
            end
        end
        if prow_of(other) then
            list[#list + 1] = { id = other, prow = prow_of(other), name = 'Tracer rounds', prefix = 't_', slots = slots }
        elseif #slots > 0 then
            list[#list + 1] = { slots = slots }   -- every round its projectile: only the swap writes them
        end
    end
    return #list > 0 and list or nil
end

-- Projectile swap (the last row of a weapon that fires projectiles): one row writing every field the
-- weapon's projectile comes from (its rounds record, ammo type, fire mode, charge stages) with another
-- weapon's projectile. The stat rows above stay the weapon's own projectile's. Choices:
-- KINDS[T_PROJECTILE].choices, every listed weapon's own projectiles by name (built after resolving).
-- Weapons with a second firing mode (the "programmable ammo" weapon function: the Autocannon's flak,
-- the Recoilless Rifle's HE) fire the fire mode's +576 in it: a second swap row for that one. Weapons without one,
-- with a function free (weapon +184 left, else +188 right): the same row, its choice also sets that function (8,
-- tested in game on the S-11 and, right, the Railgun; in game, hold Reload to switch). `extra`
-- (KINDS[T_ROUNDS].extra): a patterned magazine's rounds take the swapped projectile too (every one of
-- them), a second ammo type has its own row.
KINDS[T_PROJECTILE].swap_row = function(weapon, sources, shots, fire, extra)
    if #sources == 0 or not (weapon.projectile or shots) then return end
    local main = nil
    for _, src in ipairs(sources) do
        if shots and src.id == 'proj_c' .. shots[#shots].last then main = main or src end
        if not shots and src.own == weapon.projectile then main = main or src end
    end
    main = main or sources[1]
    local parts = { { id = main.id, field = main.field } }
    for _, src in ipairs(sources) do
        if src ~= main then parts[#parts + 1] = { id = src.id, field = src.field } end
    end
    local ammo = nil
    for _, shot in ipairs(extra or {}) do
        for k, slot in ipairs(shot.slots or {}) do parts[#parts + 1] = { id = 'proj_mag' .. k, field = slot } end
        if shot.field then ammo = shot end
    end
    local function swap(id, label, row_parts)
        local row = add_row(weapon, 'Projectile swap', id, label, 'u32', row_parts, 1, 100000, 1, 10)
        row.choice = true
        -- offline: Install loads the source weapon's package (MOD.donors), for a limited number of weapons
        row.tip = { "The shot's trail and other effects belong to the chosen weapon.",
                    'Install loads up to 6 such weapons into every mission, so nobody has to bring them. A support weapon brings its own.',
                    'Past that, the trail needs someone in the mission to bring that weapon.',
                    'Hits and explosions show either way.' }
        weapon.swaps = weapon.swaps or {}
        weapon.swaps[#weapon.swaps + 1] = row
        row.note = function(others)
            local spec, now, own = KINDS[T_PROJECTILE], read_field(row_parts[1].field), default_of(row_parts[1].field)
            local shot = spec.by_id and spec.by_id[now]
            local text = now == 0 and 'none. - / + : add one, hold Reload in game to switch'
                         or now == own and "its own. - / + : fire another weapon's"
                         or ('fires: ' .. (shot and shot.label or ('projectile ' .. tostring(now))) .. '. The rows above stay its own')
            if #others > 0 then text = text .. '; ammo type shared with ' .. table.concat(others, ', ', 1, math.min(2, #others)) end
            return text
        end
        return row
    end
    local row = swap('projectile', 'Projectile fired (id)', parts)
    local alt = fire and field_at(T_FIRE, fire + 576, 'u32', 100000)
    local second = alt and default_of(alt)
    if second and second > 0 then
        row = swap('projectile_2', 'Second mode fires (id)', { { id = 'projectile_2', field = alt } })
    else
        second = nil
        local wrow = alt and tables[T_WEAPON].index[weapon.key]
        local left = wrow and field_at(T_WEAPON, wrow + 184, 'u32', 100)
        local right = wrow and field_at(T_WEAPON, wrow + 188, 'u32', 100)
        local free = left and (default_of(left) == 0 and left or default_of(right) == 0 and right)
        if left and not weapon.name:find('(', 1, true)   -- (no mounted guns, underbarrels)
           and (weapon.slot == 'Primary' or weapon.slot == 'Secondary' or weapon.slot == 'Support') then
            if free then alt.switch = free
            else   -- both taken: the player picks which goes (the underbarrel's and the fire rate's last, first)
                local l, r = default_of(left), default_of(right)
                local pick = field_at(0, 'second_toggle:' .. weapon.hash, 'virtual', 2)
                pick.default = (l == 11 or r == 2) and 2 or 1
                pick.toggle = { left = left, right = right, pick = pick, second = alt }
                alt.toggle = pick.toggle
                add_row(weapon, 'Projectile swap', 'second_toggle', 'Second ammo replaces (1 or 2)', 'u32',
                        { { id = 'second_toggle', field = pick } }, 1, 2, 1, 1).note = function()
                    local gone = read_field(pick) == 1 and l or r
                    return gone == 2 and 'the rate of fire switch' or gone == 3 and 'the fire mode switch' or 'the underbarrel switch'
                end
            end
            row = swap('projectile_2', 'Second ammo (id)', { { id = 'projectile_2', field = alt } })
        end
    end
    if ammo then
        local id = 'projectile_' .. ammo.prefix:sub(1, -2)
        local row_parts = { { id = id, field = ammo.field } }
        if ammo.delta then row_parts[2] = { id = id .. '_ammo', field = ammo.delta } end
        row = swap(id, ammo.name .. ' fire (id)', row_parts)
    end
    -- under the last row: what a swap changes and what it keeps (drawn below it, `after_h` units)
    row.after = { "Swapping makes the shot the chosen weapon's, your edits to it included: damage,",
                  'armor penetration, forces, velocity, drag, gravity, pellets and explosions. Kept: this',
                  "weapon's fire rate, ammo, handling and heat. To tune the shot, edit the chosen weapon." }
    row.after_h = #row.after * 16 + 6
    weapon.own_shots = {}
    for _, shot in ipairs(shots or { { id = weapon.projectile } }) do
        weapon.own_shots[#weapon.own_shots + 1] = { id = shot.id, key = weapon.key,
            label = shots and (weapon.name .. ' (' .. shot.name:lower() .. ')') or weapon.name }
    end
    if second then weapon.own_shots[#weapon.own_shots + 1] = { id = second, key = weapon.key, label = weapon.name .. ' (second mode)' } end
    if ammo then
        weapon.own_shots[#weapon.own_shots + 1] = { id = ammo.id, key = weapon.key, label = weapon.name .. ' (' .. ammo.name:lower() .. ')' }
    end
end

-- The choices: every own projectile once (the first weapon's name, by name), in name order.
KINDS[T_PROJECTILE].list_choices = function()
    local list, by = {}, {}
    for _, w in ipairs(weapons) do
        for _, shot in ipairs(w.own_shots or {}) do
            if not by[shot.id] then by[shot.id] = shot; list[#list + 1] = shot end
        end
    end
    table.sort(list, function(a, b) return a.label:lower() < b.label:lower() end)
    KINDS[T_PROJECTILE].choices, KINDS[T_PROJECTILE].by_id = list, by
end

-- The projectile `n` choices on from `id` (from either end when `id` is not one).
KINDS[T_PROJECTILE].step = function(id, n)
    local list, at = KINDS[T_PROJECTILE].choices or {}, nil
    for k, shot in ipairs(list) do if shot.id == id then at = k end end
    if #list == 0 then return id end
    at = at or (n > 0 and 0 or #list + 1)
    return list[math.max(1, math.min(#list, at + n))].id
end

-- Records (CarbonAnime, PR #58): the projectile, explosion and status records themselves, by id. Their names: a
-- projectile's the game's name of its round (MOD.round_names), else the first weapon that fires it; an explosion's
-- the first weapon that sets it off, else the round that does; a status's its own (Burning, Gas, stuns).
MOD.records = { pages = {}, list = nil, cache = nil, KINDS = { T_PROJECTILE, T_EXPLOSION, T_STATUS },
                WORD = { [T_PROJECTILE] = 'Projectile', [T_EXPLOSION] = 'Explosion', [T_STATUS] = 'Status' },
                PREFIX = { [T_PROJECTILE] = 'F1', [T_EXPLOSION] = 'F2', [T_STATUS] = 'F3' } }
-- the fuse rows' notes (PR #80 by CarbonAnime): a blast proximity works only with the blast angle (+136) at 360
-- (tested in game: the crossbow at 80 and 6 m does not burst in flight, the GL-21 at 360 and 6 m does), and a radius
-- smaller than one step of the round is stepped over
MOD.records.NOTES = {
    angle = '360 fires from any side; with a blast proximity above 0 the round becomes a proximity fuse (measured: 360 and 6 m on the crossbow).',
    weapon_angle = '360 with a proximity above 0: a proximity fuse, off from any side.' }
-- the (?) tips of the fuse rows: what they do (RL-77 Flak 2 m and 0.2 s, the P-34 Breacher's sticky round 1 s)
MOD.records.TIPS = {
    impact = { 'The explosion the round sets off when it hits something. 0: no explosion.' },
    expiry = { 'The explosion the round sets off when its life time runs out before it hits anything. 0: no explosion.' },
    proximity = { 'The round goes off when it passes this close to an enemy, without hitting it. 0: off (the RL-77 uses 2 m).',
                  'Only works with the blast angle at 360, and the distance has to be larger than one step of the round:',
                  'keep it above about speed / frame rate.' },
    delay = { 'How long the round waits after the hit (or after the blast proximity trips) before it goes off.',
              '0: at once. The RL-77 waits 0.2 s, the P-34 Breacher (it sticks and burns first) 1 s.' },
    bounces = { 'How many times the round can bounce off a surface. 0: it never bounces back at you.' },
    bounce_angle = { 'The round only bounces when it hits further than this from head on (0 = head on, 90 = grazing).',
                     'Grenade launcher rounds use 80, most rounds 83.' },
    bounce_speed = { 'The round only bounces when it hits faster than this. Grenade launcher rounds use 20 m/s, most rounds 60 m/s.' } }
function MOD.records.ids(kind)
    local ids = {}
    for id in pairs(tables[kind] and tables[kind].index or {}) do
        if type(id) == 'number' and id > 0 then ids[#ids + 1] = id end
    end
    table.sort(ids)
    return ids
end
-- Who uses each record: shots (projectile id -> weapon names), blasts (explosion id -> weapon names), from the
-- weapons' rows (the record a row's field is in) and own shots; rounds (explosion id -> the name of the first named
-- round that sets it off). Built once per resolve.
function MOD.records.users()
    if MOD.records.cache then return MOD.records.cache end
    local shots, blasts, rounds = {}, {}, {}
    local function add(map, id, name)
        if not id or id <= 0 then return end
        local list = map[id] or {}
        map[id] = list
        for _, n in ipairs(list) do if n == name then return end end
        list[#list + 1] = name
    end
    local function locate(kind)
        local spots, stride = {}, KINDS[kind].stride
        for _, id in ipairs(MOD.records.ids(kind)) do spots[#spots + 1] = { at = tables[kind].index[id], id = id } end
        table.sort(spots, function(a, b) return a.at < b.at end)
        return function(offset)
            local lo, hi = 1, #spots
            while lo <= hi do
                local mid = math.floor((lo + hi) / 2)
                local spot = spots[mid]
                if offset < spot.at then hi = mid - 1
                elseif offset >= spot.at + stride then lo = mid + 1
                else return spot.id end
            end
        end
    end
    local shot_at, blast_at = locate(T_PROJECTILE), locate(T_EXPLOSION)
    for _, w in ipairs(weapons) do
        if #w.rows > 0 and not w.name:match('^%(') then   -- not the '(Not Used)' dummies
            for _, shot in ipairs(w.own_shots or {}) do add(shots, shot.id, w.name) end
            for _, row in ipairs(w.rows) do
                if row.choice == 'shrapnel' then add(shots, default_of(row.parts[1].field), w.name) end   -- (pieces, shells, bombs)
                for _, q in ipairs(row.parts) do
                    if q.field.kind == T_PROJECTILE then add(shots, shot_at(q.field.offset), w.name)
                    elseif q.field.kind == T_EXPLOSION then add(blasts, blast_at(q.field.offset), w.name) end
                end
            end
        end
    end
    local fired = {}   -- explosion id -> the weapons whose own shots set it off
    for _, id in ipairs(MOD.records.ids(T_PROJECTILE)) do
        local name, at = MOD.round_names and MOD.round_names[id], tables[T_PROJECTILE].index[id]
        for _, off in ipairs({ 144, 156 }) do
            local f = field_at(T_PROJECTILE, at + off, 'u32', 100000)
            local x = read_field(f)
            if name and x and x > 0 and not rounds[x] then rounds[x] = name end
            for _, n in ipairs(shots[id] or {}) do add(fired, default_of(f), n) end
        end
    end
    MOD.records.cache = { shots = shots, blasts = blasts, rounds = rounds, fired = fired }
    return MOD.records.cache
end
-- A record's name (English), or nil.
function MOD.records.name(kind, id)
    local u = MOD.records.users()
    if kind == T_PROJECTILE then return MOD.round_names and MOD.round_names[id] or (u.shots[id] or {})[1]
    elseif kind == T_EXPLOSION then return (u.blasts[id] or {})[1] or u.rounds[id] end
    if state.lang and state.lang() == 'zh-Hans' and MOD.status.by[id] then return MOD.status.by[id].name end
    return KINDS[T_STATUS].names[id] or KINDS[T_STATUS].stuns[id]
end
-- A hovered id row's lines: the id now in it and every page that uses it (nil on other rows and at 0).
function MOD.records.source(row)
    local kind = (row.choice == true or row.choice == 'shrapnel') and T_PROJECTILE or row.choice == 'explosion' and T_EXPLOSION
    local id = kind and read_field(row.parts[1].field)
    if not id or id <= 0 then return nil end
    local u, names, seen = MOD.records.users(), {}, {}
    for _, list in ipairs(kind == T_PROJECTILE and { u.shots[id] or {} } or { u.blasts[id] or {}, u.fired[id] or {} }) do
        for _, n in ipairs(list) do
            if not seen[n] then seen[n] = true; names[#names + 1] = state.tr and state.tr(n) or n end
        end
    end
    local lines = { MOD.records.label(kind, id) }
    if #names == 0 then lines[2] = kind == T_EXPLOSION and u.rounds[id] and ((state.tr and state.tr(u.rounds[id])) or u.rounds[id])
                                   or 'No page in this editor uses this id.' end
    for k = 1, math.min(#names, 12), 3 do   -- three names a line
        lines[#lines + 1] = (k == 1 and ((state.tr and state.tr('Used by:') or 'Used by:') .. ' ') or '') .. table.concat(names, ', ', k, math.min(k + 2, #names, 12))
    end
    if #names > 12 then lines[#lines + 1] = '+' .. (#names - 12) end
    return lines
end
-- A choice's label in a note: '#12 · 10g Sabot' (the name in the panel's language), 'none (no explosion)'.
function MOD.records.label(kind, id)
    local what = kind == T_EXPLOSION and 'explosion' or 'projectile'
    if not id or id <= 0 then return 'none (no ' .. what .. ')' end
    if not (tables[kind] and tables[kind].index[id]) then return what .. ' ' .. id .. ' (not in this game build)' end
    local name = MOD.records.name(kind, id)
    return '#' .. id .. (name and (' · ' .. (state.tr and state.tr(name) or name)) or '')
end
-- The id `n` on from `id` among none (0) and every record of the kind (from either end when `id` is not one).
function MOD.records.step(kind, id, n)
    local list = MOD.records.ids(kind)
    table.insert(list, 1, 0)
    local at = nil
    for k, x in ipairs(list) do if x == id then at = k end end
    at = at or (n > 0 and 0 or #list + 1)
    return list[math.max(1, math.min(#list, at + n))]
end
-- A weapon page's explosion id sections ('Projectile explosion id', ...) last, below its projectile swap.
function MOD.records.ids_last(weapon)
    local rows, last = {}, {}
    for _, row in ipairs(weapon.rows) do
        local list = row.section:find(' explosion id$') and last or rows
        list[#list + 1] = row
    end
    for _, row in ipairs(last) do rows[#rows + 1] = row end
    weapon.rows = rows
end
-- An explosion's shrapnel rows (explosion row `xrow`, ids `pre` ..): the projectile every piece is, then how many.
function MOD.records.shrapnel_rows(entry, section, pre, xrow)
    local piece = add_row(entry, section, pre .. '_projectile', 'Shrapnel projectile (id)', 'u32',
                          { part(pre .. '_projectile', T_EXPLOSION, xrow + 84, 'u32', 100000) }, 0, 100000, 1, 10)
    piece.choice = 'shrapnel'
    piece.note = function()
        local id = read_field(piece.parts[1].field)
        return (id or 0) > 0 and ('each piece is ' .. MOD.records.label(T_PROJECTILE, id)) or 'no shrapnel'
    end
    add_row(entry, section, pre .. '_count', 'Shrapnel pieces', 'u32', { part(pre .. '_count', T_EXPLOSION, xrow + 80, 'u32', 10000) },
            0, 500, 1, 5)
end
-- A record page's rows (page.kind, page.id).
function MOD.records.rows(page)
    local kind, at = page.kind, tables[page.kind] and tables[page.kind].index[page.id]
    page.rows, page.by_id = {}, {}
    if not at then return end
    local function num(section, id, label, off, storage, max, small, big)
        return add_row(page, section, id, label, storage, { part(id, kind, at + off, storage, 100000) }, 0, max, small, big)
    end
    local function hurt(off, section, what, count)
        local d = read_field(field_at(kind, at + off, 'u32', 100000))
        local drow = d and d > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[d]
        if not drow then return end
        damage_rows(page, section, '', drow, what, count)
        if count == nil then status_rows(page, section, '', drow, what == 'Explosion' and 'blast' or 'hit') end
    end
    if kind == T_PROJECTILE then
        for _, r in ipairs({ { 'calibre', 'Calibre (mm)', 24, 'f32', 1000, 0.1, 1 }, { 'pellets', 'Projectiles per shot', 28, 'u32', 200, 1, 5 },
                             { 'velocity', 'Velocity (m/s)', 32, 'f32', 100000, 10, 100 }, { 'mass', 'Mass (kg)', 36, 'f32', 10000, 0.1, 1 },
                             { 'drag', 'Drag factor', 40, 'f32', 100, 0.05, 0.5 }, { 'gravity', 'Gravity factor', 44, 'f32', 100, 0.05, 0.5 },
                             { 'lifetime', 'Lifetime (s)', 52, 'f32', 1000, 0.1, 1 },
                             { 'pen_slowdown', 'Penetration slowdown', 64, 'f32', 100, 0.05, 0.25 } }) do
            num('Projectile', r[1], r[2], r[3], r[4], r[5], r[6], r[7])
        end
        -- +244 switches (issue #102): bit 0x01 inherit_velocity, 0x20 explosions_inherit_velocity. Both on (the shell's
        -- explosion, its shrapnel) send the shrapnel forward with the shell's speed (the old Eruptor)
        for _, r in ipairs({ { 'inherit_velocity', 'Inherits velocity', 1,
                               'Adds the speed of what fired it: the shooter, or for shrapnel the shell it burst from.' },
                             { 'explosion_inherits', 'Explosion inherits velocity', 32,
                               'Its explosion keeps its speed, so shrapnel with Inherits velocity on flies on forward.' } }) do
            add_row(page, 'Projectile', r[1], r[2], 'flag', { { id = r[1], field = field_at(kind, at + 244, 'flag', 1, r[3]) } },
                    0, 1, 1, 1).tip = { r[4] }
        end
        hurt(60, 'Damage')
        local impact = add_row(page, 'Explosion id', 'impact_explosion', 'Impact explosion (id)', 'u32',
                               { part('impact_explosion', kind, at + 144, 'u32', 100000) }, 0, 100000, 1, 10)
        impact.choice = 'explosion'
        impact.note = function()
            return 'sets off: ' .. MOD.records.label(T_EXPLOSION, read_field(impact.parts[1].field))
        end
        impact.tip = MOD.records.TIPS.impact
        num('Explosion id', 'fuse_proximity', 'Blast proximity (m)', 148, 'f32', 200, 0.1, 1).tip = MOD.records.TIPS.proximity
        num('Explosion id', 'fuse_delay', 'Blast delay (s)', 152, 'f32', 30, 0.05, 0.5).tip = MOD.records.TIPS.delay
        local expiry = add_row(page, 'Explosion id', 'expiry_explosion', 'Expiry explosion (id)', 'u32',
                               { part('expiry_explosion', kind, at + 156, 'u32', 100000) }, 0, 100000, 1, 10)
        expiry.choice = 'explosion'
        expiry.tip = MOD.records.TIPS.expiry
        num('Explosion id', 'arming', 'Arming distance (m)', 160, 'f32', 200, 0.1, 1)
        num('Explosion id', 'blast_angle', 'Blast angle (deg)', 136, 'f32', 360, 1, 10).note = MOD.records.NOTES.angle
        -- ricochets (issue #116): shalzuth's max_ricochets/threshold angle/speed, 4 bytes later in the game's data
        -- (an extra field before decal_size); defaults 1, 83 deg, 60 m/s, grenade launcher rounds 1, 80, 20
        num('Bounce', 'max_ricochets', 'Max bounces', 180, 'u32', 100, 1, 1).tip = MOD.records.TIPS.bounces
        num('Bounce', 'ricochet_angle', 'Bounce angle (deg)', 184, 'f32', 360, 1, 10).tip = MOD.records.TIPS.bounce_angle
        num('Bounce', 'ricochet_speed', 'Bounce speed (m/s)', 188, 'f32', 100000, 1, 10).tip = MOD.records.TIPS.bounce_speed
    elseif kind == T_EXPLOSION then
        hurt(4, 'Explosion', 'Explosion')
        for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                             { 'shockwave', 'Shockwave radius (m)', 24 } }) do
            num('Radius', r[1], r[2], r[3], 'f32', 200, 0.1, 1)
        end
        num('Shape', 'cone', 'Cone angle (deg)', 28, 'f32', 360, 1, 10)
        num('Shape', 'shake', 'Camera shake radius (m)', 32, 'f32', 200, 0.1, 1)
        MOD.records.shrapnel_rows(page, 'Shrapnel', 'shrapnel', at)
    else
        local name = MOD.records.name(kind, page.id) or 'Status'
        hurt(44, name, name, 6)   -- no forces: a status has none
        num(name, 'duration', name .. ' duration (s)', 40, 'f32', 600, 0.5, 5)
    end
end
-- An unnamed record still needs something readable beside its number. Use the loaded
-- values as a description, without claiming to know which weapon or effect it belongs to.
function MOD.records.unnamed(page)
    local function value(id)
        local part = page.by_id[id]
        local v = part and default_of(part.field)
        return v and v == v and math.abs(v) < math.huge and v or nil
    end
    if page.kind == T_PROJECTILE then
        local calibre, damage, durable = value('calibre'), value('damage'), value('durable')
        if calibre and damage and durable then
            return string.format('Unnamed: %gmm; %g/%g damage', calibre, damage, durable)
        end
        return 'Unnamed projectile'
    elseif page.kind == T_EXPLOSION then
        local outer = value('outer')
        if outer then return string.format('Unnamed: %gm blast', outer) end
        return 'Unnamed explosion'
    end
    local duration = value('duration')
    return duration and string.format('Unnamed: %gs effect', duration) or 'Unnamed status effect'
end

-- A record page's title and note: 'Projectile #12 · 10g Sabot', 'Fired by: ...'.
function MOD.records.title(page)
    local name = MOD.records.name(page.kind, page.id)
    if not name and state.lang and state.lang() == 'zh-Hans' then name = MOD.records.unnamed(page) end
    page.name = MOD.records.WORD[page.kind] .. ' #' .. page.id .. (name and (' · ' .. name) or '')
    local u = MOD.records.users()
    local users = page.kind == T_PROJECTILE and u.shots[page.id] or page.kind == T_EXPLOSION and u.blasts[page.id]
    if page.kind == T_STATUS then page.note = ''
    elseif not users then page.note = 'Not used by any weapon or stratagem in this list.'
    else
        page.note = (page.kind == T_PROJECTILE and 'Fired by: ' or 'Set off by: ') .. table.concat(users, ', ', 1, math.min(3, #users)) ..
                    (#users > 3 and (', +' .. (#users - 3)) or '')
    end
end
-- The page of a record (built on first use; hash: 'F1' projectile / 'F2' explosion / 'F3' status + 14 hex digits).
function MOD.records.page(kind, id)
    local hash = string.format('%s%014X', MOD.records.PREFIX[kind], id)
    local page = MOD.records.pages[hash]
    if page then return page end
    if not (tables[kind] and tables[kind].index[id]) then return nil end
    page = { slot = 'Records', hash = hash, kind = kind, id = id, record = true }
    MOD.records.rows(page)
    MOD.records.title(page)
    MOD.records.pages[hash] = page
    return page
end
function MOD.records.find(hash)
    if type(hash) ~= 'string' or #hash ~= 16 then return nil end
    local mark, digits = hash:match('^(F[123])(%x+)$')
    if not mark then return nil end
    for kind, prefix in pairs(MOD.records.PREFIX) do
        if prefix == mark then return MOD.records.page(kind, tonumber(digits, 16)) end
    end
end
-- Every record page, projectiles, explosions then statuses, by id (the Records tab; built when first opened).
function MOD.records.all()
    if MOD.records.list then return MOD.records.list end
    local list = {}
    for _, kind in ipairs(MOD.records.KINDS) do
        for _, id in ipairs(MOD.records.ids(kind)) do
            local page = MOD.records.page(kind, id)
            if page and #page.rows > 0 then list[#list + 1] = page end
        end
    end
    MOD.records.list = list
    return list
end
-- After every resolve: who uses what again, and the pages built so far read again (a rescan moves the tables).
function MOD.records.refresh()
    MOD.records.cache, MOD.records.list = nil, nil
    for _, page in pairs(MOD.records.pages) do
        MOD.records.rows(page)
        MOD.records.title(page)
    end
end
-- a record page's values saved in config.txt or a preset: its page, built when first named
setmetatable(by_hash, { __index = function(_, hash) return MOD.records.find(hash) end })

-- ProjectileWeaponComponent +40 is a full 64-bit entity reference. Keep both
-- halves together through read/write/reset/presets; a Lua number cannot hold the hash.
-- Use the grenade entity and native release/activation lifecycle. Special grenade
-- behaviors still require gameplay validation; reference writes alone are insufficient.
KINDS[TYPES.throwable].grenade_row = function(weapon, fire)
    local spec = KINDS[TYPES.throwable]
    -- (offline: no row; a swapped grenade needs its assets loaded by the running game)
    if MOD.offline or not fire or not spec.grenade_hosts[weapon.hash] then return end
    local f = field_at(T_FIRE, fire + 40, 'grenade', #spec.grenade_hashes)
    if default_of(f) == nil then
        log('grenade swap: unknown original entity on ' .. weapon.name)
        return
    end
    spec.fields = spec.fields or {}
    spec.fields[f.key] = f
    local row = add_row(weapon, 'Grenade swap', 'grenade', 'Grenade fired (choice)', 'u32',
                        { { id = 'grenade', field = f } }, 0, #spec.grenade_hashes, 1, 10)
    row.choice = 'grenade'
    weapon.grenade_swap = row
    row.note = function()
        local id = f.pending_value or read_field(f)
        local shot = spec.by_id[id]
        return (f.pending_value and 'loading: ' or 'fires: ') .. (shot and shot.label or 'normal projectile')
    end
    row.after = { '0 = normal projectile; - / + selects a throwable grenade by name above.',
                  'Grenade selection takes priority over Projectile swap. Fire rate, ammo and handling stay.',
                  'Edit the grenade on Throwables to tune it. Assets load before selection applies.',
                  'Throwable launching is supported in solo missions only.' }
    row.after_h = #row.after * 16 + 6
end

-- Resolves weapons from `next` on until the deadline; true once all are done.
local function resolve_some(progress, deadline)
    if progress.next == 1 then
        for _, f in pairs(fields) do f.users = {} end
        KINDS[TYPES.custom].cache = {}
        KINDS[TYPES.throwable].prepare_grenades()
    end
    while progress.next <= #weapons do
        resolve(weapons[progress.next])
        MOD.records.ids_last(weapons[progress.next])
        progress.next = progress.next + 1
        if api.now() >= deadline then break end
    end
    if progress.next <= #weapons then return false end
    KINDS[T_PROJECTILE].list_choices()
    MOD.records.refresh()
    local usable, strats = 0, 0
    state.attachments, state.throwables, state.passives, state.vehicles = 0, 0, 0, 0
    for _, weapon in ipairs(weapons) do
        if #weapon.rows > 0 then
            if weapon.stratagem and weapon.stratagem.vehicle then state.vehicles = state.vehicles + 1
            elseif weapon.stratagem or weapon.mounted then strats = strats + (weapon.mounted and 0 or 1)
            elseif weapon.attachment then state.attachments = (state.attachments or 0) + 1
            elseif weapon.slot == 'Throwables' then state.throwables = (state.throwables or 0) + 1
            elseif weapon.passive then state.passives = state.passives + 1
            else usable = usable + 1 end
        end
    end
    state.weapons, state.stratagems = usable, strats
    return true
end

-- Other weapons whose values change along with this row.
local function shared_with(weapon, row)
    local names, seen = {}, { [weapon] = true }
    for _, p in ipairs(row.parts) do
        for _, other in ipairs(p.field.users) do
            if not seen[other] and (weapon.record or not other.record) then seen[other] = true; names[#names + 1] = other.name end
        end
    end
    return names
end

-- A time row (row.span) holds a rate; it shows and takes span / rate seconds.
local function as_time(span, rate)
    if span == nil or rate == nil or rate <= 0 then return nil end
    return span / rate
end

-- A row's value (the mean of its parts); default = true: the game's own value instead.
local function row_value(row, default)
    local get = default and default_of or read_field
    if row.choice == 'grenade' and not default and row.parts[1].field.pending_value ~= nil then
        return row.parts[1].field.pending_value
    end
    if row.choice == 'holster' then return MOD.holster.value(row, default) end
    -- the stratagem list's own row, not an average with a hidden same-named one (the Rocket Sentry's: 150 s against 45 s)
    if row.show_first then return get(row.parts[1].field) end
    if row.choice == 'pod_twin' then return MOD.pod.value(row, default) end
    if row.drain then   -- shortcut: at a drain of 0 it shows the last time, though the part then never runs out
        local rate = get(row.drain.parts[1].field)
        if rate and rate > 0 then row.scale = 1 / rate end
    end
    if row.choice or row.lead then   -- lead: the others scale with it
        local v = get(row.parts[1].field)
        return (v and row.scale) and v * row.scale + 0 or v
    end
    if row.span then
        local rate = get(row.parts[1].field)
        if row.never and rate == 0 then return 0 end
        return as_time((default and row.span_default or row.span)(), rate and rate + (row.rate_plus or 0))
    end
    local sum = 0
    for _, p in ipairs(row.parts) do
        local v = get(p.field)
        if v == nil then return nil end
        sum = sum + v
    end
    if row.zero and sum == 0 then return row.zero end   -- 0 stands for that (a reload played as animated)
    return sum / #row.parts * (row.scale or 1) + 0   -- (+ 0: no -0 shown)
end

-- ---------------------------------------------------------------- config
-- One line per changed value: <weapon hash> <stat> <value>   # weapon name
-- plus `hotkey <key>`. Written after every change, read once at start.
local overrides = {}    -- list of { hash, id, value }
local hotkey_name = 'F8'
local config_dirty_at = nil
-- The Settings page's choices, saved in config.txt with the changes. changes: apply the changes
-- (off: every value is the game's, the changes are kept); block_input: the game gets no keyboard /
-- mouse input while the panel is open; size: panel height, % of the screen's; side: 'left' / 'right';
-- opacity: background, %; last: the tab and page each editor was left on (reopened there; 'stat' / 'enemy'),
-- enemy_last: the editor left in; lang: the panel's language, 'en'
-- or the id of a translation: fixed by the build (a language's release, MOD.lang), not a choice; offline (every
-- language built in) a choice, saved as 'lang'.
local settings = { changes = true, block_input = true, size = 80, side = 'right', opacity = 90,
                   arc_mp = true, updates = 'ask', update_channel = 'releases', stacks = {}, own_off = {}, armor_passives = {}, hidden = {}, lang = MOD.lang or MOD.offline and rawget(_G, 'SHODAN_OFFLINE_LANG') or 'en',
                   last = { stat = {}, enemy = {} }, enemy_last = false,
                   GITHUB = 'https://github.com/SHODAN-HORAI/SHODAN-Stat-Editor',
                   RANGE = { size = { 50, 100 }, opacity = { 10, 100 } } }

-- Translations (MOD.langs, built from lang/*.json): the panel's text by its English text, so every
-- branch still runs on English and config.txt / presets stay the same in every language. A lookup:
-- exact (and lower, the lowercased names sentences carry), '* ' + exact (a changed item), whole-sentence
-- patterns (numbers and names built at run time; %1-%4 are translated again, %L1 a ', ' list of them),
-- then prefix and suffix.
-- Each text is looked up once per language (the panel redraws often).
do
    local LANG = {}
    -- capitals in UTF-8: ASCII, Latin-1 accents (à-þ but ÷) and Cyrillic (а-я, ё); Chinese has none
    local function caps(s)
        return (s:upper():gsub('\195([\160-\190])', function(c) if c ~= '\183' then return '\195' .. string.char(c:byte() - 32) end end)
                :gsub('\208([\176-\191])', function(c) return '\208' .. string.char(c:byte() - 32) end)
                :gsub('\209([\128-\143])', function(c) return '\208' .. string.char(c:byte() + 32) end)
                :gsub('\209\145', '\208\129'))
    end
    assert(caps('ação ёж efeito') == 'AÇÃO ЁЖ EFEITO')
    for _, l in ipairs(MOD.langs or {}) do   -- and by the upper / lower case English ('DAMAGE' -> capitals too, sentences)
        LANG[l.id], l.upper = l, {}
        for e, t in pairs(l.exact) do
            l.upper[e:upper()] = l.upper[e:upper()] or caps(t)
            l.lower[e:lower()] = l.lower[e:lower()] or t
        end
    end
    settings.LANGS = LANG
    local tr_cache, tr_count = {}, 0
    local function translate(v, depth)
        local l = LANG[settings.lang]
        if not l or depth > (settings.lang == 'zh-Hans' and 6 or 3) then return v end
        local t = l.exact[v] or l.lower[v] or l.upper[v] or (settings.lang == 'zh-Hans' and l.lower[v:lower()])
        if t then return t end
        if v:sub(1, 2) == '* ' and l.exact[v:sub(3)] then return '* ' .. l.exact[v:sub(3)] end
        for _, p in ipairs(l.patterns) do
            local caps = { v:match(p[1]) }
            if caps[1] then
                return (p[2]:gsub('%%(L?)([1-9])', function(list, k)
                    local x = caps[tonumber(k)]
                    if not x or x == '' then return '' end
                    if list == '' then return translate(x, depth + 1) end
                    local out = {}   -- %L1: a ', ' list of names, each translated
                    for name in (x .. ', '):gmatch('(.-), ') do out[#out + 1] = translate(name, depth + 1) end
                    return table.concat(out, l.list or ', ')
                end))
            end
        end
        for _, p in ipairs(l.prefix) do
            if v:sub(1, #p[1]) == p[1] then v = p[2] .. v:sub(#p[1] + 1); break end
        end
        for _, p in ipairs(l.suffix) do
            if #v > #p[1] and v:sub(-#p[1]) == p[1] then return v:sub(1, #v - #p[1]) .. p[2] end
        end
        return v
    end
    if MOD.offline then   -- for the host's own text and fonts
        state.tr = function(v) return settings.tr(v) end
        state.lang = function() return settings.lang end
        state.updates = function() return settings.updates end   -- the host's updater: 'ask' or 'auto'
        state.update_channel = function() return settings.update_channel end   -- 'releases' or 'commits'
        state.armor_passives = function() return settings.armor_passives end   -- armor text id -> { passive ids }
        state.one_line = function()   -- passive id -> how many lines its typed description has
            local out = {}
            for hash, typed in pairs(MOD.rename.texts) do
                local w = by_hash[hash]
                if w and w.passive and typed.desc then
                    out[tables[w.passive].index.id] = #MOD.rename.parts((typed.desc:gsub('|', '\n')))
                end
            end
            return out
        end
        state.load_donors = function() return MOD.donors() end
        state.notify = function(...) MOD.notify(...) end
        -- stratagem type -> { arrow, ... }: every call-in code set here (hostdata.lua M.codes writes them)
        state.codes = function()
            local out = {}
            for _, f in pairs(fields) do
                if f.def and f.storage == 'virtual' and f.value ~= nil and f.value ~= f.default then
                    local arrows, t = MOD.code.arrows(f.value), peek4(f.def.at)
                    if arrows and t then out[t] = arrows end
                end
            end
            return out
        end
    end
    function settings.tr(v)
        if settings.lang == 'en' or not LANG[settings.lang] then return v end
        local cache = tr_cache[settings.lang]
        if not cache or tr_count > 5000 then cache, tr_count = {}, 0; tr_cache = { [settings.lang] = cache } end
        local t = cache[v]
        if not t then t = translate(v, 0); cache[v], tr_count = t, tr_count + 1 end
        return t
    end
end

-- unlocks: items the game has but does not offer, by id, on / off (settings.unlock, below). Each: config
-- name, a stratagem (its number in game.dll's stratagem list, key and record key in the item registry)
-- or equipment (model = entity hash high / low; template: the model, or key and class, of an item of
-- the same kind whose registry row a new row is copied from)
settings.UNLOCKS = {
    { id = 'incinerator', name = 'M-104 Incinerator FRV', config = 'incinerator_frv',
      strat = 135, key = 0xA9A97CD7, record = 0xDA0600D7 },
    { id = 'ombudsman', name = 'P-41 Ombudsman', config = 'unlock_ombudsman',
      model = { 0xBDE1F253, 0x4280300D }, template = { 0x05E4E5C2, 0xDB6E44A2 } },   -- template: P-2 Peacemaker
    { id = 'caltrops', name = 'G-11 Caltrops', config = 'unlock_caltrops',
      model = { 0x2968DEBA, 0x6D6C2F09 }, template = { 0x4CE9EAB7, 0x85A79B7B } },   -- template: G-6 Frag
    { id = 'shear', name = 'LAS-22 Shear', config = 'unlock_shear',   -- its key checked; template: the LAS-5 Scythe's key
      model = { 0x7E3145A5, 0xBAA4B948 }, key = 0x7DE53646, template_key = 0xE673DCC8, class = 1 },
}
settings.unlocks = {}
-- one switch for them all (Settings: "Unlock unused items"): on while any is (old configs saved each)
function settings.unlock_any()
    for _, item in ipairs(settings.UNLOCKS) do if settings.unlocks[item.id] then return true end end
    return false
end
function settings.unlock_all(on)
    for _, item in ipairs(settings.UNLOCKS) do settings.unlocks[item.id] = on end
end

local function config_path()
    local dir = data_dir('StatEditor')
    return dir and dir .. '/config.txt'
end

local function number_text(v)
    if math.abs(v - math.floor(v + 0.5)) < 1e-6 then return tostring(math.floor(v + 0.5)) end
    return (string.format('%.4f', v):gsub('0+$', ''):gsub('%.$', ''))
end

function settings.set_percent(name, value)
    local r = settings.RANGE[name]
    local v = math.floor(value + 0.5)
    settings[name] = math.max(r[1], math.min(r[2], v))
    return settings[name] ~= v
end

-- ---------------------------------------------------------------- names and descriptions (offline)
-- The Name and Description boxes under a page's rows: the game's text ids in its encyclopedia entry (weapons,
-- throwables: +0 name, +8 in capitals, +20 description) and its stratagem's row (+44 name, +40 in capitals, +48
-- description), armors, helmets and capes (kit +16 name, +12 in capitals, +20 description; an armor and its helmet
-- can share them), passives (+4 name, the first modifier's line; a typed one is the only line, hostdata drops the others), attachments (+16 name, +12 in capitals, +20
-- description), boosters (their ids below: no table holds them). The host has the game's English texts (SHODAN_PHYSICS.texts, by id); Install puts the typed ones
-- into every language's strings files through the patch archive (offline/vehicles.lua). In config.txt:
-- rename <page hash> name|desc <text> (| in a text: a new line; {H}: a # sign, which would start a comment)
MOD.rename = { texts = {}, LIMIT = { name = 60, code = 20, desc = 400 } }

local function save_config()
    config_dirty_at = nil
    local path = config_path()
    if not path then return end
    local lines = {
        '# SHODAN Stat Editor settings. Changed through the in-game panel; applied at every start.',
        '# Lines: <weapon hash> <stat> <value>. Delete a line (or this file) to go back to the game\'s value.',
        '# The first lines are the Settings page\'s choices.',
        'hotkey ' .. hotkey_name,
    }
    local function onoff(v) return v and 'on' or 'off' end
    for _, line in ipairs({ 'changes ' .. onoff(settings.changes), 'block_input ' .. onoff(settings.block_input),
                            'panel_size ' .. settings.size, 'panel_side ' .. settings.side,
                            'panel_opacity ' .. settings.opacity,
                            'arc_chains_multiplayer ' .. onoff(settings.arc_mp) }) do
        lines[#lines + 1] = line
    end
    if MOD.offline then lines[#lines + 1] = 'lang ' .. settings.lang end
    if MOD.offline then
        lines[#lines + 1] = 'updates ' .. settings.updates
        lines[#lines + 1] = 'update_channel ' .. settings.update_channel
        -- armor_passive <armor text id> <passive id>,<passive id>... or none: the passives of that armor
        local armors, PASSIVE_NAMES = {}, KINDS[TYPES.passive].NAMES
        for id in pairs(settings.armor_passives) do armors[#armors + 1] = id end
        table.sort(armors)
        for _, id in ipairs(armors) do
            local list, names = settings.armor_passives[id], {}
            for k, other in ipairs(list) do names[k] = PASSIVE_NAMES[other] or ('Passive ' .. other) end
            lines[#lines + 1] = string.format('armor_passive %08X %s   # %s: %s', id, #list > 0 and table.concat(list, ',') or 'none',
                                              MOD.kit_names and MOD.kit_names[id] or '?', #list > 0 and table.concat(names, ', ') or 'none')
        end
        -- (older configs) passive_stack <passive id> <passive id>,<passive id>...: the passives stacked on it;
        -- MOD.kits.migrate turns these and passive_own into armor_passive lines
        local ids, NAMES = {}, KINDS[TYPES.passive].NAMES
        for id in pairs(settings.stacks) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do
            local names = {}
            for k, other in ipairs(settings.stacks[id]) do names[k] = NAMES[other] or ('Passive ' .. other) end
            lines[#lines + 1] = 'passive_stack ' .. id .. ' ' .. table.concat(settings.stacks[id], ',') ..
                                '   # ' .. (NAMES[id] or ('Passive ' .. id)) .. ': ' .. table.concat(names, ', ')
        end
        -- passive_own <passive id> off: its own effects left out (only the passives stacked on it apply)
        ids = {}
        for id in pairs(settings.own_off) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do
            lines[#lines + 1] = 'passive_own ' .. id .. ' off   # ' .. (NAMES[id] or ('Passive ' .. id))
        end
    end
    lines[#lines + 1] = 'unlock_unused ' .. onoff(settings.unlock_any())
    lines[#lines + 1] = 'several_vehicles ' .. onoff(MOD.vehicles.on)
    lines[#lines + 1] = 'stratagem_bounce ' .. onoff(MOD.tweaks.bounce.on)
    lines[#lines + 1] = 'foliage_pass_through ' .. onoff(MOD.tweaks.foliage.on)
    lines[#lines + 1] = 'sniper_crosshair ' .. onoff(MOD.tweaks.reticle.on)
    -- hide_tabs <tab>,<tab>...: the tabs Settings > Tabs shown turned off
    local hidden = {}
    for tab in pairs(settings.hidden) do hidden[#hidden + 1] = tab end
    table.sort(hidden)
    if #hidden > 0 then lines[#lines + 1] = 'hide_tabs ' .. table.concat(hidden, ',') end
    -- the tab and page each editor was left on, and the editor (reopened there)
    local last = settings.last
    if last.stat.tab then lines[#lines + 1] = 'last_tab ' .. last.stat.tab end
    if last.stat.weapon then lines[#lines + 1] = 'last_weapon ' .. last.stat.weapon end
    if last.enemy.tab then lines[#lines + 1] = 'enemy_tab ' .. last.enemy.tab end
    if last.enemy.weapon then lines[#lines + 1] = 'enemy_page ' .. last.enemy.weapon end
    lines[#lines + 1] = 'editor ' .. (settings.enemy_last and 'enemy' or 'stat')
    for _, o in ipairs(overrides) do
        local weapon = by_hash[o.hash]
        lines[#lines + 1] = o.hash .. ' ' .. o.id .. ' ' .. number_text(o.value) ..
                            (weapon and ('   # ' .. weapon.name) or '')
    end
    local renamed = {}
    for hash in pairs(MOD.rename.texts) do renamed[#renamed + 1] = hash end
    table.sort(renamed)
    for _, hash in ipairs(renamed) do
        for _, field in ipairs({ 'name', 'code', 'desc' }) do
            local v = MOD.rename.texts[hash][field]
            if v then lines[#lines + 1] = 'rename ' .. hash .. ' ' .. field .. ' ' .. v:gsub('#', '{H}') end
        end
    end
    local old = io.open(path, 'rb')
    local before = old and old:read('*a')
    if old then old:close() end
    if before and #before > 0 then MOD.write_text(path .. '.bak', before) end   -- the save before this one, to go back to by hand
    local ok, why = MOD.write_text(path, table.concat(lines, '\r\n') .. '\r\n')
    if not ok then log('could not write ' .. path .. ': ' .. why) end
end

local function load_config()
    local path = config_path()
    local handle = path and io.open(path, 'rb')
    if not handle then save_config(); return end
    local text = handle:read('*a') or ''
    handle:close()
    local count = 0
    for at, line in MOD.lines_of(text) do
        line = line:gsub('#.*$', '')
        local known = not line:find('%S')
        local key = line:match('^%s*hotkey%s+(%S+)')
        if key then hotkey_name = key; known = true end
        local name, value = line:match('^%s*([%a_]+)%s+(%S+)%s*$')
        local target, sources = line:match('^%s*passive_stack%s+(%d+)%s+([%d,]+)%s*$')
        if target and MOD.offline then
            local list, seen = {}, { [tonumber(target)] = true }
            for id in sources:gmatch('%d+') do
                id = tonumber(id)
                if not seen[id] then seen[id], list[#list + 1] = true, id end
            end
            settings.stacks[tonumber(target)] = #list > 0 and list or nil
            known = true
        end
        local armor, passives = line:match('^%s*armor_passive%s+(%x+)%s+([%a%d,]+)%s*$')
        if armor and MOD.offline then
            local list, seen = {}, {}
            for id in passives:gmatch('%d+') do
                id = tonumber(id)
                if not seen[id] then seen[id], list[#list + 1] = true, id end
            end
            settings.armor_passives[tonumber(armor, 16)], known = list, true
        end
        local own = line:match('^%s*passive_own%s+(%d+)%s+off%s*$')
        if own and MOD.offline then settings.own_off[tonumber(own)], known = true, true end
        if name == 'changes' or name == 'block_input' then
            settings[name] = value ~= 'off'
            known = true
        elseif name == 'remember' then   -- the old Settings choice: always on now
            known = true
        elseif name == 'check_updates' or name == 'updates' and value == 'off' then   -- test builds' (no Off now)
            known = true
        elseif name == 'update_channel' and (value == 'releases' or value == 'commits') then
            settings.update_channel = value
            known = true
        elseif name == 'updates' and (value == 'ask' or value == 'auto') then
            settings.updates = value
            known = true
        elseif name == 'arc_chains_multiplayer' then
            settings.arc_mp = value == 'on'
            known = true
        elseif (name == 'panel_size' or name == 'panel_opacity') and MOD.parse_number(value) then
            settings.set_percent(name:sub(7), MOD.parse_number(value))
            known = true
        elseif name == 'panel_side' and (value == 'left' or value == 'right') then
            settings.side = value
            known = true
        elseif name == 'lang' and MOD.offline and (value == 'en' or settings.LANGS[value]) then
            settings.lang = value
            known = true
        elseif name == 'panel_lang' then   -- the language choice of PR #52's build and of test builds: gone
            known = true                     -- (each language has its own release)
        elseif name == 'last_tab' or name == 'enemy_tab' then
            settings.last[name == 'enemy_tab' and 'enemy' or 'stat'].tab = value
            known = true
        elseif name == 'editor' and (value == 'enemy' or value == 'stat') then
            settings.enemy_last = value == 'enemy'
            known = true
        elseif name == 'hide_tabs' then
            for tab in value:gmatch('[^,%s]+') do settings.hidden[tab] = true end
            known = true
        elseif (name == 'last_weapon' or name == 'enemy_page') and value:find('^%x+$') and #value == 16 then
            settings.last[name == 'enemy_page' and 'enemy' or 'stat'].weapon = value:upper()
            known = true
        elseif name == 'several_vehicles' then
            MOD.vehicles.on = value == 'on'; MOD.vehicles.apply()
            known = true
        elseif name == 'stratagem_bounce' or name == 'foliage_pass_through' or name == 'sniper_crosshair' then
            MOD.tweaks[name == 'stratagem_bounce' and 'bounce' or name == 'sniper_crosshair' and 'reticle' or 'foliage'].on = value == 'on'
            MOD.tweaks.apply()
            known = true
        elseif name == 'unlock_unused' then
            settings.unlock_all(value == 'on')
            known = true
        elseif name then   -- last: any other name would stop here
            for _, item in ipairs(settings.UNLOCKS) do
                -- one line per item before the single switch: any on turns them all on (local test builds
                -- saved incinerator_frv 'off' / 'gunner' / 'supply')
                if name == item.config then
                    if value == 'on' then settings.unlock_all(true) end
                    known = true
                end
            end
        end
        local hash, id, amount = line:match('^%s*(%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x)%s+([%w_]+)%s+(%S+)')
        local parsed = hash and MOD.parse_number(amount)
        if parsed then
            overrides[#overrides + 1] = { hash = hash:upper(), id = id, value = parsed }
            count = count + 1
            known = true
        end
        local rhash, field, typed = line:match('^%s*rename%s+(%x+)%s+(%a+)%s+(.-)%s*$')
        if rhash and MOD.offline and (field == 'name' or field == 'code' or field == 'desc') and typed ~= '' then
            local t = MOD.rename.texts[rhash:upper()] or {}
            t[field], MOD.rename.texts[rhash:upper()], known = typed:gsub('{H}', '#'), t, true
        end
        if not known then MOD.skipped('config.txt', at, line) end
    end
    log('config: ' .. count .. ' value(s), hotkey ' .. hotkey_name .. (settings.changes and '' or ', changes OFF') ..
        ' (' .. path .. ')')
end

local function mark_config_dirty() config_dirty_at = api.now() + 0.75; MOD.enemy.refresh_due = true end

-- an armor page's passives: its own list, or the game's
function MOD.kits.list_of(page) return settings.armor_passives[page.armor] or page.default end
-- list nil or the game's own: the armor goes back to the game's
function MOD.kits.set(page, list)
    if list and table.concat(list, ',') == table.concat(page.default, ',') then list = nil end
    if settings.armor_passives[page.armor] == nil and list == nil then return end
    settings.armor_passives[page.armor] = list
    state.writes = state.writes + 1   -- (the host: changed since the last install)
    mark_config_dirty()
end
-- older configs stacked passives on a passive: the same effects as a list on each armor that has it
function MOD.kits.migrate()
    if not next(settings.stacks) and not next(settings.own_off) then return end
    for _, page in ipairs(weapons) do
        local id = page.armor and page.default[1]
        if id and (settings.stacks[id] or settings.own_off[id]) and not settings.armor_passives[page.armor] then
            local list = settings.own_off[id] and {} or { id }
            for _, other in ipairs(settings.stacks[id] or {}) do list[#list + 1] = other end
            MOD.kits.set(page, list)
        end
    end
    settings.stacks, settings.own_off = {}, {}
    state.writes = state.writes + 1
    mark_config_dirty()
end

-- a page's text ids ({ id, capitals } lists name and desc) and its game texts (game.name, game.desc), nil without
-- the id of a designation text, by the first word of a page's name (a stratagem's record holds no designation: its
-- weapon's does)
function MOD.rename.code_id(name)
    if not MOD.rename.codes then
        local codes, t, texts = {}, tables[TYPES.encyclopedia], rawget(_G, 'SHODAN_PHYSICS').texts
        for _, e in pairs(t and t.index or {}) do
            local id = type(e) == 'number' and peek4(t.copies[1] + HEADER_BYTES + e + 36)
            if id and texts[id] then codes[texts[id]] = id end
        end
        MOD.rename.codes = codes
    end
    return MOD.rename.codes[name:match('^%S+')]
end

function MOD.rename.of(w)
    local host = rawget(_G, 'SHODAN_PHYSICS')
    local texts = host and host.texts
    if not texts or not w then return nil end
    local out = { name = {}, code = {}, desc = {} }
    local function add(list, id, caps) if id and texts[id] then list[#list + 1] = { id, caps } end end
    local t = w.key and tables[TYPES.encyclopedia]
    local e = t and t.index[w.key]
    if e then
        local at = t.copies[1] + HEADER_BYTES + e
        add(out.name, peek4(at)); add(out.name, peek4(at + 8), true); add(out.desc, peek4(at + 20)); add(out.code, peek4(at + 36))
    end
    local def = w.stratagem and w.stratagem.def
    if def then add(out.name, peek4(def.at + 44)); add(out.name, peek4(def.at + 40), true); add(out.desc, peek4(def.at + 48)) end
    if def and not out.code[1] then add(out.code, MOD.rename.code_id(w.name)) end
    local kit = MOD.kits.texts and MOD.kits.texts[w.armor or w.look]
    if kit then
        add(out.name, w.armor or w.look)
        for id in pairs(kit.caps) do add(out.name, id, true) end
        for id in pairs(kit.desc) do add(out.desc, id) end
    end
    local passive = w.passive and tables[w.passive].index
    if passive then
        add(out.name, passive.text)
        for _, id in ipairs(passive.lines) do add(out.desc, id) end
    end
    local a = w.attachment and w.attachment.texts or w.booster and MOD.boosters.TEXTS[w.booster[1]]
    if a then add(out.name, a[1]); add(out.name, a[2], true); add(out.desc, a[3]) end
    if #out.name == 0 then return nil end
    out.game = { name = texts[out.name[1][1]], code = out.code[1] and texts[out.code[1][1]],
                 desc = out.desc[1] and texts[out.desc[1][1]]:gsub('\r?\n', '|') }
    if passive then
        -- every line, a gap between them: typed, each part goes to its line, so it keeps its own #BONUS value
        local lines = {}
        for k, n in ipairs(out.desc) do lines[k] = texts[n[1]]:gsub('\r?\n', '|') end
        out.game.desc, out.lines = out.desc[1] and table.concat(lines, '||'), true
    end
    return out
end

-- the other pages using the designation text `id` (a typed one changes them all)
function MOD.rename.sharing(w, id)
    if not MOD.rename.users then
        local users, t = {}, tables[TYPES.encyclopedia]
        for _, o in ipairs(weapons) do
            local e = t and o.key and t.index[o.key]
            local code = e and peek4(t.copies[1] + HEADER_BYTES + e + 36)
            if code and code ~= 0 then
                users[code] = users[code] or {}
                table.insert(users[code], o)
            end
        end
        MOD.rename.users = users
    end
    local names = {}
    for _, o in ipairs(MOD.rename.users[id] or {}) do
        if o ~= w and o ~= w.same then names[#names + 1] = o.name end
    end
    return names
end

-- the page and field a box edits: 'line<id>', on an armor's passive row, is that passive's description
function MOD.rename.page(w, field)
    local id = field:match('^line(%d+)$')
    if not id then return w.same or w, field end
    return by_hash[string.format('FFFFFFFE%08X', tonumber(id))], 'desc'
end

-- a passive's typed text, by the blank lines in it
function MOD.rename.parts(text)
    local parts = {}
    for part in (text .. '\n\n'):gmatch('(.-)\n\n') do parts[#parts + 1] = part end
    return parts
end

-- id -> text of every typed name and description (the host's Install asks)
function MOD.rename.map()
    local out = {}
    for hash, typed in pairs(MOD.rename.texts) do
        local ids = MOD.rename.of(by_hash[hash])
        for _, field in ipairs(ids and { 'name', 'code', 'desc' } or {}) do
            local text = typed[field] and typed[field]:gsub('|', '\n')   -- (config.txt keeps a line per text)
            if text and field == 'desc' and ids.lines then
                local parts = MOD.rename.parts(text)
                for k, part in ipairs(parts) do
                    local n = ids.desc[math.min(k, #ids.desc)][1]
                    out[n] = k > #ids.desc and out[n] .. '\n\n' .. part or part
                end
            else
                for _, n in ipairs(text and ids[field] or {}) do out[n[1]] = n[2] and text:upper() or text end
            end
        end
    end
    return out
end
do local host = rawget(_G, 'SHODAN_PHYSICS'); if host then host.renames = MOD.rename.map end end

-- a page's typed text (nil, '' or the game's own: back to the game's)
function MOD.rename.set(w, field, text)
    local ids = MOD.rename.of(w)
    if text == '' or (ids and text == ids.game[field]) then text = nil end
    local t = MOD.rename.texts[w.hash] or {}
    t[field] = text
    MOD.rename.texts[w.hash] = next(t) and t or nil
    state.writes = state.writes + 1   -- (the host: changed since the last install)
    mark_config_dirty()
end

-- Drops every override that writes the same memory as (hash, id), then optionally adds one.
local function set_override(weapon, p, value)
    local kept = {}
    for _, o in ipairs(overrides) do
        local other = by_hash[o.hash]
        local op = other and other.by_id[o.id]
        if not (op and op.field == p.field) and not (o.hash == weapon.hash and o.id == p.id) then
            kept[#kept + 1] = o
        end
    end
    if value ~= nil then kept[#kept + 1] = { hash = weapon.hash, id = p.id, value = value } end
    overrides = kept
    if p.field and p.field.storage == 'grenade' then MOD.queue_grenade(weapon, p, value) end
    mark_config_dirty()
end

-- Writes the faction-wide rows' fields (MOD.enemy.FACTION_STATS): each covered field as its game value x the row
-- (armor: + the row), but for the fields another page has a change on (that page's value stands). Run once the
-- saved values are applied and after every change (MOD.enemy.refresh_due).
function MOD.enemy.faction_refresh()
    MOD.enemy.refresh_due = nil
    local owned, by_all, covered = {}, {}, {}
    for _, o in ipairs(overrides) do
        local page = by_hash[o.hash]
        local p = page and not (page.enemy and page.enemy.faction) and page.by_id[o.id]
        if p and p.field then owned[p.field.key] = true end
    end
    for _, page in ipairs(weapons) do
        if page.enemy and page.enemy.faction then
            -- its fields, gathered once: per stat, every covered part of the faction's pages
            if not page.enemy.targets then
                local targets = {}
                for _, r in ipairs(page.rows) do targets[r.id] = { list = {}, seen = {} } end
                for _, other in ipairs(weapons) do
                    if other.enemy and other.slot == page.slot and not other.enemy.faction then
                        for _, r in ipairs(other.rows) do
                            for _, p in ipairs(r.parts) do
                                for _, s in ipairs(MOD.enemy.FACTION_STATS) do
                                    local t = targets[s[2]]
                                    if t and p.field and p.field.storage ~= 'virtual' and not t.seen[p.field.key] and s[7](other, r, p) then
                                        t.seen[p.field.key] = true
                                        t.list[#t.list + 1] = p.field
                                    end
                                end
                            end
                        end
                    end
                end
                page.enemy.targets = targets
            end
            for _, r in ipairs(page.rows) do
                local v = read_field(r.parts[1].field) or (r.add and 0 or 1)
                for _, f in ipairs(page.enemy.targets[r.id].list) do
                    local d = default_of(f)
                    local new = d and d * v
                    if d and r.add then new = math.max(0, math.min(10, d + v)) end
                    if new and f.storage == 'u32' then new = math.floor(new + 0.5) end
                    if new and f.limit then new = math.min(new, f.limit) end
                    local moved = new and math.abs(new - d) > 1e-4 * math.max(1, math.abs(d))
                    if moved then covered[f.key] = true end
                    if new and not owned[f.key] then
                        local now = read_field(f)
                        if now == nil or math.abs(now - new) > 1e-4 * math.max(1, math.abs(new)) then write_field(f, new) end
                        if moved then by_all[f.key] = true end
                    end
                end
            end
        end
    end
    -- the Helldiver's Weapon sway (x): the game's sway x it on every weapon aimed by hand (not the SEAF copies,
    -- sentries or Guard Dogs; emplacements: 'E/'), but where a weapon's own Sway multiplier is changed; shown blue like a faction row's
    local hd = by_hash[KINDS[TYPES.avatar].ENTITY]
    local lead = hd and hd.by_id.weapon_sway
    if lead then
        local v = read_field(lead.field) or 1
        for _, w in ipairs(weapons) do
            local f = w.by_id.sway and w.by_id.sway.field
            local d = f and not w.enemy and not owned[f.key] and (w.mounted or w.sentry_defs and w.name:find('^E/') or (w.slot == 'Primary'
                      or w.slot == 'Secondary' or w.slot == 'Support') and not w.name:find('(SEAF)', 1, true)) and default_of(f)
            if d then
                local new, now = d * v, read_field(f)
                if now == nil or math.abs(now - new) > 1e-4 * math.max(1, math.abs(new)) then write_field(f, new) end
                if math.abs(new - d) > 1e-4 * math.max(1, math.abs(d)) then by_all[f.key] = true end
            end
        end
    end
    -- the pages with a value only a faction-wide row changed (their name in the list: MOD.enemy.ALL_INK)
    local pages = {}
    for _, page in ipairs(weapons) do
        if page.enemy and not page.enemy.faction then
            for _, r in ipairs(page.rows) do
                if MOD.enemy.by_all_value(r, by_all, owned) then pages[page.hash] = true; break end
            end
        end
    end
    MOD.enemy.by_all, MOD.enemy.owned, MOD.enemy.by_all_pages, MOD.enemy.covered = by_all, owned, pages, covered
    -- a page's value kept at the game's own (MOD.enemy.keep_own) once no faction-wide row moves it: dropped
    local kept = {}
    for _, o in ipairs(overrides) do
        local page = by_hash[o.hash]
        local p = page and page.enemy and not page.enemy.faction and page.by_id[o.id]
        local d = p and p.field and default_of(p.field)
        if not (d and not covered[p.field.key] and math.abs(o.value - d) < 1e-4) then kept[#kept + 1] = o end
    end
    if #kept < #overrides then overrides = kept; mark_config_dirty() end
end

-- A row's value when only a faction-wide row changed it (none of its fields has a change of a page's own), else
-- nil. A multiplier row: the factor its fields got (its own value stays the game's 1).
function MOD.enemy.by_all_value(row, by_all, owned)
    by_all, owned = by_all or MOD.enemy.by_all, owned or MOD.enemy.owned
    if not by_all then return nil end
    local hit = nil
    for _, p in ipairs(row.parts) do
        if p.field and owned[p.field.key] then return nil end
        if p.field and by_all[p.field.key] then hit = hit or p end
    end
    if not hit then return nil end
    if row.lead then
        if row.parts[1] == hit then return row_value(row) end
        local d, v = default_of(hit.field), read_field(hit.field)
        if not (d and v) or d == 0 or v == 0 then return nil end
        return row.inverse and d / v or v / d
    end
    return row_value(row)
end

-- The value to keep as a change: nil when it is the game's own.
local function unless_default(value, default)
    if default ~= nil and math.abs(value - default) < 1e-4 then return nil end
    return value
end

-- The value to keep as a page's own change: its game value too where an 'All <faction>' row moves the field
-- (set back to the game's value on purpose: kept, so the faction-wide row leaves it), else unless_default's.
function MOD.enemy.keep_own(weapon, p, value, default)
    if weapon.enemy and not weapon.enemy.faction and p.field and MOD.enemy.covered and MOD.enemy.covered[p.field.key] then
        return value
    end
    return unless_default(value, default)
end

-- Whether a row holds a page's own change at the game's value where a faction-wide row moves it (shown as changed)
function MOD.enemy.pinned(row)
    local covered, owned = MOD.enemy.covered, MOD.enemy.owned
    if not (covered and owned) then return false end
    for _, p in ipairs(row.parts) do
        if p.field and covered[p.field.key] and owned[p.field.key] then return true end
    end
    return false
end

-- A multiplier row's fields written from its own value (a preset holding only that: the examples).
function MOD.enemy.mult_fields(weapon, row, value)
    for k = 2, #row.parts do
        local p = row.parts[k]
        local d = default_of(p.field)
        if d ~= nil then
            local new = row.inverse and d / value or d * value
            if write_field(p.field, new) then set_override(weapon, p, unless_default(new, d)) end
        end
    end
end

-- A row whose value is the span of time rows (row.keeps: the Hover Pack's recharge time, its fuel):
-- their times before it changes, then (keep_times) their rates rewritten so the times stay.
function MOD.times_of(row)
    if not row.keeps then return nil end
    local times = {}
    for n, k in ipairs(row.keeps) do times[n] = row_value(k) end
    return { rows = row.keeps, times = times }
end

function MOD.keep_times(weapon, keep)
    if not keep then return end
    for n, k in ipairs(keep.rows) do
        local span, p = k.span(), k.parts[1]
        if keep.times[n] and keep.times[n] > 0 and span and span > 0 then   -- (no time to keep at 0)
            local new, d = span / keep.times[n] - (k.rate_plus or 0), default_of(p.field)
            if d and math.abs(new - d) < 1e-4 then new = d end
            if write_field(p.field, new) then set_override(weapon, p, unless_default(new, d)) end
        end
    end
end

-- Wind-up weapons (the Maxigun): its wind-up / wind-down times (`spin`: its WeaponWindUp record), and
-- WeaponData +387 (`data`: its record), set on the Maxigun alone: it stops you while you fire (HD2Runtime 0.30)
function MOD.spin_rows(weapon, data, spin)
    if spin then
        for _, t in ipairs({ { 'spin_up', 'Wind-up time (s)', 0 }, { 'spin_down', 'Wind-down time (s)', 4 } }) do
            add_row(weapon, 'Wind-up', t[1], t[2], 'f32', { part(t[1], TYPES.windup, spin + t[3], 'f32', 3600) }, 0.01, 60, 0.05, 0.25)
        end
    end
    local still = part('stationary', T_WEAPON, data + 387, 'flag', 1)
    if default_of(still.field) == 1 then
        add_row(weapon, 'Handling', 'stationary', 'Stops you while firing', 'flag', { still }, 0, 1, 1, 1)
    end
end

-- The parts a saved id names: its own (a swap row's first: the whole row's, all one value, so a field
-- the row gained later follows a value saved without it: the SG-20 Halt's ammo types), else (an id saved
-- before the weapon's magazine attachments had rows of their own: 'capacity', once every magazine's)
-- each of theirs. nil: none.
function MOD.parts_of(weapon, id)
    local own = weapon.by_id[id]
    if own and own.row and own.row.choice and not own.row.each and own.row.parts[1] == own then return own.row.parts end   -- (each: every part its own value)
    if own then return { own } end
    local out = {}
    for _, listed in ipairs(weapon.legacy and weapon.legacy[id] or {}) do out[#out + 1] = weapon.by_id[listed] end
    return out[1] and out or nil
end

-- For other mods: the game's own value of a stat, named as in config.txt (weapon hash, stat id), as
-- read at startup before this mod wrote anything. nil: no such weapon / stat, or its table not found.
function state.vanilla(hash, id)
    local weapon = type(hash) == 'string' and by_hash[hash:upper()]
    local p = weapon and type(id) == 'string' and weapon.by_id[id]
    return p and default_of(p.field) or nil
end

local pending = {}      -- config values not applied yet (tables still being written)
local apply_at = 1

-- Reuse the saved-value retry queue while a grenade's package loads. New selections,
-- reset and presets cancel older requests for the same field, including shared hosts.
function MOD.queue_grenade(weapon, p, value)
    apply_at = 1
    for n = #pending, 1, -1 do
        local o = pending[n]
        local other = by_hash[o.hash]
        local op = other and other.by_id[o.id]
        if op and op.field == p.field then table.remove(pending, n) end
    end
    p.field.pending_value = nil
    if settings.changes and value ~= nil and KINDS[TYPES.throwable].entity_bytes(value)
       and read_field(p.field) ~= value then
        p.field.pending_value = value
        pending[#pending + 1] = { hash = weapon.hash, id = p.id, value = value, after = api.now() + 1 }
    end
end

function MOD.clear_grenade_pending()
    for _, f in pairs(fields) do if f.storage == 'grenade' then f.pending_value = nil end end
end

-- Applies pending values until the deadline (the rest wait for the next call); true when the
-- whole list was gone through once. Values that could not be written yet are tried again
-- later (the table may still be filling), up to 30 times.
local function apply_config(deadline)
    while apply_at <= #pending do
        local o = pending[apply_at]
        local weapon = by_hash[o.hash]
        local parts = weapon and MOD.parts_of(weapon, o.id)
        local keep = false
        if o.after and api.now() < o.after then
            keep = true   -- a grenade choice still settling
        elseif not weapon then
            log('config: unknown weapon ' .. o.hash); state.refused = state.refused + 1
        elseif not parts then
            log('config: ' .. weapon.name .. ' has no stat ' .. o.id); state.refused = state.refused + 1
        else
            local ok, why = true, nil
            for _, p in ipairs(parts) do
                default_of(p.field)
                local done, failed = write_field(p.field, o.value)
                ok, why = ok and done, why or failed
            end
            if ok then
                for _, p in ipairs(parts) do
                    if p.field.storage == 'grenade' then p.field.pending_value = nil end
                end
                state.applied = state.applied + 1
                if parts[1].id ~= o.id then   -- saved under an old id: kept under the attachments' own from now on
                    set_override(weapon, { id = o.id }, nil)
                    for _, p in ipairs(parts) do set_override(weapon, p, unless_default(o.value, default_of(p.field))) end
                end
            else
                o.tries = (o.tries or 0) + 1
                keep = o.tries < 30
                if keep then
                    for _, p in ipairs(parts) do
                        if p.field.storage == 'grenade' then p.field.pending_value = o.value end
                    end
                end
                if not keep then
                    for _, p in ipairs(parts) do
                        if p.field.storage == 'grenade' then
                            p.field.pending_value = nil
                            -- the choice stays saved (tried again next start); say so, the row now shows the projectile
                            MOD.notify(weapon.name .. ': grenade not applied (' .. tostring(why) .. ')', 6)
                        end
                    end
                    log('config: ' .. weapon.name .. ' ' .. o.id .. ' not applied: ' .. why); state.refused = state.refused + 1
                end
            end
        end
        if keep then apply_at = apply_at + 1 else table.remove(pending, apply_at) end
        if deadline and api.now() >= deadline then break end
    end
    if apply_at <= #pending then return false end
    apply_at = 1
    return true
end

-- ---------------------------------------------------------------- loadout slot (issue #82)
-- The loadout list (LoadoutEntryComponentData): keyed by entity, records of 32 bytes (+0 id, +4 type:
-- 1 primary, 2 support, 3 secondary, 4 throwable, 5 gear, 6 backpack), more records than buckets, so its
-- bucket count is the one whose keys all sit near their home bucket (key % count). The type is the armory
-- slot the weapon is listed in: the Slot row moves it (primary, secondary or support).
TYPES.loadout = 0x4F2CF417
-- the Enemy Editor's spawning: HiveMindComponentData (a faction's spawn pressure, one per mission type) and the
-- lowest-rate record (0xD74E6E1A, one 96-byte record: +80/+84 patrols, +88/+92 reinforcements)
TYPES.hivemind, TYPES.spawn_floor = 0xD0207221, 0xD74E6E1A
KINDS[TYPES.hivemind] = { name = 'hive mind', stride = 1084, keyed = true }
KINDS[TYPES.spawn_floor] = { name = 'spawn floor', stride = 96, keyed = true }
-- the enemy pages' other tables (filediver's typelib layouts; strides checked on the current build):
-- AiCharacter (+0 preferred / +4 maximum speed), AiEnemy (each AI state's speed; 736 bytes in this build),
-- Unit (+8 / +12 scale), Inventory (+0 / +8 weapons carried), SensorEar (+4 hearing),
-- SquadTransportFormation (2 formations of 24: +4 rows, +8 columns)
TYPES.ai_character, TYPES.ai_enemy = 0x5FEF63C4, 0x9D0EEFB5
TYPES.unit, TYPES.inventory, TYPES.ear, TYPES.transport = 0x4437574D, 0x8ADAB43B, 0xC8033E7F, 0x498CE7C7
KINDS[TYPES.ai_character] = { name = 'AI character', stride = 80, keyed = true }
KINDS[TYPES.ai_enemy] = { name = 'enemy AI', stride = 736, keyed = true }
KINDS[TYPES.unit] = { name = 'unit', stride = 136, keyed = true }
KINDS[TYPES.inventory] = { name = 'inventory', stride = 144, keyed = true }
KINDS[TYPES.ear] = { name = 'hearing', stride = 16, keyed = true }
KINDS[TYPES.transport] = { name = 'transport', stride = 48, keyed = true }
-- whose side a unit is on (FactionComponentData, 152-byte records: +0 up to 3 factions of 4 bytes; 0 none,
-- 1 Super Earth, 2 Terminids, 4 Illuminate, 8 Automatons). From 127MU's and CarbonAnime's forks. Only the
-- first is shown; a unit whose first is none gets no row.
TYPES.faction = 0x5653EA91
KINDS[TYPES.faction] = { name = 'faction', stride = 152, keyed = true }
MOD.faction = { NAMES = { [1] = 'Super Earth', [2] = 'Terminids', [4] = 'Illuminate', [8] = 'Automatons' }, ORDER = { 1, 2, 4, 8 } }
function MOD.faction.row(entry, section, id, keys)
    local t, p = tables[TYPES.faction], {}
    for n, key in ipairs(keys) do
        local at = t and t.index[key]
        if at then p[#p + 1] = part(#p == 0 and id or (id .. '_' .. n), TYPES.faction, at, 'u32', 255) end
    end
    if #p == 0 or not MOD.faction.NAMES[default_of(p[1].field) or 0] then return end
    for _, q in ipairs(p) do q.field.allowed = { [1] = true, [2] = true, [4] = true, [8] = true, why = 'not a faction' } end
    local r = add_row(entry, section, id, 'Faction', 'u32', p, 1, 8, 1, 1)
    r.choice = 'faction'
    r.label_of = function() return 'Faction: ' .. (MOD.faction.NAMES[read_field(p[1].field) or 0] or '?') end
    r.note = 'who it fights for: units of other sides attack it, and it attacks them'
end
-- stratagem jammers (StratagemBlockerComponentData): +0 the stratagem kind blocked (7: every kind), +12 the
-- radius, +16 active from the start; 4 bytes after the records
TYPES.jammer = 0x8C5F8AB7
KINDS[TYPES.jammer] = { name = 'jammer', stride = 20, keyed = true, slack = 4 }
-- stratagem scramblers (StratagemScramblerComponentData, 28-byte records): +0 the stratagem kind scrambled, +12 the
-- radius, +16 its strength, +24 the status effect it puts on Helldivers in range
TYPES.scrambler = 0x595A2910
KINDS[TYPES.scrambler] = { name = 'scrambler', stride = 28, keyed = true }
-- target retention (0xFF67A367, 24-byte records; Gameplay Reforged's tank tracking): +16 how fast a lost target is
-- forgotten (1: the game's; 0.5 keeps tracking twice as long); the enemy Leviathan's flight path
-- (CurveNavigationComponentData, one 752-byte record): +20 the height above its route (40)
TYPES.retention, TYPES.curve = 0xFF67A367, 0x333C9A62
KINDS[TYPES.retention] = { name = 'target retention', stride = 24, keyed = true }
KINDS[TYPES.curve] = { name = 'flight path', stride = 752, keyed = true }
-- hit reactions (HitReactComponentData, 4836 bytes): +4 six reactions of 36 bytes (+0 the hit size: 1 light .. 4
-- massive, +4 the force a hit needs to stagger, +8 whether it staggers, +12 cooldown, +16 duration)
TYPES.hitreact = 0xD57D0101
KINDS[TYPES.hitreact] = { name = 'hit reaction', stride = 4836, keyed = true }
-- status effects taken (StatusEffectReceiverComponentData, 46600 bytes): 8 body parts of 5816 bytes from +0 (+0 the
-- part's name), each with 33 susceptibilities of 176 bytes from +8 (+140 the kind: 6 fire, 10 acid, 12 fire (bots),
-- 20 electric, 27 / 28 gas; +144 / +148 thresholds, +168 the damage it takes from it (x))
-- suppression: SensorDangerComponentData (12 bytes, 4 after the records): +0 the most danger it builds, +4 the radius
-- around it where shots count, +8 reacts to near misses (bool byte); TargetingComponentData (64 bytes): +36 how much
-- danger throws off its aim, +40 how fast that wears off (per second), +44 the most it can
TYPES.danger, TYPES.targeting = 0xC677F538, 0x2C0968D2
KINDS[TYPES.danger] = { name = 'danger sensor', stride = 12, keyed = true, slack = 4 }
KINDS[TYPES.targeting] = { name = 'targeting', stride = 64, keyed = true }
TYPES.status_rx = 0x6062C233
KINDS[TYPES.status_rx] = { name = 'status effects taken', stride = 46600, keyed = true }
KINDS[TYPES.loadout] = { name = 'loadout', stride = 32 }

KINDS[TYPES.loadout].parse = function(blob, stride)
    local total, count, live, keys, found = #blob, 0, 0, {}, nil
    while count * 16 + 16 <= total do
        local at = count * 16
        local slot, pad = u32(blob, at + 8), u32(blob, at + 12)
        if pad ~= 0 or slot > 100000 then break end
        local lo, hi = u32(blob, at), u32(blob, at + 4)
        count = count + 1
        if lo ~= 0 or hi ~= 0 then live = live + 1; keys[live] = { count - 1, lo, hi, slot } end
        local records = math.floor((total - count * 16) / stride)
        if count == 2 * live and count >= 64 and records > 0 then   -- (a few buckets always sit near home)
            local fits = true
            for k = 1, live do
                local b = keys[k]
                local home = ((b[3] % count) * (4294967296 % count) + b[2]) % count
                if (b[1] - home) % count >= 16 or b[4] >= records then fits = false; break end
            end
            if fits then
                if found then return nil, 'two layouts fit' end
                found = count
            end
        end
    end
    if not found then return nil, 'no layout fits' end
    local index, entries = {}, 0
    for k = 0, found - 1 do
        local key = blob:sub(k * 16 + 1, k * 16 + 8)
        if key ~= string.rep('\0', 8) and not index[key] then
            index[key] = found * 16 + u32(blob, k * 16 + 8) * stride
            entries = entries + 1
        end
    end
    return index, entries
end

-- Primary and secondary weapons only: a support weapon put in another slot is not listed there (the armory
-- lists the weapons your account owns, and support weapons come with their stratagem; tested 2026-10-24).
MOD.slot = { NAMES = { [1] = 'Primary', [3] = 'Secondary' } }

-- Which slot a support weapon goes to when you pick it up (SHODAN Offline Integration): InteractableComponentData,
-- 8 zones of 136 bytes from +8, +40 the interaction (1 primary, 2 secondary, 3 support). Secondary made weapons
-- vanish, so only 1 and 3; only on a record with one weapon pickup zone
TYPES.interactable = 0xFCCA29DB
KINDS[TYPES.interactable] = { name = 'pickup', stride = 1104, keyed = true }
function MOD.slot.pickup_row(weapon, key)
    local t = tables[TYPES.interactable]
    local off = t and KINDS[TYPES.interactable].stride == 1104 and t.index[key]
    if not off then return end
    local found, count = nil, 0
    for zone = 0, 7 do
        local at = off + 8 + zone * 136
        local kind = peek4(t.copies[1] + HEADER_BYTES + at + 40)
        if (peek4(t.copies[1] + HEADER_BYTES + at) or 0) ~= 0 and kind and kind >= 1 and kind <= 3 then
            found, count = at + 40, count + 1
        end
    end
    local p = count == 1 and part('pickup_slot', TYPES.interactable, found, 'u32', 3)
    if not p or default_of(p.field) ~= 3 then return end
    local r = add_row(weapon, 'Pickup', 'pickup_slot', 'Picked up into', 'u32', { p }, 1, 3, 2, 2)
    r.only = { [1] = true, [3] = true }
    r.label_of = function() return 'Picked up into: ' .. (read_field(p.field) == 1 and 'Primary slot' or 'Support slot') end
    r.tip = { 'Picking it up puts it in your primary slot instead (1), in place of your primary. 3 = the support slot.',
              'Not offered on backpack weapons: their backpack does not attach when the weapon is in your primary slot.' }
    -- WeaponData +464 auto_drop_ability (1240-byte layout; the EATs and the Commando): played when out of ammo, it
    -- always drops the support slot, so in the primary slot it looped and threw your support weapon away (issue #115)
    local at = KINDS[T_WEAPON].stride == 1240 and tables[T_WEAPON] and tables[T_WEAPON].index[key]
    local drop = at and field_at(T_WEAPON, at + 464, 'u32', 100000)
    if drop and (default_of(drop) or 0) ~= 0 then
        p.field.auto_drop = drop
        r.tip[3] = 'In the primary slot it is not thrown away when empty: it stays in your hands until you pick up another weapon.'
    end
end

function MOD.slot.row(weapon)
    local t = tables[TYPES.loadout]
    local off = t and t.index[weapon.key]
    if not off then return end
    local f = field_at(TYPES.loadout, off + 4, 'u32', 100000)
    if not MOD.slot.NAMES[default_of(f) or 0] then return end
    f.allowed = { [1] = true, [3] = true, why = 'a slot is 1 (primary) or 3 (secondary)' }
    local row = add_row(weapon, 'Loadout', 'slot', 'Slot (choice)', 'u32', { part('slot', TYPES.loadout, off + 4, 'u32', 100000) }, 1, 3, 2, 2)
    row.choice = 'slot'
    row.label_of = function() return 'Slot: ' .. (MOD.slot.NAMES[read_field(f) or 0] or '?') end
    row.note = 'the armory list it is in: 1 primary, 3 secondary'
    MOD.slot.place(weapon, row)
end
-- at the bottom, above the projectile swap
function MOD.slot.place(weapon, row)
    table.remove(weapon.rows)
    local at = #weapon.rows + 1
    for k, r in ipairs(weapon.rows) do if r.section == 'Projectile swap' then at = k; break end end
    table.insert(weapon.rows, at, row)
end

-- A pod with one weapon on the rack's left (node 76C6D1E3, side 2: the Leveller, Meltagun, Breaching Hammer): 2 puts a
-- copy on the right (slot 1 = slot 0's 64 bytes with the right's node 7FE13CFF, side 1, as the Commando's) and
-- drops both (+556 2). Parts: slot 1's 16 words, then +556.
MOD.pod = { LEFT = 0x76C6D1E3, RIGHT = 0x7FE13CFF }
function MOD.pod.twin_row(entry, rack)
    local parts = {}
    for w = 0, 15 do parts[#parts + 1] = part('pod_twin' .. (w > 0 and ('_' .. w) or ''), TYPES.rack, rack + 64 + w * 4, 'u32', 4294967295) end
    parts[#parts + 1] = part('pod_twin_count', TYPES.rack, rack + 556, 'u32', 8)
    local row = add_row(entry, 'Hellpod', 'pod_twin', 'Items per drop', 'u32', parts, 1, 2, 1, 1)
    row.choice, row.each, row.rack = 'pod_twin', true, rack
    row.note = '2 puts a second one on the other side of the pod'
end
function MOD.pod.value(row, default)
    local get = default and default_of or read_field
    return (get(row.parts[3].field) == MOD.pod.RIGHT and (get(row.parts[17].field) or 0) >= 2) and 2 or 1
end

-- Holster position (issue #101): a primary carried on the back, or on the hip where pistols hang. EquipmentComponent
-- +28 the holster node (primaries EC864C61, pistols CCF501C7), +32 / +44 its rotation (deg) / position offsets
-- (pistols: none). Hip writes the pistols' node and no offsets; Back puts the weapon's own back.
MOD.holster = { BACK = 0xEC864C61, HIP = 0xCCF501C7, NAMES = { [0] = 'Back', [1] = 'Hip' } }
function MOD.holster.row(weapon)
    local t = tables[TYPES.equipment]
    local off = t and t.index[weapon.key]
    if not off or default_of(field_at(TYPES.equipment, off + 28, 'u32', 4294967295)) ~= MOD.holster.BACK then return end
    local parts = { part('holster', TYPES.equipment, off + 28, 'u32', 4294967295) }
    parts[1].field.allowed = { [MOD.holster.BACK] = true, [MOD.holster.HIP] = true, why = 'the holster is on the back or the hip' }
    for k = 1, 6 do
        parts[k + 1] = part('holster_' .. k, TYPES.equipment, off + 28 + 4 * k, 'f32', 360)
        parts[k + 1].field.signed = true
    end
    local row = add_row(weapon, 'Loadout', 'holster', 'Holster position (choice)', 'u32', parts, 0, 1, 1, 1)
    row.choice, row.each = 'holster', true
    row.label_of = function() return 'Holster: ' .. MOD.holster.NAMES[MOD.holster.value(row)] end
    row.note = 'where it hangs when put away: 0 on the back, 1 on the hip'
    MOD.slot.place(weapon, row)
end
function MOD.holster.value(row, default)
    return (default and default_of or read_field)(row.parts[1].field) == MOD.holster.HIP and 1 or 0
end

-- ---------------------------------------------------------------- scan client
-- Once the tables are in: resolve every weapon, then apply the saved values, a slice per frame.
local progress = nil

-- The lists built once every table is found: one step per frame (phase 'building'), so no frame
-- carries them all. Each step: { name, function, what failing means }.
local function become_ready(final)
    state.build_steps = {
        { 'stratagems', build_stratagems, 'stratagems: not listed: ' },
        { 'attachments', KINDS[TYPES.items].build, 'attachments: not listed: ' },
        { 'passives', KINDS[TYPES.passive].build, 'armor passives: not listed: ' },
        { 'armor weight', MOD.kits.build, 'armor weight: not listed: ' },
        { 'boosters', MOD.boosters.build, 'boosters: not listed: ' },
        { 'enemies', MOD.enemy.build, 'enemies: not listed: ' },
    }
    set_status('building', 'listing stratagems, attachments and armor passives')
end

-- The next build step; once all are done, weapons are resolved and saved values applied.
function state.build_some()
    local build_steps = state.build_steps
    local step = table.remove(build_steps, 1)
    if step then
        local ok, why = pcall(step[2])
        if not ok then log(step[3] .. tostring(why)) end
        if #build_steps > 0 then return end
    end
    state.build_steps = nil
    progress = { next = 1 }
    pending, apply_at = {}, 1
    if settings.changes then
        for _, o in ipairs(overrides) do pending[#pending + 1] = { hash = o.hash, id = o.id, value = o.value } end
    end
    set_status('preparing', 'resolving weapons and applying saved values')
end

-- Every field's game value, read before this mod writes any: otherwise a field's default is read
-- when first needed, and holds another mod's value if one edited it first (an ammo mod's damage).
-- Reset, "was" and changes off then go back to the game's own value. Fields already read keep theirs.
function MOD.snapshot_defaults(progress, deadline)
    if not progress.keys then
        progress.keys, progress.read = {}, 1
        for key in pairs(fields) do progress.keys[#progress.keys + 1] = key end
    end
    local keys = progress.keys
    while progress.read <= #keys do
        default_of(fields[keys[progress.read]])
        progress.read = progress.read + 1
        if progress.read % 256 == 0 and api.now() >= deadline then return false end
    end
    return true
end

local function prepare(deadline)
    if not progress.resolved then
        if not resolve_some(progress, deadline) then return end
        progress.resolved = true
    end
    if not MOD.snapshot_defaults(progress, deadline) then return end
    if api.now() >= deadline or not apply_config(deadline) then return end
    progress = nil
    MOD.enemy.faction_refresh()
    local missing = {}
    for _, kind in ipairs(KIND_ORDER) do
        if not tables[kind] then missing[#missing + 1] = KINDS[kind].name end
    end
    for _, w in ipairs(weapons) do
        if w.stratagem and not w.stratagem.def and not w.stratagem.native and #STRATAGEMS > 0 and w.stratagem.family ~= 'support' then
            log('stratagem ' .. w.name .. ' (' .. w.hash .. '): definition not found; cooldown not editable')
        elseif w.stratagem and w.stratagem.def and w.stratagem.nodes[1] == nil then
            local keys = {}
            for k, key in ipairs(w.stratagem.payloads) do keys[k] = string.format('%08X%08X', u32(key, 4), u32(key, 0)) end
            log('stratagem ' .. w.name .. ' (' .. w.hash .. '): ' .. #w.rows .. ' rows, payloads ' .. table.concat(keys, ' '))
        end
    end
    set_status('ready', state.weapons .. ' weapons, ' .. (state.throwables or 0) .. ' throwables, ' ..
               (state.stratagems or 0) .. ' stratagems, ' .. (state.vehicles or 0) .. ' vehicles, ' ..
               (state.attachments or 0) .. ' attachments and ' ..
               (state.passives or 0) .. ' armor passives editable; ' ..
               state.applied .. ' saved value(s) applied' ..
               (#pending > 0 and (', ' .. #pending .. ' waiting') or '') ..
               (#missing > 0 and ('; tables not found: ' .. table.concat(missing, ', ')) or ''))
end

local function searching() return state.phase == 'searching' end

local function wants(kind, address)
    return KINDS[kind] ~= nil and not parsed_blocks[address]
end

local function handle_table(address, kind, payload, blob)
    local spec = KINDS[kind]
    if not spec or parsed_blocks[address] then return end
    if spec.found then   -- one of many tables taken by address (the destruction settings)
        spec.found[#spec.found + 1] = address
        parsed_blocks[address] = true
        return
    end
    local parse = spec.parse or (spec.keyed and parse_keyed or parse_rows)
    local started = api.now()
    local index, info = parse(blob, spec.stride, spec, address)
    -- game build 25988413 (2026-10-20) changed some records: its layouts are tried after the first one, and the
    -- one that fits is kept (`offsets`: where fields moved, old offset -> new)
    for _, layout in ipairs(not index and spec.layouts or {}) do
        local was = { spec.stride, spec.slack, spec.offsets }
        spec.stride, spec.slack, spec.offsets = layout.stride, layout.slack, layout.offsets
        index, info = parse(blob, spec.stride, spec, address)
        if index then
            log(string.format('%s: layout of game build 25988413 (%d bytes a record)', spec.name, spec.stride))
            break
        end
        spec.stride, spec.slack, spec.offsets = was[1], was[2], was[3]
    end
    local took = (api.now() - started) * 1000
    if not index then
        log(spec.name .. ' table at ' .. hex(address) .. ' not usable yet: ' .. info)
        return
    end
    local table_type = kind
    if spec.groups then
        -- each group is its own table; copies of one group have its size and first row
        local list = kind == T_STRATAGEM and stratagem_groups or spec.list
        kind = spec.group_key and spec.group_key(blob)
               or ((kind == T_STRATAGEM and 'stratagems' or spec.name) .. ' ' .. payload .. ' ' .. (u32(blob, 16 + (spec.id_at or 0)) or 0))
        if not tables[kind] then list[#list + 1] = kind end
    end
    local entry = tables[kind]
    if entry and entry.payload ~= payload then
        log(spec.name .. ' table at ' .. hex(address) .. ' has another size; ignored')
        parsed_blocks[address] = true
        return
    end
    if not entry then
        entry = { payload = payload, index = index, entries = info, copies = {}, type = table_type }
        tables[kind] = entry
        state.tables = state.tables + 1
    end
    entry.copies[#entry.copies + 1] = address
    parsed_blocks[address] = true
    log(string.format('%s table at %s: %d entries (parsed in %.2f ms)', spec.name, hex(address), info, took))
end

-- Offline every file is loaded before the scan and no game frame waits on it, so it starts at once, in long slices,
-- and never sweeps memory (from starstring's fork): that finds the editor's own copies and restarts the scan.
if MOD.offline then START_FRAME, FRAME_BUDGET, PASS_DELAY, FALLBACK_SECONDS = 1, 0.025, 0.02, math.huge end

local function after_pass(pass, final)
    if not searching() then return end
    if have_all_tables() or final or (MOD.offline and pass >= 2) then become_ready(final or not have_all_tables()) end
end

-- The tables are still where they were (checked when the panel opens); if not, scan again.
local hub = nil
local function tables_intact()
    for kind, entry in pairs(tables) do
        for _, block in ipairs(entry.fixed and {} or entry.copies) do
            local header = api.read(block, HEADER_BYTES)
            if not header or header:sub(1, 8) ~= NEEDLE or u32(header, 8) ~= entry.type or u32(header, 12) ~= entry.payload then
                return false
            end
        end
    end
    return true
end

local function rescan()
    log('a settings table moved; scanning again')
    tables, parsed_blocks, stratagem_groups = {}, {}, {}
    KINDS[TYPES.items].list = {}
    KINDS[TYPES.passive].list = {}
    KINDS[TYPES.kit].list = {}
    KINDS[TYPES.destruction].found, KINDS[TYPES.destruction].told = {}, nil
    state.tables = 0
    set_status('searching', 'a table moved; scanning again')
    if hub then hub.wake() end
end

-- ---------------------------------------------------------------- windows input
local user, own_pid = nil, nil
local point, rect, pid = nil, nil, nil

local function build_input()
    for _, declaration in ipairs({
        'void *GetForegroundWindow(void);',
        'uint32_t GetWindowThreadProcessId(void*,void*);',
        'uint32_t GetCurrentProcessId(void);',
        'int GetCursorPos(void*);',
        'int ScreenToClient(void*,void*);',
        'int GetClientRect(void*,void*);',
        'int16_t GetAsyncKeyState(int key);',
        'int16_t GetKeyState(int key);',
        'uint32_t MapVirtualKeyW(uint32_t code, uint32_t type);',
        'int ToUnicode(uint32_t vk, uint32_t scan, const uint8_t *state, uint16_t *text, int size, uint32_t flags);',
        'int ShowCursor(int show);',
        'int ClipCursor(const void *rect);',
        'int GetClipCursor(void *rect);',
        'void *GetModuleHandleA(const char *name);',
        'typedef struct { uint16_t page; uint16_t usage; uint32_t flags; void *target; } shodan_raw_device;',
        'uint32_t GetRegisteredRawInputDevices(shodan_raw_device *devices, uint32_t *count, uint32_t size);',
        'int RegisterRawInputDevices(const shodan_raw_device *devices, uint32_t count, uint32_t size);',
        'uint32_t GetCurrentThreadId(void);',
        'intptr_t GetWindowLongPtrW(void *window, int index);',
        'intptr_t SetWindowLongPtrW(void *window, int index, intptr_t value);',
        'void *GetProcAddress(void *module, const char *name);',
        'void *VirtualAlloc(void *address, size_t size, uint32_t type, uint32_t protect);',
        'int FlushInstructionCache(void *process, const void *address, size_t size);',
        'void *GetCurrentProcess(void);',
        'void *ShellExecuteW(void *window, const uint16_t *op, const uint16_t *file, const uint16_t *params, const uint16_t *dir, int show);',
        'int OpenClipboard(void *owner);',
        'int EmptyClipboard(void);',
        'void *SetClipboardData(uint32_t format, void *data);',
        'int CloseClipboard(void);',
        'void *GlobalAlloc(uint32_t flags, size_t bytes);',
        'void *GlobalLock(void *data);',
        'int GlobalUnlock(void *data);',
        'int MultiByteToWideChar(uint32_t page, uint32_t flags, const char *text, int bytes, uint16_t *wide, int chars);',
    }) do pcall(ffi.cdef, declaration) end
    user = ffi.load('user32')
    own_pid = ffi.load('kernel32').GetCurrentProcessId()
    point, rect, pid = ffi.new('int32_t[2]'), ffi.new('int32_t[4]'), ffi.new('uint32_t[1]')
end

local function focused_window()
    local window = user.GetForegroundWindow()
    if window == nil then return nil end
    if user.GetWindowThreadProcessId(window, ffi.cast('void *', pid)) == 0 or pid[0] ~= own_pid then return nil end
    return window
end

-- UTF-8 text as a zero-ended UTF-16 string (and its length in characters, the zero included)
function settings.wide(text)
    local kernel = ffi.load('kernel32')
    local n = kernel.MultiByteToWideChar(65001, 0, text, -1, nil, 0)
    local out = ffi.new('uint16_t[?]', math.max(1, n))
    kernel.MultiByteToWideChar(65001, 0, text, -1, out, n)
    return out, n
end

-- Opens a link or folder with Windows' default program (the browser, Explorer).
function settings.open(target)
    local ok = pcall(function()
        ffi.load('shell32').ShellExecuteW(nil, (settings.wide('open')), (settings.wide(target)), nil, nil, 1)
    end)
    return ok
end

-- Puts text on the clipboard.
function settings.copy(text)
    local kernel = ffi.load('kernel32')
    local wide, n = settings.wide(text)
    local data = kernel.GlobalAlloc(0x0002, n * 2)          -- GMEM_MOVEABLE
    if data == nil then return false end
    local at = kernel.GlobalLock(data)
    if at == nil then return false end
    ffi.copy(at, wide, n * 2)
    kernel.GlobalUnlock(data)
    if user.OpenClipboard(nil) == 0 then return false end
    user.EmptyClipboard()
    local ok = user.SetClipboardData(13, data) ~= nil      -- CF_UNICODETEXT
    user.CloseClipboard()
    return ok
end

local VK = { Up = 0x26, Down = 0x28, Left = 0x25, Right = 0x27, PageUp = 0x21, PageDown = 0x22,
             Delete = 0x2E, Shift = 0x10, Insert = 0x2D, Home = 0x24, End = 0x23, Pause = 0x13,
             ScrollLock = 0x91, Ctrl = 0x11, Enter = 0x0D, Backspace = 0x08, Escape = 0x1B }
for n = 1, 12 do VK['F' .. n] = 0x6F + n end
for n = 0, 9 do VK['Key' .. n] = 0x30 + n end

local function key_down(vk) return user.GetAsyncKeyState(vk) < 0 end

-- Typing (preset names): the keys that can make a character (space, digits, letters, numpad,
-- punctuation), turned into text by the player's keyboard layout with Shift, Caps Lock and
-- AltGr as they are. '#' is left out (it starts a comment in the preset files).
local TEXT_KEYS = { 0x20, 0xE2 }
for vk = 0x30, 0x39 do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0x41, 0x5A do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0x60, 0x6F do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0xBA, 0xC0 do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0xDB, 0xDF do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for _, vk in ipairs(TEXT_KEYS) do VK['T' .. vk] = vk end
local key_char
do
    local key_state, key_text = nil, nil

    local function utf8_char(c)
        if c < 0x80 then return string.char(c) end
        if c < 0x800 then return string.char(0xC0 + math.floor(c / 64), 0x80 + c % 64) end
        return string.char(0xE0 + math.floor(c / 4096), 0x80 + math.floor(c / 64) % 64, 0x80 + c % 64)
    end

    key_char = function(vk)
        if not key_state then key_state, key_text = ffi.new('uint8_t[256]'), ffi.new('uint16_t[4]') end
        ffi.fill(key_state, 256)
        for _, k in ipairs({ 0x10, 0x11, 0x12, 0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5 }) do
            if key_down(k) then key_state[k] = 0x80 end
        end
        if user.GetKeyState(0x14) % 2 == 1 then key_state[0x14] = 1 end     -- Caps Lock on (low bit)
        key_state[vk] = 0x80
        -- flag 4: leaves the keyboard's own state (dead keys) alone
        if user.ToUnicode(vk, user.MapVirtualKeyW(vk, 0), key_state, key_text, 4, 4) ~= 1 then return nil end
        local c = key_text[0]
        if c < 32 or c == 35 or c == 127 or (c >= 0xD800 and c < 0xE000) then return nil end
        return utf8_char(c)
    end
end

-- ---------------------------------------------------------------- panel
local sr = nil          -- the engine (stingray)
-- page / fpage: the first row the weapon / full preset list shows (the lists scroll by rows)
local ui = { open = false, measured = {}, measures = 0, tab = 'Primary', page = 1, row = 1, scroll = 1, weapon = nil, hover = nil,
             gui = nil, world = nil, signature = nil, regions = {}, version = 0, errors = 0,
             wslot = 1, fslot = nil, fpage = 1, fopen = {}, closed = {}, fclosed = {}, message = nil,   -- chosen weapon preset / full preset, status line
             editing = nil, confirm = nil,    -- a preset name being typed; an overwrite / delete to confirm
             search = { text = '', active = false },    -- the list's search (active: being typed)
             value = nil }   -- a value being typed: { n = row, weapon, text, fresh (the first key replaces it) }

-- the status line, for code above the panel's
function MOD.notify(text, seconds, warning) ui.message = { text = text, till = api.now() + (seconds or 4), warning = warning } end
local TABS = { 'Primary', 'Secondary', 'Support', 'Throwables', 'Stratagems', 'Mechas', 'Boosters', 'Attachments', 'Armors', 'Records' }
-- the tabs Settings > Tabs shown leaves on
function settings.shown_tabs()
    if MOD.enemy.on then return MOD.enemy.TABS end
    local list = {}
    for _, tab in ipairs(TABS) do if not settings.hidden[tab] then list[#list + 1] = tab end end
    return list
end
local LIST_ROWS = 27
local W, H = 1000, 980       -- panel size in its own units

