                                    service.last={id=id,source=source,owner=owner,hash=hash,speed=speed}
                                    processed=processed+1
                                end
                            end
                        end
                        if service.seen[id]~=true and service.seen[id]>=8 then
                            service.seen[id]=true;service.refused=service.refused+1
                        end
